let expect_ok = function
  | Ok value -> value
  | Error (err : Lg.Compiler.compile_error) ->
      failwith ("expected successful compilation, got: " ^ err.message)

let expect_error expected = function
  | Ok value ->
      failwith ("expected compilation error, got OCaml output:\n" ^ value)
  | Error (err : Lg.Compiler.compile_error) ->
      if err.message <> expected then
        failwith
          (Printf.sprintf "expected error %S, got %S" expected err.message)

let expect_error_value expected = function
  | Ok _ -> failwith "expected compilation error, got successful result"
  | Error (err : Lg.Compiler.compile_error) ->
      if err.message <> expected then
        failwith
          (Printf.sprintf "expected error %S, got %S" expected err.message)

let string_contains_substring text expected =
  let expected_len = String.length expected in
  let rec loop index =
    index + expected_len <= String.length text
    && (String.sub text index expected_len = expected || loop (index + 1))
  in
  expected_len = 0 || loop 0

let substring_from text marker =
  let marker_len = String.length marker in
  let rec find index =
    if index + marker_len > String.length text then None
    else if String.sub text index marker_len = marker then
      Some (String.sub text index (String.length text - index))
    else find (index + 1)
  in
  find 0

let count_substring text expected =
  let expected_len = String.length expected in
  let rec loop count index =
    if expected_len = 0 || index + expected_len > String.length text then count
    else if String.sub text index expected_len = expected then
      loop (count + 1) (index + expected_len)
    else loop count (index + 1)
  in
  loop 0 0

let count_generated_anonymous_record_types source =
  let anonymous_type_name line =
    let words =
      line |> String.split_on_char ' '
      |> List.filter (fun word -> word <> "")
    in
    let rec before_equals previous = function
      | "=" :: _ -> previous
      | word :: rest -> before_equals (Some word) rest
      | [] -> None
    in
    match words with
    | "type" :: "nonrec" :: rest -> before_equals None rest
    | _ -> None
  in
  source |> String.split_on_char '\n'
  |> List.fold_left
       (fun count line ->
         match anonymous_type_name line with
         | Some name
           when String.length name > 1 && name.[0] = 't'
                && name.[1] >= '0' && name.[1] <= '9' ->
             count + 1
         | Some _ | None -> count)
       0

let maximum_line_length source =
  source |> String.split_on_char '\n'
  |> List.fold_left (fun longest line -> max longest (String.length line)) 0

let substring_index text expected =
  let expected_len = String.length expected in
  let rec loop index =
    if index + expected_len > String.length text then None
    else if String.sub text index expected_len = expected then Some index
    else loop (index + 1)
  in
  if expected_len = 0 then Some 0 else loop 0

let expect_substring_index text expected =
  match substring_index text expected with
  | Some index -> index
  | None -> failwith (Printf.sprintf "expected %S in source" expected)

let expect_error_contains expected = function
  | Ok _ -> failwith "expected compilation error, got successful result"
  | Error (err : Lg.Compiler.compile_error) ->
      if not (string_contains_substring err.message expected) then
        failwith
          (Printf.sprintf "expected error containing %S, got %S" expected
             err.message)

let expect_error_location ?start_column ?end_column expected_line = function
  | Ok _ -> failwith "expected compilation error, got successful result"
  | Error ({ location = None; _ } : Lg.Compiler.compile_error) ->
      failwith "expected compilation error with a source location"
  | Error ({ location = Some location; _ } : Lg.Compiler.compile_error) ->
      let start = location.loc_start in
      let finish = location.loc_end in
      let actual_start_column = start.pos_cnum - start.pos_bol in
      let actual_end_column = finish.pos_cnum - finish.pos_bol in
      if start.pos_lnum <> expected_line then
        failwith
          (Printf.sprintf "expected error on line %d, got line %d" expected_line
             start.pos_lnum);
      Option.iter
        (fun expected ->
          if actual_start_column <> expected then
            failwith
              (Printf.sprintf "expected start column %d, got %d" expected
                 actual_start_column))
        start_column;
      Option.iter
        (fun expected ->
          if actual_end_column <> expected then
            failwith
              (Printf.sprintf "expected end column %d, got %d" expected
                 actual_end_column))
        end_column

let typecheck_items source =
  match Lg.Lexer.tokenize source with
  | Error (err : Lg.Error.t) ->
      failwith ("expected successful lexing, got: " ^ err.message)
  | Ok tokens -> (
      match Lg.Parser.parse tokens with
      | Error (err : Lg.Error.t) ->
          failwith ("expected successful parsing, got: " ^ err.message)
      | Ok forms -> Lg.Typecheck.compile_forms forms |> expect_ok)

let typecheck_state source =
  match Lg.Lexer.tokenize source with
  | Error (err : Lg.Error.t) -> failwith err.message
  | Ok tokens -> (
      match Lg.Parser.parse tokens with
      | Error (err : Lg.Error.t) -> failwith err.message
      | Ok forms ->
          Lg.Typecheck.compile_forms_incremental Lg.Typecheck.empty_state forms
          |> expect_ok |> fst)

let expect_structured_value_expression source =
  let rec find_value_expression = function
    | [] -> None
    | Lg.Lowered.Value_binding { expression; _ } :: _ -> Some expression
    | Lg.Lowered.Group items :: rest -> (
        match find_value_expression items with
        | Some _ as expression -> expression
        | None -> find_value_expression rest)
    | _ :: rest -> find_value_expression rest
  in
  match typecheck_items source |> find_value_expression with
  | Some _ -> ()
  | None -> failwith "expected a value binding"

let assert_equal_string expected actual =
  if actual <> expected then
    failwith (Printf.sprintf "expected:\n%s\nactual:\n%s" expected actual)

let write_file path contents =
  let oc = open_out path in
  Fun.protect
    ~finally:(fun () -> close_out_noerr oc)
    (fun () -> output_string oc contents)

let rec find_repo_root_opt dir =
  if Sys.file_exists (Filename.concat dir "dune-project") then Some dir
  else
    let parent = Filename.dirname dir in
    if parent = dir then None else find_repo_root_opt parent

let repo_root () =
  let cwd = Sys.getcwd () in
  match find_repo_root_opt cwd with
  | Some root -> root
  | None -> cwd

let build_root () =
  let root = repo_root () in
  if Sys.file_exists (Filename.concat root "dune-project") then
    Filename.concat root "_build/default"
  else root

let compiler_source_path path = Filename.concat (repo_root ()) path

let rrbvec_build_dir () =
  Filename.concat (build_root ()) "vendor/rrbvec"

let rrbvec_cmi_dir () =
  Filename.concat (rrbvec_build_dir ()) ".rrbvec.objs/byte"

let lg_build_dir () = Filename.concat (build_root ()) "src"

let lg_runtime_build_dir () =
  Filename.concat (build_root ()) "runtime"

let lg_edn_backend_native_build_dir () =
  Filename.concat (build_root ()) "runtime_edn_backend_native"

let lg_byte_cmi_dir () = Filename.concat (lg_build_dir ()) ".lg.objs/byte"
let lg_runtime_byte_cmi_dir () =
  Filename.concat (lg_runtime_build_dir ()) ".lg_runtime.objs/byte"

let lg_edn_backend_native_cmi_dir () =
  Filename.concat (lg_edn_backend_native_build_dir ())
    ".lg_edn_backend_native.objs/byte"

let compiler_test_runner () =
  Filename.concat (build_root ()) "test/compiler_test_runner.bc.exe"

type compile_job = { name : string; ocaml_source : string }

type run_job = {
  name : string;
  expected_output : string;
  ocaml_source : string;
}

let pending_compile_jobs = ref []
let pending_run_jobs = ref []

let time_phase label fn =
  let started = Unix.gettimeofday () in
  let result = fn () in
  if Sys.getenv_opt "LG_TEST_TIMING" = Some "1" then
    Printf.eprintf "%s: %.3fs\n%!" label (Unix.gettimeofday () -. started);
  result

let test_directory = lazy (Filename.temp_dir "lg-tests-" "")

let test_dir () = Lazy.force test_directory

let test_test_directory_avoids_existing_pid_directory () =
  let legacy_dir =
    Filename.concat (Filename.get_temp_dir_name ())
      ("lg-tests-" ^ string_of_int (Unix.getpid ()))
  in
  let created = not (Sys.file_exists legacy_dir) in
  if created then Unix.mkdir legacy_dir 0o755;
  let sentinel = Filename.concat legacy_dir "stale-build-artifact" in
  Fun.protect
    ~finally:(fun () ->
      if Sys.file_exists sentinel then Sys.remove sentinel;
      if created && Sys.file_exists legacy_dir then Unix.rmdir legacy_dir)
    (fun () ->
      write_file sentinel "stale";
      let actual = test_dir () in
      if actual = legacy_dir then
        failwith "compiler tests must not reuse an existing PID directory";
      if not (Sys.file_exists actual && Sys.is_directory actual) then
        failwith "compiler test directory must be created before use";
      if Sys.file_exists (Filename.concat actual "stale-build-artifact") then
        failwith "compiler test directory must not contain stale artifacts")

let compile_only_command dir ml_path =
  Printf.sprintf
    "cd %s && ocamlfind ocamlc -package melange-edn-native,re,unix -w -11-26 -I %s -I %s -I %s -I %s \
     -I %s -I %s -I %s -c %s"
    (Filename.quote dir)
    (Filename.quote (rrbvec_build_dir ()))
    (Filename.quote (rrbvec_cmi_dir ()))
    (Filename.quote (lg_build_dir ()))
    (Filename.quote (lg_byte_cmi_dir ()))
    (Filename.quote (lg_runtime_build_dir ()))
    (Filename.quote (lg_runtime_byte_cmi_dir ()))
    (Filename.quote (lg_edn_backend_native_cmi_dir ()))
    (Filename.quote (Filename.basename ml_path))

let run_compiled_module_command dir cmo_paths output_path =
  Printf.sprintf
    "cd %s && %s %s > %s"
    (Filename.quote dir)
    (Filename.quote (compiler_test_runner ()))
    (String.concat " "
       (List.map
          (fun path -> Filename.quote (Filename.basename path))
          cmo_paths))
    (Filename.quote output_path)

let compile_job_immediately ?(prelude = "") (job : compile_job) =
  let dir = test_dir () in
  let ml_path = Filename.concat dir (job.name ^ ".ml") in
  write_file ml_path (String.concat "\n" [ prelude; job.ocaml_source ]);
  match Sys.command (compile_only_command dir ml_path) with
  | 0 -> ()
  | code ->
      failwith
        (Printf.sprintf "generated OCaml did not compile, exit code %d:\n%s"
           code job.ocaml_source)

let read_file path =
  let ic = open_in path in
  Fun.protect
    ~finally:(fun () -> close_in_noerr ic)
    (fun () ->
      let length = in_channel_length ic in
      really_input_string ic length)

let stdlib_sources =
  let cached =
    lazy
      ([
         "stdlib/clojure/core.lgi";
         "stdlib/clojure/core.cljc";
         "stdlib/clojure/string.lgi";
         "stdlib/clojure/string.cljc";
         "stdlib/clojure/edn.lgi";
         "stdlib/clojure/edn.cljc";
         "stdlib/cljs/reader.lgi";
         "stdlib/cljs/reader.cljc";
         "stdlib/clojure/set.lgi";
         "stdlib/clojure/set.cljc";
         "stdlib/clojure/data.lgi";
         "stdlib/clojure/data.cljc";
         "stdlib/clojure/walk.lgi";
         "stdlib/clojure/walk.cljc";
         "stdlib/clojure/zip.lgi";
         "stdlib/clojure/zip.cljc";
         "stdlib/cljs/cache.cljc";
         "stdlib/cljs/pprint.lgi";
         "stdlib/cljs/pprint.cljc";
         "stdlib/cljs/test.lgi";
         "stdlib/cljs/test.cljc";
       ]
      |> List.map (fun path ->
             (path, read_file (compiler_source_path path))))
  in
  fun () -> Lazy.force cached

type compiled_stdlib = {
  state : Lg.Compiler.state;
  ocaml_source : string;
}

let compiled_stdlib_cache = ref []

let compiled_stdlib target =
  let target_name = Lg.Target.to_string target in
  match List.assoc_opt target_name !compiled_stdlib_cache with
  | Some cached -> cached
  | None ->
      let state, reversed_outputs =
        List.fold_left
          (fun (state, outputs) (source_filename, source_text) ->
            let state, output =
              match
                Lg.Compiler.compile_chunk_with_filename ~target
                  ~filename:source_filename state source_text
              with
              | Ok compiled -> compiled
              | Error (error : Lg.Compiler.compile_error) ->
                  let location =
                    match error.location with
                    | Some location ->
                        ":" ^ string_of_int location.loc_start.pos_lnum
                    | None -> ""
                  in
                  failwith
                    ("failed to compile " ^ source_filename ^ location ^ ": "
                   ^ error.message)
            in
            (state, output :: outputs))
          (Lg.Compiler.empty_state, []) (stdlib_sources ())
      in
      let cached =
        {
          state = Lg.Compiler.with_source_scope "" state;
          ocaml_source =
            reversed_outputs |> List.rev |> String.concat "\n";
        }
      in
      compiled_stdlib_cache :=
        (target_name, cached) :: !compiled_stdlib_cache;
      cached

let compile_with_stdlib target filename source =
  let stdlib = compiled_stdlib target in
  let _, output =
    Lg.Compiler.compile_chunk_with_filename ~target ~filename stdlib.state
      source
    |> expect_ok
  in
  output

let compile_with_stdlib_result target filename source =
  let stdlib = compiled_stdlib target in
  Lg.Compiler.compile_chunk_with_filename ~target ~filename stdlib.state source
  |> Result.map snd

let compile_string_with_stdlib ?(target = Lg.Target.default) source =
  let stdlib = compiled_stdlib target in
  Lg.Compiler.compile_chunk_with_filename ~target
    ~filename:"test/source_core_program.cljc" stdlib.state source
  |> Result.map snd

let compile_string_from_stdlib ?(target = Lg.Target.default) source =
  let stdlib = compiled_stdlib target in
  Lg.Compiler.compile_chunk_with_filename ~target
    ~filename:"test/source_core_program.cljc" stdlib.state source
  |> Result.map snd

let stdlib_state target = (compiled_stdlib target).state

module Raw_lg = Lg

module Lg = struct
  include Raw_lg

  module Compiler = struct
    include Raw_lg.Compiler

    let compile_string ?(target = Target.default) source =
      compile_string_from_stdlib ~target source

    let compile_parsetree ?(target = Target.default) source =
      let stdlib = compiled_stdlib target in
      Raw_lg.Compiler.compile_chunk_parsetree ~target stdlib.state source
      |> Result.map snd

    let compile_parsetree_with_filename ?(target = Target.default) ~filename
        source =
      let stdlib = compiled_stdlib target in
      Raw_lg.Compiler.compile_chunk_parsetree_with_filename ~target ~filename
        stdlib.state source
      |> Result.map snd
  end

  module Toolchain = struct
    include Raw_lg.Toolchain

    let analyze ?(target = Target.default) ?(filename = "<string>") source =
      let stdlib = compiled_stdlib target in
      Raw_lg.Toolchain.analyze_from_state ~target ~filename stdlib.state source
  end

  module Language_service = struct
    include Raw_lg.Language_service

    let analyze ~filename source =
      let stdlib = compiled_stdlib Target.Native in
      Raw_lg.Language_service.analyze_from_state ~filename stdlib.state source

    let analyze_workspace sources =
      let stdlib = compiled_stdlib Target.Native in
      Raw_lg.Language_service.analyze_workspace_from_state stdlib.state sources
  end
end

let compile_chunks_with_stdlib target sources =
  let stdlib = compiled_stdlib target in
  let _, reversed_outputs =
    List.fold_left
      (fun (state, outputs) (source_filename, source_text) ->
        let state, output =
          Lg.Compiler.compile_chunk_with_filename ~target
            ~filename:source_filename state source_text
          |> expect_ok
        in
        (state, output :: outputs))
      (stdlib.state, [ stdlib.ocaml_source ]) sources
  in
  reversed_outputs |> List.rev |> String.concat "\n"

let test_workspace_order_follows_namespace_requires () =
  let stdlib = compiled_stdlib Lg.Target.Native in
  let sources =
    [
      ( "app/a_consumer.cljc",
        {|
(ns app.consumer
  (:require [app.z-provider :as provider]))

(def answer (provider/value))
|} );
      ( "app/z_provider.cljc",
        {|
(ns app.z-provider)

(defn value [] 42)
|} );
    ]
  in
  match
    Raw_lg.Toolchain.order_workspace_from_state ~target:Lg.Target.Native
      stdlib.state sources
  with
  | Ok [ "app/z_provider.cljc"; "app/a_consumer.cljc" ] -> ()
  | Ok ordered ->
      failwith
        ("expected provider before consumer, got: "
        ^ String.concat ", " ordered)
  | Error err ->
      failwith
        ("expected namespace require ordering to compile, got: "
        ^ err.message)

let test_compiler_tests_reuse_precompiled_stdlib_state () =
  let first = compiled_stdlib Lg.Target.Native in
  let second = compiled_stdlib Lg.Target.Native in
  if first != second then
    failwith "compiler tests must reuse one precompiled stdlib state per target";
  Lg.Compiler.compile_string {|(str "source-core")|} |> expect_ok |> ignore;
  Raw_lg.Compiler.compile_string {|(str "raw-core")|}
  |> expect_error "unknown function str"

let rec files_with_suffix suffix directory =
  Sys.readdir directory |> Array.to_list
  |> List.concat_map (fun name ->
         let path = Filename.concat directory name in
         if Sys.is_directory path then files_with_suffix suffix path
         else if Filename.check_suffix path suffix then [ path ]
         else [])

let test_lg_signature_sidecars_use_lgi_extension () =
  let roots =
    [ "stdlib" ]
    |> List.map (Filename.concat (repo_root ()))
  in
  let legacy = List.concat_map (files_with_suffix ".mil") roots in
  if legacy <> [] then
    failwith
      ("LG signature sidecars must use .lgi, found legacy .mil files: "
      ^ String.concat ", " legacy);
  let lg_syntax_mli =
    roots
    |> List.concat_map (files_with_suffix ".mli")
    |> List.filter (fun path ->
           let source = read_file path |> String.trim in
           [ "(ns "; "(signature "; "(type "; "(type-record ";
             "(type-variant " ]
           |> List.exists (fun prefix ->
                  String.starts_with ~prefix source))
  in
  if lg_syntax_mli <> [] then
    failwith
      (".mli files must use OCaml syntax; move LG signature forms to .lgi: "
      ^ String.concat ", " lg_syntax_mli);
  if
    not
      (Sys.file_exists
         (Filename.concat (repo_root ()) "stdlib/clojure/core.lgi"))
  then failwith "missing stdlib/clojure/core.lgi LG signature sidecar"

let rec source_files_under directory =
  Sys.readdir directory |> Array.to_list
  |> List.concat_map (fun name ->
         let path = Filename.concat directory name in
         if Sys.is_directory path then source_files_under path
         else if Filename.check_suffix path ".ml" then [ path ]
         else [])

let wrapped_module index source =
  Printf.sprintf "module Case_%04d = struct\n%s\nend\n" index source

let native_stdlib_prelude () = (compiled_stdlib Lg.Target.Native).ocaml_source

let strip_native_stdlib_prelude source =
  let prelude = native_stdlib_prelude () in
  if String.starts_with ~prefix:prelude source then
    let offset = String.length prelude in
    let offset =
      if offset < String.length source && source.[offset] = '\n' then offset + 1
      else offset
    in
    String.sub source offset (String.length source - offset)
  else source

let flush_compile_jobs (jobs : compile_job list) =
  match jobs with
  | [] -> ()
  | _ -> (
      let dir = test_dir () in
      let ml_path = Filename.concat dir "compile_batch.ml" in
      let source =
        String.concat "\n"
          [
            native_stdlib_prelude ();
            (jobs
            |> List.mapi (fun index (job : compile_job) ->
                   wrapped_module index job.ocaml_source)
            |> String.concat "\n");
          ]
      in
      write_file ml_path source;
      match Sys.command (compile_only_command dir ml_path) with
      | 0 -> ()
      | code ->
          List.iter
            (compile_job_immediately ~prelude:(native_stdlib_prelude ()))
            jobs;
          failwith
            (Printf.sprintf
               "batched generated OCaml failed with exit code %d, but isolated \
                cases passed"
               code))

let run_marker phase index = Printf.sprintf "__LG_TEST_%s_%04d__\n" phase index

let wrapped_run_module index (job : run_job) =
  Printf.sprintf
    "let () =\n  print_string %S;\n  try\n    let module Case_%04d = struct\n%s\nend in\n    \
     print_string %S\n  with exn ->\n    prerr_endline (\"FAILED RUN JOB: \" ^ %S);\n    raise exn\n"
    (run_marker "BEGIN" index)
    index job.ocaml_source (run_marker "END" index) job.name

let chunks_of count values =
  let rec take remaining taken values =
    if remaining = 0 then (List.rev taken, values)
    else
      match values with
      | [] -> (List.rev taken, [])
      | value :: rest -> take (remaining - 1) (value :: taken) rest
  in
  let rec chunks accumulated values =
    match values with
    | [] -> List.rev accumulated
    | _ ->
        let chunk, rest = take count [] values in
        chunks (chunk :: accumulated) rest
  in
  chunks [] values

let compile_commands_in_parallel commands =
  let compile_group commands =
    flush_all ();
    let pids =
      List.map
        (fun command ->
          match Unix.fork () with
          | 0 -> exit (Sys.command command)
          | pid -> pid)
        commands
    in
    List.for_all
      (fun pid ->
        match snd (Unix.waitpid [] pid) with
        | Unix.WEXITED 0 -> true
        | Unix.WEXITED _ | Unix.WSIGNALED _ | Unix.WSTOPPED _ -> false)
      pids
  in
  commands |> chunks_of 8 |> List.for_all compile_group

let flush_run_jobs (jobs : run_job list) =
  match jobs with
  | [] -> ()
  | _ -> (
      let dir = test_dir () in
      let output_path = Filename.concat dir "run_batch.out" in
      let batches = chunks_of 64 jobs in
      let batch_files =
        batches
        |> List.mapi (fun batch_index jobs ->
               let basename = Printf.sprintf "run_batch_%03d" batch_index in
               let ml_path = Filename.concat dir (basename ^ ".ml") in
               let cmo_path = Filename.concat dir (basename ^ ".cmo") in
              let source =
                 String.concat "\n"
                   [
                     native_stdlib_prelude ();
                     (jobs
                     |> List.mapi wrapped_run_module
                     |> String.concat "\n");
                   ]
               in
               write_file ml_path source;
               (cmo_path, compile_only_command dir ml_path))
      in
      let expected =
        batches
        |> List.concat_map (fun jobs ->
               jobs
               |> List.mapi (fun index job ->
                      ignore job.name;
                      run_marker "BEGIN" index ^ job.expected_output
                      ^ run_marker "END" index))
        |> String.concat ""
      in
      let cmo_paths = List.map fst batch_files in
      let compile_commands = List.map snd batch_files in
      let run_cmd = run_compiled_module_command dir cmo_paths output_path in
      if not (compile_commands_in_parallel compile_commands) then (
        batches
        |> List.concat
        |> List.iteri (fun index job ->
               let basename = Printf.sprintf "run_isolated_%04d" index in
               let ml_path = Filename.concat dir (basename ^ ".ml") in
               write_file ml_path
                 (String.concat "\n"
                    [ native_stdlib_prelude (); wrapped_run_module 0 job ]);
               if Sys.command (compile_only_command dir ml_path) <> 0 then
                 Printf.eprintf "FAILED GENERATED COMPILE: %s\n%!" job.name);
        failwith "batched generated OCaml failed")
      else
        match Sys.command run_cmd with
        | code when code <> 0 ->
            failwith
              (Printf.sprintf
                 "batched generated module failed with exit code %d" code)
        | _ -> (
          let actual = read_file output_path in
          if actual <> expected then
            let indexed_jobs =
              batches
              |> List.concat_map (fun jobs -> List.mapi (fun index job -> (index, job)) jobs)
            in
            let starts_with_at text offset prefix =
              offset + String.length prefix <= String.length text
              && String.sub text offset (String.length prefix) = prefix
            in
            let find_from text offset pattern =
              let rec loop index =
                if index + String.length pattern > String.length text then None
                else if starts_with_at text index pattern then Some index
                else loop (index + 1)
              in
              loop offset
            in
            let rec compare_jobs offset mismatches = function
              | [] ->
                  let mismatches =
                    if offset = String.length actual then mismatches
                    else
                      Printf.sprintf "unexpected trailing data: %S"
                        (String.sub actual offset (String.length actual - offset))
                      :: mismatches
                  in
                  if mismatches <> [] then
                    failwith
                      ("generated output mismatches:\n"
                      ^ String.concat "\n" (List.rev mismatches))
              | (index, (job : run_job)) :: rest ->
                  let begin_marker = run_marker "BEGIN" index in
                  let end_marker = run_marker "END" index in
                  if not (starts_with_at actual offset begin_marker) then
                    failwith
                      (Printf.sprintf
                         "batched generated output lost marker before %s" job.name)
                  else
                    let content_start = offset + String.length begin_marker in
                    (match find_from actual content_start end_marker with
                    | None ->
                        failwith
                          (Printf.sprintf
                             "batched generated output lost end marker for %s"
                             job.name)
                    | Some content_end ->
                        let output =
                          String.sub actual content_start
                            (content_end - content_start)
                        in
                        let mismatches =
                          if output = job.expected_output then mismatches
                          else
                            Printf.sprintf "%s: expected %S, got %S" job.name
                              job.expected_output output
                            :: mismatches
                        in
                        compare_jobs
                          (content_end + String.length end_marker)
                          mismatches rest)
            in
            compare_jobs 0 [] indexed_jobs))

let assert_ocaml_compiles name ocaml_source =
  pending_compile_jobs :=
    { name; ocaml_source = strip_native_stdlib_prelude ocaml_source }
    :: !pending_compile_jobs

let assert_ocaml_runs name expected_output ocaml_source =
  pending_run_jobs :=
    {
      name;
      expected_output;
      ocaml_source = strip_native_stdlib_prelude ocaml_source;
    }
    :: !pending_run_jobs

