let test_source_record_step_function_needs_no_sidecar_signature () =
  let source =
    {|
(ns app.ref-text)

(type-record text-step
  (step-index :int)
  (step-result :string))

(defn text-step [^:int index ^:string result]
  (record text-step
          (step-index index)
          (step-result result)))

(defn char-at [^:string value ^:int index]
  (subs value index (inc index)))

(defn to-text-step [tag-title ref-title title ^:int length ^:int index ^:string result]
  (if (< index length)
    (match (if false None (tag-title title))
      (Some label)
      (text-step (inc index) (str result label (char-at title index)))
      None
      (text-step (inc index) (str result (char-at title index))))
    (text-step index result)))

(defn to-text [tag-title ref-title title]
  (let [length (count title)]
    (loop [index 0
           result ""]
      (if (>= index length)
        result
        (let [step (to-text-step tag-title ref-title title length index result)]
          (recur (:step-index step) (:step-result step)))))))

(println (to-text (fn [value] (Some value)) (fn [_] None) "A"))
|}
  in
  let native =
    compile_with_stdlib Lg.Target.Native "app/ref_text_without_lgi.cljc" source
  in
  assert_ocaml_runs "source_record_step_function_needs_no_sidecar_signature"
    "AA\n" native;
  ignore
    (compile_with_stdlib Lg.Target.Melange "app/ref_text_without_lgi.cljc"
       source)

let flush_ocaml_jobs () =
  let compile_jobs = List.rev !pending_compile_jobs in
  let run_jobs = List.rev !pending_run_jobs in
  pending_compile_jobs := [];
  pending_run_jobs := [];
  time_phase "generated compile batch" (fun () ->
      flush_compile_jobs compile_jobs);
  time_phase "generated run batch" (fun () -> flush_run_jobs run_jobs)

