(deftype Datom [value ignored]
  IEquiv
  (-equiv [_ other]
    (and (instance? Datom other)
         (= value (.-value other)))))
(defn same-index? [^:vector<Datom> left ^:vector<Datom> right]
  (loop [xs (seq left)
         ys (seq right)]
    (cond
      (nil? xs) (nil? ys)
      (= (first xs) (first ys)) (recur (next xs) (next ys))
      :else false)))
(def left (Datom. 42 (fn [] :left)))
(def right (Datom. 42 (fn [] :right)))
(println (same-index? [left] [right]))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs
    "generic_sequence_element_equality_avoids_host_function_compare"
    "true\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_seq_instance_validation_rejects_heterogeneous_storage () =
  let source =
    {|
(deftype Datom [value])
(defn datom? [value] (instance? Datom value))
(defn first-invalid-datom [datoms]
  (first (drop-while datom? datoms)))
(println (vector? (first-invalid-datom [[:not-a-datom] {:not-a-datom true}])))
|}
  in
  compile_string_with_stdlib source
  |> expect_error_contains
       "Lg_edn_backend.t Seq.t"

