let test_type_relations_are_explicit_and_strict () =
  if Lg.Types.equal Lg.Types.TUnknown Lg.Types.TInt then
    failwith "unknown must not be strictly equal to int";
  let name = Lg.Types.make_field ":name" Lg.Types.TString in
  let narrow = Lg.Types.TRecord [ name ] in
  let wide =
    Lg.Types.TRecord [ name; Lg.Types.make_field ":age" Lg.Types.TInt ]
  in
  if not (Lg.Types.row_compatible ~expected:narrow ~actual:wide) then
    failwith "wider structural records must remain row-compatible";
  let generated =
    Lg.Types.named_record ~type_name:"t1" ~set_module_name:"Set_t1"
      [ name; Lg.Types.make_field ":age" Lg.Types.TInt ]
  in
  if not (Lg.Types.row_compatible ~expected:narrow ~actual:generated) then
    failwith "generated records must remain row-compatible with structural rows";
  if
    not
      (Lg.Types.defer_to_ocaml ~expected:(Lg.Types.TOcaml "user_id")
         ~actual:Lg.Types.TInt)
  then failwith "opaque OCaml relationships must be explicitly deferred";
  let source_option = Lg.Types.TNullable Lg.Types.TInt in
  let host_option =
    Lg.Types.TOcaml_app ("option", [ Lg.Types.TInt ])
  in
  if
    not
      (Lg.Types.assignable ~policy:Lg.Types.Host_boundary
         ~expected:source_option ~actual:host_option
      && Lg.Types.assignable ~policy:Lg.Types.Host_boundary
           ~expected:host_option ~actual:source_option)
  then
    failwith
      "source nullability and host option must meet explicitly at the host boundary";
  if
    Lg.Types.assignable ~policy:Lg.Types.Nominal ~expected:source_option
      ~actual:host_option
    || Lg.Types.assignable ~policy:Lg.Types.Nominal ~expected:host_option
         ~actual:source_option
  then
    failwith "source nullability must remain distinct from host option semantics"

let test_fresh_anonymous_records_merge_across_branches () =
  let open Lg.Types in
  let field keyword ty = make_field keyword ty in
  let anonymous index fields =
    let type_name = "t" ^ string_of_int index in
    named_record
      ~type_id:(Lg.Type_id.create ~owner:[ "chat.live_sync" ] ~name:type_name)
      ~type_parameters:[ "a" ] ~extensible:true ~type_name
      ~set_module_name:("Set_" ^ type_name) fields
  in
  let left =
    anonymous 22
      [ field ":baseline-t" TUnknown; field ":url" TString ]
  in
  let right =
    anonymous 23
      [ field ":url" TString; field ":baseline-t" TInt ]
  in
  match Lg.Expression_support.merge_branch_types left right with
  | Some (TNamed_record record) ->
      if
        not
          (Lg.Type_id.owner record.type_id = [ "chat.live_sync" ]
          && Lg.Type_id.name record.type_id = "t22")
      then failwith "merged anonymous record should preserve the left branch id";
      (match find_field ":baseline-t" record.fields with
      | Some { ty = TInt; _ } -> ()
      | Some _ -> failwith "merged anonymous record lost concrete field type"
      | None -> failwith "merged anonymous record lost shared field");
      (match record.type_arguments with
      | [ TInt ] -> ()
      | _ -> failwith "merged anonymous record lost concrete type argument")
  | Some _ -> failwith "fresh anonymous branch merge returned a non-record type"
  | None -> failwith "fresh compatible anonymous records must merge across branches"

let test_fresh_anonymous_record_branches_emit_shared_record_type () =
  let source =
    {|
(defn merge-pull-cursor [metadata ok?]
  (try
    (if ok?
      (if-some [t (Some 9)] (assoc metadata :baseline-t t) metadata)
      metadata)
    (catch _ metadata)))

(println (:baseline-t (merge-pull-cursor {:baseline-t 7} true)))
(println (:baseline-t (merge-pull-cursor {:baseline-t 7} false)))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "fresh_anonymous_record_branches_emit_shared_record_type"
    "9\n7\n" native_source;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_type_solver_unifies_sequence_representations () =
  let open Lg.Types in
  let element = seqable_constraint_with_value (TVar "element") (TVar "storage") in
  List.iter
    (fun actual ->
      let variable = Lg.Type_solver.fresh () in
      match Lg.Type_solver.unify Lg.Type_solver.empty (TSeq variable) actual with
      | Error _ -> failwith "sequence representation lost its element type"
      | Ok substitutions ->
          if not (equal element (Lg.Type_solver.apply substitutions variable)) then
            failwith "sequence representation lost its element capability")
    [ next_seq element; TOcaml_app ("Seq.t", [ element ]) ]

let test_type_solver_preserves_shared_and_independent_variables () =
  let open Lg.Types in
  let template =
    TTuple
      [
        TVar "value";
        TFn ([ TVar "value"; TVar "other" ], TVar "other");
      ]
  in
  let actual = TTuple [ TInt; TFn ([ TInt; TString ], TString) ] in
  let substitutions =
    Lg.Type_solver.unify Lg.Type_solver.empty template actual
    |> Result.fold ~ok:Fun.id ~error:(fun _ ->
           failwith "compatible shared constraints must unify")
  in
  if Lg.Type_solver.apply substitutions (TVar "value") <> TInt then
    failwith "shared variables must resolve through every occurrence";
  if Lg.Type_solver.apply substitutions (TVar "other") <> TString then
    failwith "independent variables must retain independent solutions";
  let preserved =
    Lg.Type_solver.unify substitutions (TVar "value") TUnknown
    |> Result.fold ~ok:Fun.id ~error:(fun _ ->
           failwith "unknown evidence must not conflict")
  in
  if Lg.Type_solver.apply preserved (TVar "value") <> TInt then
    failwith "unknown evidence must not erase a concrete solution";
  match
    Lg.Type_solver.unify Lg.Type_solver.empty (TVar "recursive")
      (TVector (TVar "recursive"))
  with
  | Error _ -> ()
  | Ok _ -> failwith "recursive substitutions must fail the occurs check"

let test_type_schemes_distinguish_declared_and_inferred_variables () =
  let open Lg.Types in
  let inferred = Lg.Type_solver.fresh () in
  let inferred_scheme =
    Lg.Type_solver.generalize (TFn ([ inferred ], inferred))
  in
  (match inferred_scheme.quantified with
  | [ Inferred_variable _ ] -> ()
  | _ -> failwith "inferred metavariables must retain their category");
  let declared_scheme =
    Lg.Type_solver.generalize
      (TFn ([ TVar "value"; TVar "value" ], TVar "value"))
  in
  match declared_scheme.quantified with
  | [ Declared_variable "value" ] -> ()
  | _ -> failwith "declared variables must retain their category"

let test_type_scheme_instantiation_preserves_shared_identity () =
  let open Lg.Types in
  let inferred = Lg.Type_solver.fresh () in
  let scheme = Lg.Type_solver.generalize (TFn ([ inferred ], inferred)) in
  let first = Lg.Type_solver.instantiate scheme in
  let second = Lg.Type_solver.instantiate scheme in
  match (first, second) with
  | TFn ([ TMeta first_parameter ], TMeta first_return),
    TFn ([ TMeta second_parameter ], TMeta second_return) ->
      if first_parameter.id <> first_return.id then
        failwith "one instantiation must preserve shared occurrences";
      if second_parameter.id <> second_return.id then
        failwith "one instantiation must preserve shared occurrences";
      if first_parameter.id = second_parameter.id then
        failwith "separate instantiations must use fresh metavariables"
  | _ -> failwith "inferred schemes must instantiate to metavariables"

let test_seqable_constraints_accept_all_sequence_representations () =
  let open Lg.Types in
  let required = seqable_constraint_with_value TInt (TSeq TInt) in
  let same_required = seqable_constraint_with_value TInt (TSeq TInt) in
  let optional = optional_seqable_constraint TInt (TSeq TInt) in
  if not (equal required same_required) then
    failwith "equivalent closed constraints must compare equal";
  if equal required optional then
    failwith "different closed constraint requirements must remain distinct";
  let open_optional = optional_seqable_constraint (Lg.Type_solver.fresh ()) (TVar "left") in
  let generic_optional = optional_seqable_constraint (TVar "value") (TVar "right") in
  if
    not
      (row_compatible ~expected:open_optional ~actual:generic_optional
      && assignable ~policy:Host_boundary ~expected:open_optional
           ~actual:generic_optional)
  then
    failwith
      "closed constraints must recurse through row compatibility and assignability";
  let unify_sequence actual =
    let constraint_ =
      seqable_constraint_with_value (TVar "element") (TVar "storage")
    in
    Lg.Type_solver.unify Lg.Type_solver.empty constraint_ actual
    |> Result.fold ~ok:Fun.id ~error:(fun _ ->
           failwith
             ("seqable constraint rejected " ^ source_name actual))
  in
  let sequence_substitutions = unify_sequence (TSeq TInt) in
  if
    Lg.Type_solver.apply sequence_substitutions (TVar "element") <> TInt
    || Lg.Type_solver.apply sequence_substitutions (TVar "storage")
       <> TSeq TInt
  then failwith "seqable constraint lost ordinary sequence evidence";
  let nonempty = next_seq TInt in
  let nonempty_substitutions = unify_sequence nonempty in
  if
    Lg.Type_solver.apply nonempty_substitutions (TVar "element") <> TInt
    || Lg.Type_solver.apply nonempty_substitutions (TVar "storage") <> nonempty
  then failwith "seqable constraint lost nonempty sequence evidence";
  let signature =
    TFn
      ( [ seqable_constraint_with_value (TVar "value") (TVar "storage") ],
        next_seq (TVar "value") )
  in
  let instantiated = Lg.Type_solver.instantiate (Lg.Type_solver.generalize signature) in
  let expected_call = TFn ([ nonempty ], Lg.Type_solver.fresh ()) in
  match Lg.Type_solver.unify Lg.Type_solver.empty instantiated expected_call with
  | Ok _ -> ()
  | Error _ ->
      failwith
        "generalized seqable function rejected a nonempty sequence argument"

