let test_type_solver_applies_deep_substitutions_linearly () =
  let open Lg.Types in
  let depth = 12_000 in
  let rec nest remaining ty =
    if remaining = 0 then ty else nest (remaining - 1) (TVector ty)
  in
  let rec leaf remaining = function
    | ty when remaining = 0 -> ty
    | TVector inner -> leaf (remaining - 1) inner
    | _ -> failwith "deep substitution changed the type shape"
  in
  let unchanged = TRecord [ make_field ":name" TString ] in
  let template = TTuple [ unchanged; nest depth (TVar "leaf") ] in
  let started_at = Sys.time () in
  let applied =
    Lg.Type_solver.apply
      (Lg.Type_solver.of_list [ (Lg.Type_solver.Declared "leaf", TInt) ])
      template
  in
  let elapsed = Sys.time () -. started_at in
  (match applied with
  | TTuple [ actual_unchanged; nested ] ->
      if not (actual_unchanged == unchanged) then
        failwith "deep substitutions must preserve unchanged subtrees";
      if leaf depth nested <> TInt then
        failwith "deep substitutions must replace the target variable"
  | _ -> failwith "deep substitution changed the root type");
  if elapsed > 0.05 then
    failwith
      (Printf.sprintf
         "deep type substitution must be linear, but took %.3fs" elapsed)

let test_type_solver_preserves_shared_substitution_dags () =
  let open Lg.Types in
  let depth = 24 in
  let rec share remaining ty =
    if remaining = 0 then ty
    else
      let child = share (remaining - 1) ty in
      TTuple [ child; child ]
  in
  let rec leaf remaining = function
    | ty when remaining = 0 -> ty
    | TTuple [ left; right ] ->
        if not (left == right) then
          failwith "substitution must preserve shared type subtrees";
        leaf (remaining - 1) left
    | _ -> failwith "shared substitution changed the type shape"
  in
  let template = share depth (TVar "leaf") in
  let started_at = Sys.time () in
  let applied =
    Lg.Type_solver.apply
      (Lg.Type_solver.of_list [ (Lg.Type_solver.Declared "leaf", TInt) ])
      template
  in
  let elapsed = Sys.time () -. started_at in
  if leaf depth applied <> TInt then
    failwith "shared substitutions must replace the target variable";
  if elapsed > 0.05 then
    failwith
      (Printf.sprintf
         "shared type substitution must be linear, but took %.3fs" elapsed)

let test_type_solver_memo_handles_separated_shared_nodes () =
  let open Lg.Types in
  let rec shared depth =
    if depth = 0 then TVar "leaf"
    else let child = shared (depth - 1) in
      TTuple [ child; TVector TInt; child ]
  in
  let template = shared 17 in
  let before = Gc.allocated_bytes () in
  let result = Lg.Type_solver.apply
      (Lg.Type_solver.of_list [ Lg.Type_solver.Declared "leaf", TString ]) template in
  let allocated = Gc.allocated_bytes () -. before in
  let rec check depth = function
    | TString when depth = 0 -> ()
    | TTuple [ left; TVector TInt; right ] when depth > 0 ->
        if left != right then failwith "separated shared nodes were expanded";
        check (depth - 1) left
    | _ -> failwith "shared substitution changed the result type"
  in
  check 17 result;
  if allocated > 2_000_000. then
    failwith "shared substitution allocated an expanded tree"

let test_type_solver_memo_respects_cycle_context () =
  let open Lg.Types in
  let shared = TList (TVar "y") in
  let substitutions = Lg.Type_solver.of_list
      [ Lg.Type_solver.Declared "x", shared; Lg.Type_solver.Declared "y", shared ] in
  let result = Lg.Type_solver.apply substitutions (TTuple [ TVar "x"; TVar "y" ]) in
  let expected = TTuple [ TList (TList (TVar "y")); TList (TVar "y") ] in
  if result <> expected then
    failwith "substitution memo reused a result from a different cycle context"

let test_type_solver_applies_wide_substitutions_linearly () =
  let open Lg.Types in
  let width = 20_000 in
  let template =
    TRecord
      (List.init width (fun index ->
           make_field (":field-" ^ string_of_int index) (TVar "element")))
  in
  let started_at = Sys.time () in
  let applied =
    Lg.Type_solver.apply
      (Lg.Type_solver.of_list [ (Lg.Type_solver.Declared "element", TInt) ])
      template
  in
  let elapsed = Sys.time () -. started_at in
  (match applied with
  | TRecord fields
    when List.length fields = width
         && List.for_all (fun (field : field) -> field.ty = TInt) fields ->
      ()
  | _ -> failwith "wide substitution changed the type shape");
  if elapsed > 0.10 then
    failwith
      (Printf.sprintf
         "wide type substitution must be linear, but took %.3fs" elapsed)

let test_type_solver_unifies_deep_types_linearly () =
  let open Lg.Types in
  let depth = 4_000 in
  let rec nest remaining leaf =
    if remaining = 0 then leaf else TVector (nest (remaining - 1) leaf)
  in
  let left = nest depth TInt in
  let right = nest depth TInt in
  let started_at = Sys.time () in
  (match
     Lg.Type_solver.infer
       (Lg.Type_solver.of_list
          [ (Lg.Type_solver.Declared "unrelated", TString) ])
       ~template:left ~actual:right
   with
  | Ok _ -> ()
  | Error _ -> failwith "equivalent nested types must unify");
  let elapsed = Sys.time () -. started_at in
  if elapsed > 0.10 then
    failwith
      (Printf.sprintf
         "deep type unification repeatedly traversed nested subtrees: %.3fs"
         elapsed)

let test_type_solver_adds_independent_substitutions_linearly () =
  let open Lg.Types in
  let substitution_count = 3_000 in
  let started_at = Sys.time () in
  let substitutions =
    List.init substitution_count Fun.id
    |> List.fold_left
         (fun substitutions index ->
           Lg.Type_solver.unify substitutions
             (TVar ("value-" ^ string_of_int index)) TInt
           |> Result.fold ~ok:Fun.id ~error:(fun _ ->
                  failwith "independent substitutions must unify"))
         Lg.Type_solver.empty
  in
  let elapsed = Sys.time () -. started_at in
  if
    Lg.Type_solver.apply substitutions
      (TVar ("value-" ^ string_of_int (substitution_count - 1)))
    <> TInt
  then failwith "the latest independent substitution must remain available";
  if elapsed >= 0.1 then
    failwith
      (Printf.sprintf
         "adding independent substitutions must be linear (%.3fs)" elapsed)

let test_type_solver_indexes_independent_substitutions () =
  let open Lg.Types in
