        "declarations" env 0 ("new_" ^ string_of_int i) [] [ make_field ":value" TInt ] with
    | Ok _ -> ()
    | Error _ -> failwith "new independent record declaration failed"
  done;
  if Gc.allocated_bytes () -. before > 3_000_000. then
    failwith "new record declarations scanned unrelated binding types"

let test_record_declaration_refreshes_forward_consumers () =
  let open Lg.Types in
  let scope = "forward_refresh" and name = "item" in
  let type_id = Lg.Type_id.create ~owner:[scope] ~name in
  let stale = named_record ~type_id ~type_name:name ~set_module_name:"Set_item" [] in
  let key = Lg.Resolver.record_type_key scope name in
  let env = Lg.Compiler_environment.of_bindings
      [ key, binding ~forward_declared:true name stale;
        "consumer", binding "consumer" (TFn ([ TNullable stale ], TVector stale)) ] in
  match Lg.Type_definition_elaborator.compile_type_record_fields
      scope env 0 name [] [ make_field ":value" TInt ] with
  | Error _ -> failwith "forward record declaration failed"
  | Ok (_, env, _, _) ->
      match Lg.Compiler_environment.find_opt "consumer" env with
      | Some { ty = TFn ([ TNullable (TNamed_record input) ], TVector (TNamed_record output)); _ }
        when input.fields = [ make_field ":value" TInt ] && output.fields = input.fields -> ()
      | _ -> failwith "record declaration lost a nested forward consumer"

let test_refresh_named_record_realigns_forward_declared_records () =
  let open Lg.Types in
  let fields = [ make_field ":db-before" TUnknown ] in
  let fresh =
    named_record ~type_name:"txreport" ~set_module_name:"txreport_set" fields
  in
  let stale =
    named_record ~type_parameters:[ "value" ] ~type_name:"txreport"
      ~set_module_name:"txreport_set" fields
  in
  (match fresh with
  | TNamed_record fresh_record -> (
      let refreshed =
        refresh_named_record fresh_record (TFn ([ stale ], TNullable stale))
      in
      let expected = TFn ([ fresh ], TNullable fresh) in
      if refreshed <> expected then
        failwith
          ("forward-declared record arguments must realign to the emitted \
            declaration: " ^ source_name refreshed);
      let generic =
        named_record ~type_parameters:[ "value" ] ~type_name:"btset"
          ~set_module_name:"btset_set" fields
      in
      match generic with
      | TNamed_record generic_record ->
          let instantiated =
            TNamed_record { generic_record with type_arguments = [ TInt ] }
          in
          let refreshed = refresh_named_record generic_record instantiated in
          if refreshed <> instantiated then
            failwith
              "matching argument counts must keep the more specific \
               instantiation";
          let refreshed = refresh_named_record generic_record stale in
          if refreshed <> stale then
            failwith "unrelated record shapes must be left alone"
      | _ -> failwith "expected a named record")
  | _ -> failwith "expected a named record")

let test_refresh_named_record_preserves_shared_types () =
  let open Lg.Types in
  let stale = named_record ~type_name:"shared_record"
      ~set_module_name:"shared_record_set" [] in
  let fresh = named_record ~type_name:"shared_record"
      ~set_module_name:"shared_record_set" [make_field ":value" TInt] in
  let rec share depth leaf =
    if depth = 0 then leaf
    else let child = share (depth - 1) leaf in TTuple [child; child]
  in
  match fresh with
  | TNamed_record record ->
      let instance =
        TNamed_record { record with type_arguments = Sys.opaque_identity [] }
      in
      if refresh_named_record record instance != instance then
        failwith "record refresh copied an already current definition";
      let unrelated = share 18 (TVector TString) in
      let before = Gc.allocated_bytes () in
      let unchanged = refresh_named_record record unrelated in
      let allocated = Gc.allocated_bytes () -. before in
      if unchanged != unrelated then
        failwith "record refresh copied an unrelated shared type";
      if allocated > 2_000_000. then
        failwith (Printf.sprintf "record refresh allocated %.0f bytes" allocated);
      let rec check depth = function
        | ty when depth = 0 ->
            if ty <> fresh then failwith "record refresh lost updated fields"
        | TTuple [left; right] ->
            if left != right then failwith "record refresh lost subtree sharing";
            check (depth - 1) left
        | _ -> failwith "record refresh changed the type shape"
      in
      check 18 (refresh_named_record record (share 18 stale));
      let repeated =
        TTuple
          (List.init 20_000
             (fun _ -> TVector (TList (Sys.opaque_identity TString))))
      in
      let started = Sys.time () in
      if refresh_named_record record repeated != repeated then
        failwith "record refresh copied repeated unrelated shapes";
      let elapsed = Sys.time () -. started in
      if elapsed > 0.2 then
        failwith (Printf.sprintf "record refresh hash collisions took %.3fs" elapsed)
  | _ -> assert false

let test_freshen_deferred_dynamic_dispatch_stays_monomorphic () =
  let open Lg.Types in
  let dynamic = dynamic_constraint TUnknown in
  let protocol_id = Lg.Protocol_id.of_string "test/dynamic-dispatch" in
  let dynamic_method = TFn ([ dynamic; dynamic ], dynamic) in
  let dynamic_constraint_ty =
    protocol_constraint protocol_id [ dynamic_method ] TUnknown
  in
  (match
     Lg.Elaborator.freshen_deferred_type (TFn ([ dynamic_constraint_ty ], TInt))
   with
  | TFn ([ refreshed ], TInt) -> (
      match protocol_constraint_info refreshed with
      | Some (_, _, value_ty) ->
          if not (equal value_ty dynamic) then
            failwith
              ("dynamic dispatch must keep the container monomorphic dynamic, \
                got: " ^ source_name value_ty)
      | None -> failwith "expected a protocol constraint")
  | _ -> failwith "expected a deferred function type");
  let generic_method = TFn ([ TUnknown ], TUnknown) in
  let generic_constraint_ty =
    protocol_constraint protocol_id [ generic_method ] TUnknown
  in
  match
    Lg.Elaborator.freshen_deferred_type (TFn ([ generic_constraint_ty ], TInt))
  with
  | TFn ([ refreshed ], TInt) -> (
      match protocol_constraint_info refreshed with
      | Some (_, witness_ty, TVar _) -> (
          match protocol_witness_method_types witness_ty with
          | Some [ TFn ([ receiver_ty ], return_ty) ]
            when (not (is_dynamic receiver_ty))
                 && not (is_dynamic return_ty)
                 && not (equal receiver_ty TUnknown)
                 && not (equal return_ty TUnknown) ->
              ()
          | Some [ method_ty ] ->
              failwith
                ("generic protocol witness positions must remain static type variables, got: "
                ^ source_name method_ty)
          | Some _ | None -> failwith "expected one generic witness method")
      | Some (_, _, value_ty) ->
          failwith
            ("generic receivers must keep freshened polymorphism, got: "
            ^ source_name value_ty)
      | None -> failwith "expected a protocol constraint")
  | _ -> failwith "expected a deferred function type"

let test_freshen_deferred_erased_seqable_values_stay_dynamic () =
  let open Lg.Types in
  let constraints =
    [
      seqable_constraint TUnknown;
      optional_seqable_constraint TUnknown TUnknown;
      optional_sequential_constraint TUnknown TUnknown;
    ]
  in
  List.iter
    (fun constraint_ty ->
      match Lg.Elaborator.freshen_deferred_type (TFn ([ constraint_ty ], TInt)) with
      | TFn ([ refreshed ], TInt) -> (
          match seqable_constraint_info refreshed with
          | Some (_, element_ty, value_ty)
            when is_dynamic element_ty && is_dynamic value_ty -> ()
          | Some (_, element_ty, value_ty) ->
              failwith
                ("deferred erased seqable items and values must stay dynamic, "
               ^ "got: " ^ source_name element_ty ^ " / "
                ^ source_name value_ty)
          | None -> failwith "expected a seqable constraint")
      | _ -> failwith "expected a deferred function type")
    constraints

