let test_generic_function_signatures_preserve_type_parameters () =
  let source =
    {|
(type-record box [value]
  (item :value))
(signature user/read-box [value]
  :fn<box<value>;value>)
(defn read-box [box]
  (:item box))
(def int-box (record box (item 41)))
(def string-box (record box (item "Ada")))
(println (+ (read-box int-box) 1))
(println (read-box string-box))
|}
  in
  let state, ocaml =
    Lg.Compiler.compile_chunk (stdlib_state Lg.Target.Native) source |> expect_ok
  in
  let binding =
    Lg.Compiler_environment.find_opt "read-box" state.typecheck_state.env
    |> Option.get
  in
  (match binding.ty with
  | Lg.Types.TFn
      ( [ Lg.Types.TNamed_record { type_arguments = [ Lg.Types.TVar input ]; _ } ],
        Lg.Types.TVar output )
    when input = output ->
      ()
  | _ ->
      failwith
        ("generic signature must preserve one shared type variable, got "
       ^ Lg.Types.source_name binding.ty));
  if string_contains_substring ocaml "Runtime_dynamic" then
    failwith "generic function signatures must not use Runtime_dynamic";
  assert_ocaml_runs "generic_function_signatures_preserve_type_parameters"
    "42\nAda\n" ocaml

let test_generic_signature_refines_bare_named_record_parameter_hint () =
  let source =
    {|
(ns user)
(signature user/LookupState [key value]
  {:values :map<key;value>
   :index :clojure.core/persistent-tree-map<int;key>
   :reverse-index :map<key;int>
   :generation :int
   :limit :int})
(deftype LookupState [values index reverse-index generation limit])
(signature user/read-value [key value]
  :fn<user/LookupState<key;value>;key;option<value>>)
(signature user/empty-state [key value]
  :fn<int;user/LookupState<key;value>>)
(defn read-value [^LookupState state key]
  (get (.-values state) key))
(defn empty-state [_limit]
  (LookupState. {} (sorted-map) {} 0 16))
(println "ok")
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "generic named record signatures must remain static";
