let test_map_projects_named_record_elements_for_structural_callbacks () =
  let source =
    {|
(ns ocaml-list-map-record-projection
  (:require [ocaml.List :as list]))
(type-record entity
  (db-id :option<int>)
  (attrs :list<tuple<string;int>>))
(type-variant op
  (Many :list<entity>))
(defn attr-count [entity]
