(defn op-counts [operation]
  (match operation
    (Many entities) (list/map (fn [entity] (attr-count entity)) entities)))
(println
  (first
    (op-counts
      (Many
        (list
          (record entity
            (db-id None)
            (attrs (list (tuple "a" 1)))))))))
|}
  in
