let test_generic_call_infers_nested_host_container_for_keyword_callbacks () =
  let source =
    {|
(type-record graph
  (id :string)
  (name :string))
(type-record model
  (graphs :vector<graph>))
(type-record Signal [a]
  (current :a))
(signature signal-map [input output]
  :overload<fn<fn<input;output>;Signal<input>;Signal<output>>;fn<fn<input;input;output>;Signal<input>;Signal<input>;Signal<output>>>)
(defn signal-map
  ([f source]
   (record Signal
     (current (f (:current source)))))
  ([f left right]
   (record Signal
     (current (f (:current left) (:current right))))))
(signature consume [key item]
  :fn<Signal<vector<item>>;fn<item;key>;fn<Signal<item>;string>;string>)
(defn consume [source key-fn child]
  (do source key-fn child "ok"))
(signature make-graph-item :fn<Signal<graph>>)
(defn make-graph-item []
  (record Signal
    (current (record graph
               (id "g1")
               (name "Main")))))
(signature make-graph-signal :fn<Signal<vector<graph>>>)
(defn make-graph-signal []
  (record Signal
    (current [(:current (make-graph-item))])))
(signature make-model-signal :fn<Signal<model>>)
(defn make-model-signal []
  (record Signal
    (current (record model
               (graphs (:current (make-graph-signal)))))))
(signature graph-title :fn<Signal<graph>;string>)
(defn graph-title [source]
  (:name (:current source)))
(defn render []
  (consume (signal-map :graphs (make-model-signal)) :id graph-title))
(type-record other-graph (id :string) (extra :int))
(defn render-id [source]
  (let [title (graph-title source)
        id (signal-map :id source)]
    (str title ":" (:current id))))
(assert (= (render-id (make-graph-item)) "Main:g1"))
|}
  in
  let ocaml = compile_with_stdlib Lg.Target.Native "test/keyword_signal.cljc" source in
  assert_ocaml_runs "generic_call_infers_nested_host_container_for_keyword_callbacks" "" ocaml

let test_core_name_conflicts_require_explicit_exclusion () =
  List.iter (fun definition ->
    let stdlib = compiled_stdlib Lg.Target.Native in
    Lg.Compiler.compile_chunk ~target:Lg.Target.Native stdlib.state
      ("(ns collision-check)\n" ^ definition)
    |> expect_error_contains ":refer-clojure :exclude")
    ["(defn update [current event] (+ current event))";
     "(def first 42)"; "(defn map [x] x)";
     "(defonce first 42)";
     "(def ^:dynamic first 42)";
     "(defmacro update [x] x)"];
  let provider = {|(ns update-model (:refer-clojure :exclude [update])
  (:require [clojure.string :as string]))
(defn update [current event] (+ current event))
|} in
  let wrapper = {|(ns app-wrapper)
(macro-helper-defn wrap-expansion [value]
  `(let [result# ~value] result#))
(defmacro wrap [value] (wrap-expansion value))
|} in
  let consumer = {|(ns update-app (:require [update-model :as model] [app-wrapper :as app]))
(assert (= (app/wrap (model/update 20 22)) 42))
|} in
  let compile target =
    let stdlib = compiled_stdlib target in
    let state, declarations = Lg.Compiler.compile_chunk ~target stdlib.state
      {|(ns update-model (:refer-clojure :exclude [update])) (signature update-model/update :fn<int;int;int>)|} |> expect_ok in
    let state, provider = Lg.Compiler.compile_chunk ~target state provider |> expect_ok in
    let state, wrapper = Lg.Compiler.compile_chunk ~target state wrapper |> expect_ok in
    let state, _ = Lg.Compiler.compile_chunk ~target state
      {|(ns unrelated (:require [clojure.core :as model]))|} |> expect_ok in
    let _, consumer = Lg.Compiler.compile_chunk ~target state consumer |> expect_ok in
    stdlib.ocaml_source ^ "\n" ^ declarations ^ "\n" ^ provider ^ "\n" ^ wrapper ^ "\n" ^ consumer
  in
  assert_ocaml_runs "core_name_conflicts_require_explicit_exclusion" "" (compile Lg.Target.Native);
  ignore (compile Lg.Target.Melange)

let test_lookup_infers_nested_variant_payload () =
  let source = {|
(defn lookup-field [entries key]
  (some (fn [entry] (match entry (tuple name value) (when (= name key) value))) entries))
(defn string-field [entries key]
  (match (lookup-field entries key)
    (Some (tag String value)) value
    (Some (tag Null)) "null"
    _ "missing"))
(println (string-field [(tuple "title" (tag String "hello"))] "title"))
(println (string-field [(tuple "title" (tag String "hello"))] "missing"))
(println (string-field [(tuple "title" (tag Null))] "title"))
(defn tuple-field [entry]
  (match entry
    (tuple (tag Empty) _) "empty"
    (tuple (tag Text value) _) value
    _ "other"))
(println (tuple-field (tuple (tag Empty) 1)))
(println (tuple-field (tuple (tag Text "tuple") 2)))
|} in
  let native = compile_with_stdlib Lg.Target.Native "test/lookup_variant.cljc" source in
  assert_ocaml_runs "lookup_infers_nested_variant_payload" "hello\nmissing\nnull\nempty\ntuple\n" native;
  ignore (compile_with_stdlib Lg.Target.Melange "test/lookup_variant.cljc" source);
  compile_with_stdlib_result Lg.Target.Native "test/closed_nested_variant.cljc" {|
(signature reject-unknown :fn<option<variant<Known:int>>;int>)
(defn reject-unknown [value]
  (match value (Some (tag Unknown payload)) payload _ 0))
|} |> expect_error_contains "Unknown"

