(defn state [runtime] @(:state runtime))
(defn operation [runtime] (:server-t (state runtime)))
(defn stage [runtime value]
  (swap! (:state runtime) assoc :server-t value)
  (:path runtime))
(defn advance [runtime]
  (stage runtime (inc (operation runtime))))

