let test_keyword_callbacks_preserve_mutable_signal_item_types () =
  let source = {|
(ns signal-fixture)
(type-record Row (uuid :string) (depth :int) (is-asset :bool))
(type-record Block (uuid :string) (is-asset :bool))
(type-record Subscriber [value] (callback :fn<value;bool>))
(type-record Signal [value] (current :ref<value>) (subscribers :ref<vector<Subscriber<value>>>))
(type-record Scope (id :int))
(type-record Context (scope :Scope))
(signature sample [value] :fn<Signal<value>;value>)
(defn sample [source] @(:current source))
(signature own [value] :fn<Scope;Signal<value>;Signal<value>>)
(defn own [scope source] source)
(signature signal-map [left right output]
  :overload<fn<fn<left;output>;Signal<left>;Signal<output>>;fn<fn<left;right;output>;Signal<left>;Signal<right>;Signal<output>>>)
(defn signal-map
  ([f source] (record Signal (current (atom (f (sample source)))) (subscribers (atom []))))
  ([f left right] (record Signal (current (atom (f (sample left) (sample right)))) (subscribers (atom [])))))
|} in
  let consumer = {|
(ns signal-consumer (:require [signal-fixture :refer [Row Signal Scope Context sample own signal-map]]))
(defn row-uuid [row] (let [_depth (:depth row)] (:uuid row)))
(defn asset-is? [row expected] (= (:is-asset row) expected))
(defn asset? [row] (asset-is? row true))
(defn render [context ^:signal<row> source]
  (let [row (sample source)
        uuid (own (:scope context) (signal-map row-uuid source))
        keyword-asset (own (:scope context) (signal-map :is-asset source))
        asset (own (:scope context) (signal-map asset? source))]
    (assert (= (sample keyword-asset) (sample asset)))
    (sample asset)))
(def context (record Context (scope (record Scope (id 1)))))
(assert (= (render context (record Signal (current (atom (record Row (uuid "a") (depth 0) (is-asset true)))) (subscribers (atom [])))) true))
(assert (= (render context (record Signal (current (atom (record Row (uuid "b") (depth 0) (is-asset false)))) (subscribers (atom [])))) false))
|} in
  let compile target =
    let stdlib = compiled_stdlib target in
    let state, provider = Lg.Compiler.compile_chunk ~target stdlib.state source |> expect_ok in
    let _, consumer = Lg.Compiler.compile_chunk ~target state consumer |> expect_ok in
    stdlib.ocaml_source ^ "\n" ^ provider ^ "\n" ^ consumer
  in
  let native = compile Lg.Target.Native in
  assert_ocaml_runs "keyword_callbacks_preserve_mutable_signal_item_types" "" native;
  ignore (compile Lg.Target.Melange)

let test_sampled_signals_keep_independent_nominal_payloads () =
  let source = {|
(type-record signal [value] (current :ref<value>))
(type-record chat-model (search-open :bool) (rows :vector<outliner-row>))
(type-record outliner-row (uuid :string) (depth :int))

(signature sample [value] :fn<signal<value>;value>)
(defn sample [source] @(:current source))

(defn row-uuid [row]
  (let [_depth (:depth row)]
    (:uuid row)))

(defn root-visible? [current]
  (not (:search-open current)))

(defn row-visible? [current row]
  (and (root-visible? current)
       (= (row-uuid row) "row-1")))

(defn zoom-control [model-source row-source]
  (let [current (sample model-source)
        row (sample row-source)]
    (if (row-visible? current row)
      (row-uuid row)
      "")))

(def model-source
  (record signal
    (current (atom (record chat-model
                     (search-open false)
                     (rows []))))))

(def row-source
  (record signal
    (current (atom (record outliner-row
                     (uuid "row-1")
                     (depth 0))))))

(println (zoom-control model-source row-source))
|} in
  let output = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "sampled_signals_keep_independent_nominal_payloads" "row-1\n" output;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_chat_migration_fixture_preserves_inferred_rows () =
  let source = {|
(ns chat-migration-fixture (:require [ocaml.String :as bytes]))

(type-record signal [value] (current :ref<value>))
(type-record chat-model (search-open :bool) (rows :vector<outliner-row>))
(type-record outliner-row (uuid :string) (title :string) (depth :int))
(type-record candidate (label :string) (value :string))

(defprotocol RowSource
  (-rows [source]))

(def ^:set<string> empty-labels #{})

(defn sample [source] @(:current source))

(defn row-uuid [row]
  (let [_depth (:depth row)]
    (:uuid row)))

(defn root-visible? [current]
  (not (:search-open current)))

(defn row-visible? [current row]
  (and (root-visible? current)
       (= (row-uuid row) "row-1")))

(defn active-row [model-source row-source]
  (let [current (sample model-source)
        row (sample row-source)]
    (if (row-visible? current row)
      (row-uuid row)
      "")))

(defn duplicated-labels [candidates]
  (let [by-label (group-by #(bytes/lowercase-ascii (:label %)) candidates)]
    (into empty-labels
          (keep (fn [[label values]]
                  (when (> (count (set (map :value values))) 1)
                    label))
                by-label))))

(defn row-candidate [row]
  (record candidate
    (label (:title row))
    (value (:uuid row))))

(defrecord StaticRows [^:vector<outliner-row> rows]
  RowSource
  (-rows [source]
    (filter (fn [row] (not= "" (:uuid row))) (:rows source))))

(def first-row
  (record outliner-row (uuid "row-1") (title "Roadmap") (depth 0)))
(def second-row
  (record outliner-row (uuid "row-2") (title "roadmap") (depth 1)))
(def rows [first-row second-row])
(def model-source
  (record signal
    (current (atom (record chat-model (search-open false) (rows rows))))))
(def row-source (record signal (current (atom first-row))))
(def static-source (StaticRows. rows))

(println (active-row model-source row-source))
(println (contains? (duplicated-labels (mapv row-candidate rows)) "roadmap"))
(println (count (vec (-rows static-source))))
|}
  in
  let native =
    compile_with_stdlib Lg.Target.Native
      "test/chat_migration_fixture.cljc" source
  in
  assert_ocaml_runs "chat_migration_fixture_preserves_inferred_rows"
    "row-1\ntrue\n2\n" native;
  ignore
    (compile_with_stdlib Lg.Target.Melange
       "test/chat_migration_fixture.cljc" source)

let test_sidebar_pages_preserves_entity_summary_rows () =
  let model = {|
(ns sidebar-model)
(type-record entity-summary (uuid :string) (title :string))
|} in
  let graph = {|
(ns sidebar-graph (:require [sidebar-model :as model]))
(type-record sidebar-pages
  (favorites :vector<model/entity-summary>)
  (recent-pages :vector<model/entity-summary>))

(defn page-summary [eid]
  (when (> eid 0)
    (record model/entity-summary (uuid (str eid)) (title (str "page-" eid)))))

(defn sidebar-pages [favorite-eids recent-eids]
  (let [favorites (mapv second
                    (sort-by first
                      (keep (fn [eid]
                              (when-some [page (page-summary eid)]
                                (tuple (str eid) page)))
                            favorite-eids)))
        favorite-uuids (set (map :uuid favorites))
        recent (vec
                 (take 15
                   (keep (fn [eid]
                           (when-some [page (page-summary eid)]
                             (when (not (contains? favorite-uuids (:uuid page)))
                               page)))
                         recent-eids)))]
    (record sidebar-pages
      (favorites favorites)
      (recent-pages recent))))

(def pages (sidebar-pages [1] [1 2]))
(println (str (count (:favorites pages)) ":" (count (:recent-pages pages))))
|}
  in
  let compile target =
    let stdlib = compiled_stdlib target in
    let state, model =
      Lg.Compiler.compile_chunk ~target stdlib.state model |> expect_ok
    in
    let _, graph =
      Lg.Compiler.compile_chunk ~target state graph |> expect_ok
    in
    stdlib.ocaml_source ^ "\n" ^ model ^ "\n" ^ graph
  in
  let native = compile Lg.Target.Native in
  assert_ocaml_runs "sidebar_pages_preserves_entity_summary_rows" "1:1\n"
    native;
  ignore (compile Lg.Target.Melange)

