    (println (db runtime)))
  (println "done"))

(def runtime
  (record graph-runtime
    (state (atom (record runtime-state
                   (snapshot (record snapshot (db "db")))
                   (search-index-is-fresh true))))
    (search-index (Some "index"))))

(refresh-search-affected runtime)
