let test_seqable_inferred_record_rows_accept_wider_nominal_elements () =
  let definitions = {|
(ns record-seqable-width-test)
(type-record candidate (label :string) (value :string))
(type-record indexed-candidate (index :int) (label :string) (value :string))
(defn indexed-candidates [candidates]
  (loop [index 0 result []]
    (if (= index (count candidates)) result
      (let [candidate (nth candidates index)]
        (recur (inc index)
          (conj result (record indexed-candidate
                         (index index) (label (:label candidate)) (value (:value candidate)))))))))
|} in
  let source = definitions ^ {|
(let [candidate (nth (indexed-candidates [(record indexed-candidate (index 9) (label "A") (value "a"))]) 0)]
  (println (str (:index candidate) ":" (:label candidate) ":" (:value candidate))))
|} in
  let native = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "seqable_inferred_record_rows_accept_wider_nominal_elements"
    "0:A:a\n" native;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  List.iter (fun suffix ->
    List.iter (fun target ->
      match compile_string_with_stdlib ~target (definitions ^ suffix) with
      | Error _ -> ()
      | Ok _ -> failwith "record sequence adaptation accepted incompatible elements")
      [ Lg.Target.Native; Lg.Target.Melange ])
    [ {|
(type-record invalid-candidate (label :int) (value :string))
(indexed-candidates [(record invalid-candidate (label 1) (value "a"))])
|}; {|
(defn nominal-candidates [^:seq<candidate> values] (count values))
(nominal-candidates [(record indexed-candidate (index 9) (label "A") (value "a"))])
|} ]
;;

let test_loop_record_accumulators_preserve_nested_result_types () =
  let source = {|
(ns loop-record-test (:require [ocaml.Rrbvec :as rrbvec]))
(type-record row (addr :int))
(defn consume []
  (loop [offset 0 rows []]
    (if (= offset 1)
      (Ok (tuple offset rows))
      (recur 1 (conj rows (record row (addr 7)))))))
(defn feed []
  (let* [[offset rows] (consume)]
    (Ok rows)))
(defn expect-ok [result]
  (match result (Ok value) value (Error message) (Stdlib.failwith message)))
(defn feed-list []
  (let* [[offset rows] (consume)] (Ok (rrbvec/to-list rows))))
(defn combine []
  (loop [offset 0 rows []]
    (if (= offset 1)
      (Ok (tuple offset rows))
      (let* [[next decoded] (consume)]
        (recur next (into rows decoded))))))
(defn feed-argument [parser chunk]
  (let [source (str @parser chunk)]
    (reset! parser source)
    (let* [[offset rows] (combine)]
      (reset! parser (subs source offset))
      (Ok (rrbvec/to-list rows)))))
(defn read-nested []
  (let [parser (atom "x")]
    (let [rows (expect-ok (feed-argument parser ""))]
      (println (pr-str (mapv :addr rows))))))
(defn read-rows []
  (let [rows (expect-ok (feed))]
    (println (pr-str (mapv :addr rows))))
  (let [rows (expect-ok (feed-list))]
    (println (pr-str (mapv :addr rows))))
  (let* [[offset rows] (combine)]
    (println (pr-str (mapv :addr rows)))))
(defn nested []
  (loop [index 0 rows []]
    (if (= index 1)
      rows
      (let [row (loop [attempt 0]
                  (if (= attempt 0) (record row (addr 9)) (recur 0)))]
        (recur 1 (conj rows row))))))
(read-rows)
(read-nested)
(println (pr-str (mapv :addr (nested))))
|} in
  let native = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "loop_record_accumulators_preserve_nested_result_types" "[7]\n[7]\n[7]\n[7]\n[9]\n" native;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  let incompatible = source ^ {|
(defn incompatible []
  (loop [index 0 rows []]
    (if (= index 0)
      (recur 1 (conj rows (record row (addr 7))))
      (if (= index 1) (recur 2 (conj rows "wrong")) rows))))
|} in
  List.iter (fun target ->
    match compile_string_with_stdlib ~target incompatible with
    | Error _ -> ()
    | Ok _ -> failwith "loop accepted incompatible record and string elements")
    [Lg.Target.Native; Lg.Target.Melange]

let test_module_protocols_preserve_typed_registry_state () =
  let state =
    typecheck_state
      {|
(module Labels
  (defprotocol Labelled (label [x] :string))
  (extend-type :int Labelled (label [x] (__lg_str x))))
|}
  in
  let protocol = Lg.Protocol_id.create ~owner:[ "Labels" ] ~name:"Labelled" in
  let method_id =
    Lg.Method_id.create ~owner:[ "Labels"; "Labelled" ] ~name:"label"
  in
  let protocols = Lg.Compiler_environment.protocols state.env in
  if
    Lg.Protocol_registry.find_method protocol method_id protocols = None
    || Lg.Protocol_registry.find_implementation protocol method_id
      Lg.Protocol_registry.Int_receiver protocols
    = None
  then failwith "module compilation must preserve typed protocol registry state"

let test_module_elaboration_populates_typed_registry () =
  let state =
    typecheck_state
      {|
(module-signature MathSig (val answer :int))
(module Math (def answer 42))
(module-alias M Math)
(module-functor Make [Input MathSig] (def result Input/answer))
|}
  in
  let modules = Lg.Compiler_environment.modules state.env in
  let signature = Lg.Signature_id.create ~owner:[] ~name:"MathSig" in
  let alias = Lg.Module_id.create ~owner:[] ~name:"M" in
  let target = Lg.Module_id.create ~owner:[] ~name:"Math" in
  let functor_id = Lg.Functor_id.create ~owner:[] ~name:"Make" in
  if Lg.Module_registry.find_signature signature modules = None then
    failwith "module-signature must populate the typed module registry";
  if Lg.Module_registry.find_alias alias modules <> Some target then
    failwith "module-alias must populate the typed module registry";
  if Lg.Module_registry.find_functor_result functor_id modules = None then
    failwith "module-functor must populate the typed module registry"

