  match
    Lg.Compiler_environment.find_map
      (fun name binding -> if name = "target/value" then Some binding else None)
      env
  with
  | Some binding when binding.Lg.Types.ty = Lg.Types.TString -> ()
  | _ -> failwith "environment find_map must return the matching binding"

let test_compiler_environment_indexes_bindings_by_local_name () =
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "first/Value"
         (Lg.Types.binding "first_value" Lg.Types.TInt)
    |> Lg.Compiler_environment.add "second/Value"
         (Lg.Types.binding "second_value" Lg.Types.TString)
    |> Lg.Compiler_environment.add "second/Other"
         (Lg.Types.binding "second_other" Lg.Types.TBool)
  in
  let types =
    Lg.Compiler_environment.bindings_named "Value" env
    |> List.map (fun (binding : Lg.Types.binding) -> binding.ty)
    |> List.sort_uniq Stdlib.compare
  in
  if types <> [ Lg.Types.TInt; Lg.Types.TString ] then
    failwith "local-name binding index must include every matching namespace"

let test_compiler_environment_indexes_namespace_prefixes () =
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "people/user"
         (Lg.Types.binding "People.user" Lg.Types.TString)
    |> Lg.Compiler_environment.add "__record/people/Person"
         (Lg.Types.binding "People.person"
            (Lg.Types.named_record ~type_name:"Person"
               ~set_module_name:"Person_set" []))
    |> Lg.Compiler_environment.add "people.address/city"
         (Lg.Types.binding "People.Address.city" Lg.Types.TString)
    |> Lg.Compiler_environment.add "unrelated/value"
         (Lg.Types.binding "Unrelated.value" Lg.Types.TInt)
  in
  let keys env =
    Lg.Compiler_environment.namespace_binding_entries "people" env
    |> List.map fst |> List.sort String.compare
  in
  let expected =
    [ "__record/people/Person"; "people.address/city"; "people/user" ]
  in
  if keys env <> expected then
    failwith "namespace index must include values, records, and nested modules";
  let removed =
    Lg.Compiler_environment.remove "__record/people/Person" env
  in
  if keys removed <> [ "people.address/city"; "people/user" ] then
    failwith "namespace index must discard removed bindings"

let test_unresolved_declaration_index_tracks_aliases_and_overloads () =
  let declared ?(overload_targets = []) ocaml_name =
    { (Lg.Types.binding ocaml_name (Lg.Types.TOcaml "__declared_fn")) with
      overload_targets;
    }
  in
  let forward ?(overload_targets = []) ocaml_name =
    { (Lg.Types.binding ocaml_name Lg.Types.TInt) with
      forward_declared = true;
      overload_targets;
    }
  in
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "first/value" (declared "shared")
    |> Lg.Compiler_environment.add "second/value"
         (forward ~overload_targets:[ "shared$arity2" ] "shared")
  in
  if not (Lg.Compiler_environment.unresolved_declaration "shared$arity2" env)
  then failwith "overload targets must remain unresolved declarations";
  let env = Lg.Compiler_environment.remove "first/value" env in
  if not (Lg.Compiler_environment.unresolved_declaration_binding "shared" env)
  then failwith "removing one alias must preserve another declaration";
  let env =
    Lg.Compiler_environment.add "second/value"
      (Lg.Types.binding "shared" Lg.Types.TInt)
      env
  in
  if Lg.Compiler_environment.unresolved_declaration "shared" env then
    failwith "replacing the final forward declaration must clear the index"

let test_assoc_field_inference_avoids_full_environment_scans () =
  let stdlib = compiled_stdlib Lg.Target.Native in
  let state, prelude =
    Lg.Compiler.compile_chunk stdlib.state
      "(defrecord Counter [^:int count]) (def target (->Counter 0))"
    |> expect_ok
  in
  let env =
    List.init 20_000 Fun.id
    |> List.fold_left
         (fun env index ->
           Lg.Compiler_environment.add
             (Printf.sprintf "noise-%05d/value" index)
             (Lg.Types.binding "unused" Lg.Types.TInt) env)
         state.typecheck_state.env
  in
  let large_state =
    { state with typecheck_state = { state.typecheck_state with env } }
  in
  let source =
    "(println (let [a 40 b 41 c 42] (:count (assoc target :count c))))"
  in
  let compile state =
    Gc.full_major ();
    let before = Gc.allocated_bytes () in
    let _, output = Lg.Compiler.compile_chunk state source |> expect_ok in
    (output, Gc.allocated_bytes () -. before)
  in
  let _, small_allocations = compile state in
  let output, large_allocations = compile large_state in
  if large_allocations -. small_allocations > 5_000_000. then
    failwith
      (Printf.sprintf "assoc field inference allocated %.0f extra bytes for unrelated bindings"
         (large_allocations -. small_allocations));
  assert_ocaml_runs "assoc_field_lookup" "42\n"
    (String.concat "\n" [ stdlib.ocaml_source; prelude; output ])

let test_record_lookup_cost_is_independent_of_unrelated_bindings () =
  let record_ty =
    Lg.Types.named_record ~type_name:"Wanted" ~set_module_name:"Wanted_set" []
  in
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add "__record/requested/Stored"
         (Lg.Types.binding "stored" record_ty)
  in
  let env =
    List.init 20_000 Fun.id
    |> List.fold_left
         (fun env index ->
           Lg.Compiler_environment.add
             (Printf.sprintf "noise-%05d/value" index)
             (Lg.Types.binding (Printf.sprintf "noise_%05d" index) Lg.Types.TInt)
             env)
         env
  in
  let unrelated_record =
    Lg.Types.binding "unrelated_record"
      (Lg.Types.named_record ~type_name:"Unrelated"
         ~set_module_name:"Unrelated_set" [])
  in
  let env =
    List.init 10_000 Fun.id
    |> List.fold_left
         (fun env index ->
           let scope = if index mod 2 = 0 then "other" else "requested" in
           Lg.Compiler_environment.add
             (Printf.sprintf "__record/%s/Unrelated%05d" scope index)
             unrelated_record env)
         env
  in
  Gc.full_major ();
  let before = Gc.allocated_bytes () in
  for _ = 1 to 25 do
    match Lg.Resolver.lookup_record_type "requested" env "Wanted" with
    | Ok record when String.equal record.type_name "Wanted" -> ()
    | Ok _ -> failwith "record fallback lookup returned the wrong record"
    | Error error ->
        failwith ("record fallback lookup failed: " ^ error.Lg.Error.message)
  done;
  let allocated = Gc.allocated_bytes () -. before in
  if allocated > 500_000. then
    failwith
      (Printf.sprintf
         "record fallback lookup allocated %.0f bytes for unrelated bindings"
         allocated)

let test_record_lookup_index_tracks_removal_and_ambiguity () =
  let record_binding emitted_name =
    Lg.Types.binding emitted_name
      (Lg.Types.named_record ~type_name:"Wanted" ~set_module_name:"Wanted_set" [])
  in
  let first_key = "__record/requested/StoredFirst" in
  let env =
    Lg.Compiler_environment.empty
    |> Lg.Compiler_environment.add first_key (record_binding "stored_first")
  in
  let removed = Lg.Compiler_environment.remove first_key env in
  (match Lg.Resolver.lookup_record_type "requested" removed "Wanted" with
  | Error _ -> ()
  | Ok _ -> failwith "removed record remained visible to fallback lookup");
  let ambiguous =
    env
    |> Lg.Compiler_environment.add "__record/requested/StoredSecond"
         (record_binding "stored_second")
  in
  match Lg.Resolver.lookup_record_type "requested" ambiguous "Wanted" with
  | Error _ -> ()
  | Ok _ -> failwith "ambiguous record fallback lookup must be rejected"

