let test_dynamically_bound_vars_bind_and_restore_portably () =
  let source =
    {|
(def ^:dynamic *selected* (set-of :keyword))
(defn selected? [^:keyword value]
  (contains? *selected* value))

(println (selected? :a))
(println
  (binding [*selected* #{:a}]
    (selected? :a)))
(println
  (binding [*selected* #{:a}]
    (and
      (selected? :a)
      (binding [*selected* #{:b}]
        (and (selected? :b) (not (selected? :a))))
      (selected? :a))))
(try
  (binding [*selected* #{:a}]
    (do
      (Stdlib.failwith "stop")
      false))
  (catch _ false))
(println (selected? :a))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "dynamically_bound_vars_bind_and_restore_portably"
    "false\ntrue\ntrue\nfalse\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

