    (Lg_edn_backend/Float value) value
    _ 0.0))

(def nan (read-float "##NaN"))
(def positive-infinity (read-float "##Inf"))
(def negative-infinity (read-float "##-Inf"))
(println (not= nan nan))
(println (pos? positive-infinity))
(println (neg? negative-infinity))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/symbolic_edn.cljc" source
  in
  assert_ocaml_runs "clojure_edn_read_string_supports_symbolic_numbers"
    "true\ntrue\ntrue\n" native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange "test/symbolic_edn.cljc" source)

let test_melange_transit_api_compiles_for_native_and_melange () =
  let source =
    {|
(ns app.transit
  (:require
    [ocaml.Lg_runtime.Runtime_edn :as runtime-edn]
    #?(:native [ocaml.Transit_core.Json :as transit-json]
       :melange [ocaml.melange-transit-melange/Transit_melange.Transit.Json :as transit-json])
    #?(:native [ocaml.melange-edn-native/Melange_edn_native :as target-edn]
       :melange [ocaml.melange-edn-melange/Melange_edn_melange :as target-edn])
    #?(:native [ocaml.melange-transit-native/Transit_native.Transit.Json :as transit]
       :melange [ocaml.melange-transit-melange/Transit_melange.Transit.Json :as transit])))

(def encoded
  (transit/to-string
    (transit/of-edn
      (target-edn/of-edn-string
        (pr-str {:answer 42})))
    :mode (transit-json/Normal)))
(defn decode [encoded]
  (transit/of-string encoded))
(runtime-edn/read-string
  (target-edn/to-edn-string
    (transit/to-edn (transit/of-string encoded))))
|}
  in
  let compile target =
    let state, _ =
      Lg.Compiler.compile_chunk ~target (stdlib_state target) source
      |> expect_ok
    in
    match
      Lg.Compiler_environment.find_opt "app.transit/decode"
        state.typecheck_state.env
    with
    | Some { ty = Lg.Types.TFn ([ Lg.Types.TString ], _); _ } -> ()
    | Some binding ->
        failwith
          ("expected transit wrapper string parameter, got "
          ^ Lg.Types.source_name binding.ty)
    | None -> failwith "expected transit wrapper binding"
  in
  compile Lg.Target.Native;
  compile Lg.Target.Melange

