let test_callbacks_keep_nominal_protocol_parameters_raw () =
  let source =
    {|
(defprotocol Readable
  (read-value [database] :int))
(deftype Store [^int value])
(extend-type Store
  Readable
  (read-value [database]
    (.-value database)))
(type-record state
  (database :Store))
(defn state-store [^state state]
  (:database state))
(defn swap-store [^state state update]
  (let [database (update (state-store state))]
    (record state (database database))))
(defn store-number [^Store database]
  (.-value database))
(def initial
  (record state (database (Store. 1))))
(def updated
  (swap-store
    initial
    (fn [database]
      (if (= 1 (read-value database))
        (Store. 2)
        database))))
(println (store-number (:database updated)))
|}
  in
  let native_source = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "callbacks_keep_nominal_protocol_parameters_raw" "2\n"
    native_source;
  ignore
    (Lg.Compiler.compile_string ~target:Lg.Target.Melange source |> expect_ok)

let test_source_inline_macros_respect_lexical_shadowing () =
  let source =
    {|
(ns app.inline-shadow)

(type-record updater-holder
  (update :fn<int;int>))

(defn call-parameter [^:fn<int;int> update ^:int value]
  (update value))

(defn call-destructured [{:keys [update]} ^:int value]
  (update value))

(defn call-let [^:int value]
  (let [update (fn [^:int item] (+ item 3))]
    (update value)))

(def incrementer (fn [^:int value] (+ value 1)))
(def holder (record updater-holder (update (fn [^:int value] (+ value 2)))))

(println (call-parameter incrementer 1))
(println (call-destructured holder 1))
(println (call-let 1))
|}
  in
