let test_source_tagged_literals_match_clojurescript () =
  let source =
    {|
(ns app.source-tagged-literals
  (:require [clojure.core :as core :refer [record? tagged-literal tagged-literal?]]))

(def tagged-predicate core/tagged-literal?)
