let test_cross_module_extend_protocol_preserves_record_extension_field () =
  let record_source =
    {|
(ns app.records)
(defprotocol Existing
  (existing-value [this]))
(defrecord FindRel [elements]
  Existing
  (existing-value [_] elements))
(defrecord FindColl [element]
  Existing
  (existing-value [_] element))
(defrecord FindScalar [element]
  Existing
  (existing-value [_] element))
(defrecord FindTuple [elements]
  Existing
  (existing-value [_] elements))
|}
  in
  let extension_source =
    {|
(ns app.extension
  (:require [app.records :refer [FindRel FindColl FindScalar FindTuple]]))
(defprotocol Added
  (added-value
    [this
     ^:option<bool> return-map
     ^:vector<vector<int>> tuples]))
(extend-protocol Added
  FindRel
  (added-value [_ return-map tuples]
    (if (nil? return-map) tuples (vec tuples)))

  FindColl
  (added-value [_ return-map tuples]
    (into [] (map (fn [tuple] (nth tuple 0))) tuples))

  FindScalar
  (added-value [_ return-map tuples]
    (ffirst tuples))

  FindTuple
  (added-value [_ return-map tuples]
    (if (some? return-map) (first (vec tuples)) (first tuples))))
(println (= [1 2] (added-value (FindColl. nil) nil [[1] [2]])))
|}
  in
  let compile target =
    let stdlib = compiled_stdlib target in
    let sources =
      [
        ("test/protocol_records.cljc", record_source);
        ("test/protocol_extension.cljc", extension_source);
      ]
    in
    let _, outputs =
      List.fold_left
        (fun (state, outputs) (filename, source) ->
          let state, output =
            Lg.Compiler.compile_chunk_with_filename ~target ~filename state
              source
            |> expect_ok
          in
          (state, output :: outputs))
        (stdlib.state, [ stdlib.ocaml_source ]) sources
    in
    outputs |> List.rev |> String.concat "\n"
  in
  let native_source = compile Lg.Target.Native in
  assert_ocaml_runs
    "cross_module_extend_protocol_preserves_record_extension_field" "true\n"
    native_source;
  ignore (compile Lg.Target.Melange)

let test_dotimes_evaluates_bounds_once_and_returns_nil () =
  let source =
    {|
(def evaluations (atom 0))
(def runs (atom 0))
(def values (make-array 3 0))
(defn limit []
  (swap! evaluations (fn [value] (+ value 1)))
  3)
(def result
  (dotimes [index (limit)]
    (aset values index index)))
(dotimes [_ 0]
  (swap! runs (fn [value] (+ value 1))))
(dotimes [_ -2]
  (swap! runs (fn [value] (+ value 1))))
(println
  (str
    (= 0 (aget values 0)) ":"
    (= 1 (aget values 1)) ":"
    (= 2 (aget values 2)) ":"
    (= 1 @evaluations) ":"
    (= 0 @runs) ":"
    (nil? result)))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "dotimes_evaluates_bounds_once_and_returns_nil"
    "true:true:true:true:true:true\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

