let test_inferred_ocaml_calls_implicitly_apply_trailing_unit_after_optional_labels
    () =
  let dir = Filename.concat (test_dir ()) "unit_tail_fixture" in
  if not (Sys.file_exists dir) then Unix.mkdir dir 0o755;
  let mli = Filename.concat dir "unit_tail_fixture.mli" in
  let ml = Filename.concat dir "unit_tail_fixture.ml" in
  let generated_ml = Filename.concat dir "unit_tail_generated.ml" in
  let output_path = Filename.concat dir "unit_tail.out" in
  write_file mli
    {|
val entries : ?e:int -> ?a:string -> string -> unit -> string
val transform : ?apply:(string -> string) -> ?limit:int -> string -> string
val labelled : apply:(prefix:string -> string -> string) -> string -> string
val optional_callback : apply:(?prefix:string -> string -> string) -> string -> string
type operation = { operation_id : string; title : string }
type marker = { operation_id : string }
val collect : stage:(operation -> unit) -> pending:(unit -> operation list) -> int
type node = [ `Assoc of (string * node) list | `Text of string | `Null | `List of node list ]
val node : unit -> node
val children : unit -> node list
val sequence : unit -> node
|};
  write_file ml
    {|
let entries ?e ?a base () =
  base ^ ":" ^
  (match e with Some value -> string_of_int value | None -> "none") ^
  ":" ^
  (match a with Some value -> value | None -> "none")
let transform ?(apply = Fun.id) ?(limit = 20) value =
  let value = apply value in
  String.sub value 0 (min limit (String.length value))
let labelled ~apply value = apply ~prefix:"label:" value
let optional_callback ~(apply : ?prefix:string -> string -> string) value =
  apply value ^ ":" ^ apply ~prefix:"optional:" value
type operation = { operation_id : string; title : string }
type marker = { operation_id : string }
let collect ~stage ~pending =
  stage { operation_id = "a"; title = "first" };
  stage { operation_id = "a"; title = "updated" };
  List.length (pending ())
type node = [ `Assoc of (string * node) list | `Text of string | `Null | `List of node list ]
let node () = `Assoc [ "title", `Text "kept"; "child", `Null ]
let children () = [ node () ]
let sequence () = `List (children ())
|};
  Fun.protect
    ~finally:(fun () ->
      List.iter
        (fun path -> if Sys.file_exists path then Sys.remove path)
        [
          Filename.concat dir "unit_tail_fixture.cmi";
          Filename.concat dir "unit_tail_fixture.cmo";
          Filename.concat dir "unit_tail_generated.cmi";
          Filename.concat dir "unit_tail_generated.cmo";
          output_path;
          generated_ml;
          mli;
          ml;
        ];
      if Sys.file_exists dir then Unix.rmdir dir)
    (fun () ->
      let command =
        Printf.sprintf
          "cd %s && ocamlc -c unit_tail_fixture.mli && ocamlc -c \
           unit_tail_fixture.ml"
          (Filename.quote dir)
      in
      (match Sys.command command with
      | 0 -> ()
      | code ->
          failwith
            (Printf.sprintf
               "could not compile OCaml unit-tail fixture, exit code %d" code));
      Lg.Ocaml_signature.set_melange_target false;
      Lg.Ocaml_signature.add_include_dirs [ dir ];
      let source =
        {|
(require [ocaml.Unit_tail_fixture :as fixture])
(println (fixture/entries "base" :e 7 :a "name"))
(defn converted [f value] (fixture/transform :apply f value))
(defn converted-last [f value] (fixture/transform value :apply f))
(defn shortened [limit value] (fixture/transform :limit limit value))
(type-record transformer (run :fn<string;string>))
(defn from-record [transformer value]
  (fixture/transform :apply (:run transformer) value))
(defn locally-converted [f value]
  (letfn [(convert [value] (fixture/transform :apply f value))]
    (convert value)))
(println (converted (fn [value] (str value "!")) "hello"))
(println (converted-last (fn [value] (str value "!")) "hello"))
(println (shortened 3 "hello"))
(println (from-record (record transformer (run (fn [value] (str value "?")))) "hello"))
(println (locally-converted (fn [value] (str value "?")) "hello"))
(println (fixture/labelled :apply (fn [prefix value] (str prefix value)) "hello"))
(println (fixture/optional_callback
           :apply (fn [prefix value] (str (if-some [prefix prefix] prefix "none:") value))
           "hello"))
(def callback-builds (atom 0))
(println (fixture/optional_callback
           :apply (do (swap! callback-builds inc)
                      (fn [prefix value] (str (if-some [prefix prefix] prefix "none:") value)))
           "once"))
(println @callback-builds)
(def staged (atom []))
(println (fixture/collect
           :stage (fn [operation]
                    (swap! staged
                      (fn [operations]
                        (into [operation]
                          (remove #(= (:operation_id %) (:operation_id operation)) operations))))
                    (Stdlib.ignore 0))
           :pending (fn [] (apply list (reverse @staged)))))
(defn count-entries [^:map<string;Unit_tail_fixture.node> entries] (count entries))
(defn decode-node [node]
  (match node
    (tag Assoc fields) (Ok (count-entries (into {} (reverse fields))))
    _ (Error "not an object")))
(def decoded-nodes
  (reduce (fn [result child]
            (let* [values result value (decode-node child)] (Ok (conj values value))))
          (Ok []) (fixture/children)))
(println (match decoded-nodes (Ok values) (nth values 0) _ 0))
(defn node-field [^:map<string;Unit_tail_fixture.node> fields key] (get fields key))
(defn required-text [fields key]
  (match (node-field fields key)
    (Some (tag Text value)) (Ok value)
    _ (Error "missing text")))
(defn decode-title [node]
  (match node
    (tag Assoc entries)
    (let [fields (into {} (reverse entries))]
      (let* [title (required-text fields "title")]
        (Ok title)))
    _ (Error "not an object")))
(defn decode-titles [input]
  (match input
    (tag List children)
    (reduce (fn [result child]
              (let* [values result value (decode-title child)] (Ok (conj values value))))
            (Ok []) children)
    _ (Error "not a list")))
(def decoded-titles (decode-titles (fixture/sequence)))
(println (match decoded-titles (Ok values) (nth values 0) _ "failed"))
|}
      in
      let native_source = compile_string_with_stdlib source |> expect_ok in
      compile_string_with_stdlib
        {|(require [ocaml.Unit_tail_fixture :as fixture])
          (fixture/labelled :apply (fn [prefix value] 42) "bad")|}
      |> expect_error_contains "string";
      write_file generated_ml
        (String.concat "\n"
           [ native_stdlib_prelude (); strip_native_stdlib_prelude native_source ]);
      (match Sys.command (compile_only_command dir generated_ml) with
      | 0 -> ()
      | code ->
          failwith
            (Printf.sprintf "generated OCaml did not compile, exit code %d:\n%s"
               code native_source));
      let run_cmd =
        run_compiled_module_command dir
          [
            Filename.concat dir "unit_tail_fixture.cmo";
            Filename.concat dir "unit_tail_generated.cmo";
          ]
          output_path
      in
      (match Sys.command run_cmd with
      | 0 -> ()
      | code ->
          failwith
            (Printf.sprintf "generated OCaml did not run, exit code %d" code));
      let actual = read_file output_path in
      if actual <> "base:7:name\nhello!\nhello!\nhel\nhello?\nhello?\nlabel:hello\nnone:hello:optional:hello\nnone:once:optional:once\n1\n1\n2\nkept\n" then
        failwith
          (Printf.sprintf "expected %S, got %S" "base:7:name\nhello!\nhello!\nhel\nhello?\nhello?\nlabel:hello\nnone:hello:optional:hello\nnone:once:optional:once\n1\n1\n2\nkept\n" actual))

