let test_source_option_annotations_remain_nullable_until_lowering () =
  let expect_nullable source =
    match Lg.Type_annotation.parse_ocaml_type source with
    | Ok (Lg.Types.TNullable Lg.Types.TInt) -> ()
    | Ok ty ->
        failwith
          ("source option annotation became a host type: "
          ^ Lg.Types.source_name ty)
    | Error error -> failwith error.Lg.Error.message
  in
  expect_nullable "option<int>";
  match Lg.Type_annotation.parse_ocaml_type "result<option<int>;string>" with
  | Ok
      (Lg.Types.TOcaml_app
        ("result", [ Lg.Types.TNullable Lg.Types.TInt; Lg.Types.TString ])) ->
      ()
  | Ok ty ->
      failwith
        ("nested source option annotation became a host type: "
        ^ Lg.Types.source_name ty)
  | Error error -> failwith error.Lg.Error.message

let test_nullable_refinement_preserves_the_existing_boundary_identity () =
  let open Lg.Types in
  let host_option = TOcaml_app ("option", [ TInt ]) in
  let source_option = TNullable TInt in
  let expect expected actual =
    if not (equal expected actual) then
      failwith
        ("option refinement changed boundary identity: expected "
       ^ source_name expected ^ ", got " ^ source_name actual)
  in
  expect source_option
    (Lg.Type_inference_core.refine_type (TNullable TUnknown) host_option);
  expect host_option
    (Lg.Type_inference_core.refine_type
       (TOcaml_app ("option", [ TUnknown ])) source_option)

let test_structural_host_boundary_refinement_preserves_host_identity () =
  let open Lg.Types in
  let structural =
    TRecord
      [
        make_field ":db-id" (TNullable (TOcaml "Datascript.entity_ref"));
        make_field ":attrs"
          (seqable_constraint (TTuple [ TString; Lg.Type_solver.fresh () ]));
      ]
  in
  let host = TOcaml "Datascript.tx_entity" in
  let refined = Lg.Type_inference_core.refine_type structural host in
  if not (equal host refined) then
    failwith
      ("structural host-boundary refinement must keep host identity, got "
     ^ source_name refined);
  let fn_refined =
    Lg.Type_inference_core.refine_type
      (TFn ([ TOcaml "Datascript.db"; structural ], TVar "result"))
      (TFn ([ TOcaml "Datascript.db"; host ], TVar "result"))
  in
  let expected = TFn ([ TOcaml "Datascript.db"; host ], TVar "result") in
  if not (equal expected fn_refined) then
    failwith
      ("function parameter refinement must keep host identity, got "
     ^ source_name fn_refined);
  let transit_refined =
    Lg.Type_inference_core.refine_type
      (TFn ([ TOcaml "Datascript.db"; structural ], TOcaml "Transit_core.Json.value"))
      (TFn ([ TOcaml "Datascript.db"; host ], Lg.Type_solver.fresh ()))
  in
  let expected =
    TFn
      ([ TOcaml "Datascript.db"; host ], TOcaml "Transit_core.Json.value")
  in
  if not (equal expected transit_refined) then
    failwith
      ("host-return function refinement must keep host parameter identity, got "
     ^ source_name transit_refined)

