    let state, db_ocaml =
      Lg.Compiler.compile_chunk ~target state db_source |> expect_ok
    in
    let _, consumer_ocaml =
      Lg.Compiler.compile_chunk ~target state consumer_source |> expect_ok
    in
    String.concat "\n"
      [ stdlib.ocaml_source; storage_ocaml; db_ocaml; consumer_ocaml ]
