let test_host_callback_atom_vector_preserves_nominal_identity () =
  let dir = Filename.temp_dir "lg-callback-vector-" "" in
  let fixture = Filename.concat dir "callback_vector_fixture.ml" in
  let generated = Filename.concat dir "callback_vector_generated.ml" in
  let output = Filename.concat dir "result.out" in
  Fun.protect
    ~finally:(fun () ->
      Sys.readdir dir |> Array.iter (fun name -> Sys.remove (Filename.concat dir name));
      Unix.rmdir dir)
    (fun () ->
      write_file fixture {|
type state = Applied | Queued
type intent = Create_asset of { uuid : string; title : string }
type operation = { operation_id : string; base_t : int; state : state; intent : intent }
type row = { uuid : string; title : string }
type cursor = { mutable queue : int list; mutable active : int option; read_only : int }
let make_cursor () = { queue = [1; 2]; active = Some 1; read_only = 0 }
let make_row uuid title = { uuid; title }
let outliner_op = function Create_asset _ -> "save"
let create ?stage ?prepare ?rows ?pending () =
  let operation = { operation_id = "operation"; base_t = 7; state = Applied; intent = Create_asset { uuid = "asset"; title = "Updated" } } in
  Option.iter (fun stage -> ignore (stage operation)) stage;
  Option.iter (fun prepare -> ignore (prepare operation : ((string * string), string) result)) prepare;
  Option.iter (fun rows -> ignore (rows () : row list)) rows;
  Option.iter (fun pending -> ignore (pending () : operation list)) pending
|};
      let command = Printf.sprintf "cd %s && ocamlc -c callback_vector_fixture.ml" (Filename.quote dir) in
      if Sys.command command <> 0 then failwith "could not compile callback vector fixture";
      Lg.Ocaml_signature.set_melange_target false;
      Lg.Ocaml_signature.add_include_dirs [ dir ];
      let source = {|
(require [ocaml.Callback_vector_fixture :as host]
         [ocaml.Stdlib :as stdlib])
(type-record row (uuid :string) (title :string))
(defn other-operation [operation]
  (match (:intent operation) (host/Create_asset _) "other"))
(defn prepare-operation [operation]
  (Ok (tuple (host/outliner-op (:intent operation)) "[]")))
(let [staged (atom [])
      target (host/make-row "parent" "Parent")
      projected (atom (into [target] []))
      session (host/create :rows (fn [] (apply list @projected))
                           :stage (fn [operation]
                                    (swap! staged conj operation)
                                    (match (:intent operation)
                                      (host/Create_asset value)
                                      (do
                                        (reset! projected [target (host/make-row (:uuid value) "Asset")])
                                        (swap! projected
                                          (fn [rows]
                                            (mapv (fn [row]
                                                    (if (= (:uuid row) (:uuid value))
                                                      (assoc row :title (:title value)) row)) rows)))))
                                    (Ok (stdlib/ignore 0)))
                           :prepare prepare-operation)]
  (let [operation (nth @staged 0)]
    (match (:intent operation)
      (host/Create_asset value) (println (= "asset" (:uuid value))))
    (println (= (host/Applied) (:state operation)))
    (println (= "Updated" (:title (nth @projected 1))))))
|} in
      let compiled = compile_string_with_stdlib source |> expect_ok in
      write_file generated (String.concat "\n" [ native_stdlib_prelude (); strip_native_stdlib_prelude compiled ]);
      if Sys.command (compile_only_command dir generated) <> 0 then
        failwith "could not compile generated callback vector code";
      if Sys.command (run_compiled_module_command dir
          [ Filename.concat dir "callback_vector_fixture.cmo";
            Filename.concat dir "callback_vector_generated.cmo" ] output) <> 0 then
        failwith "could not run callback vector code";
      if read_file output <> "true\ntrue\ntrue\n" then failwith "callback vector result mismatch";
      let deletion = {|
(require [ocaml.Callback_vector_fixture :as host]
         [ocaml.Stdlib :as stdlib])
(type-record row (uuid :string) (title :string))
(defn make-row [uuid title] (assoc (host/make-row uuid title) :title title))
(let [staged (atom [])
      titles (vec (repeat 100 "Tail"))
      tail (mapv (fn [index title] (make-row (str "tail-" index) title)) (range 100) titles)
      projected (atom (into [(make-row "asset" "Asset")] tail))
      session (host/create :rows (fn [] (apply list @projected))
                           :stage (fn [operation]
                                    (swap! staged conj operation)
                                    (match (:intent operation)
                                      (host/Create_asset value)
                                      (swap! projected
                                        (fn [rows] (filterv (fn [row] (not= (:uuid row) (:uuid value))) rows))))
                                    (Ok (stdlib/ignore 0))))]
  (println (= 100 (count @projected)))
  (println (= 1 (count @staged))))
|} in
      let compiled = compile_string_with_stdlib deletion |> expect_ok in
      write_file generated (String.concat "\n" [ native_stdlib_prelude (); strip_native_stdlib_prelude compiled ]);
      if Sys.command (compile_only_command dir generated) <> 0 then
        failwith "could not compile callback deletion code";
      if Sys.command (run_compiled_module_command dir
          [ Filename.concat dir "callback_vector_fixture.cmo";
            Filename.concat dir "callback_vector_generated.cmo" ] output) <> 0 then
        failwith "could not run callback deletion code";
      if read_file output <> "true\ntrue\n" then failwith "callback deletion result mismatch";
      let replacement = {|
(require [ocaml.Callback_vector_fixture :as host]
         [ocaml.Stdlib :as stdlib])
(defn pending? [operation]
  (match (:state operation) (host/Applied) true (host/Queued) true))
(let [staged (atom [])]
  (host/create
    :stage (fn [operation]
             (swap! staged (fn [pending]
                             (conj (filterv #(not= (:operation-id %) (:operation-id operation)) pending)
                                   operation)))
             (Ok (stdlib/ignore 0)))
    :pending (fn [] (apply list (filterv pending? @staged))))
  (println (= 1 (count @staged)))
  (println (= "operation" (:operation-id (nth @staged 0)))))
|} in
      let compiled = compile_string_with_stdlib replacement |> expect_ok in
      write_file generated (String.concat "\n" [ native_stdlib_prelude (); strip_native_stdlib_prelude compiled ]);
      if Sys.command (compile_only_command dir generated) <> 0 then
        failwith "could not compile callback replacement code";
      if Sys.command (run_compiled_module_command dir
          [ Filename.concat dir "callback_vector_fixture.cmo";
            Filename.concat dir "callback_vector_generated.cmo" ] output) <> 0 then
        failwith "could not run callback replacement code";
      if read_file output <> "true\ntrue\n" then failwith "callback replacement result mismatch";
      let selection = {|
(require [ocaml.Callback_vector_fixture :as host]
         [ocaml.Stdlib :as stdlib])
(defn required-item [pred items]
  (if-some [item (first (filterv pred items))]
    item
    (stdlib/failwith "missing item")))
(let [row (required-item #(= "row" (:uuid %)) [(host/make-row "row" "Preserved")])]
  (println (:title row)))
(defn filtered [pred items] (filterv pred items))
(defn transformed [f items] (mapv f items))
(println (= [2] (filtered (fn [item] (= item 2)) [1 2])))
(println (= ["1" "2"] (transformed (fn [item] (str item)) [1 2])))
|} in
      let compiled = compile_string_with_stdlib selection |> expect_ok in
      write_file generated (String.concat "\n" [ native_stdlib_prelude (); strip_native_stdlib_prelude compiled ]);
      if Sys.command (compile_only_command dir generated) <> 0 then
        failwith "could not compile callback selection code";
      if Sys.command (run_compiled_module_command dir
          [ Filename.concat dir "callback_vector_fixture.cmo";
            Filename.concat dir "callback_vector_generated.cmo" ] output) <> 0 then
        failwith "could not run callback selection code";
      if read_file output <> "Preserved\ntrue\ntrue\n" then failwith ("callback selection result mismatch: " ^ read_file output);
      let mutation = {|
(require [ocaml.Callback_vector_fixture :as host])
(let [cursor (host/make-cursor)]
  (set! (.-queue cursor) (list))
  (set! (.-active cursor) nil)
  (println (empty? (:queue cursor)))
  (println (nil? (:active cursor))))
|} in
      let compiled = compile_string_with_stdlib mutation |> expect_ok in
      write_file generated (String.concat "\n" [ native_stdlib_prelude (); strip_native_stdlib_prelude compiled ]);
      if Sys.command (compile_only_command dir generated) <> 0 then
        failwith "could not compile host mutation code";
      if Sys.command (run_compiled_module_command dir
          [ Filename.concat dir "callback_vector_fixture.cmo";
            Filename.concat dir "callback_vector_generated.cmo" ] output) <> 0 then
        failwith "could not run host mutation code";
      if read_file output <> "true\ntrue\n" then failwith "host mutation result mismatch";
      compile_string_with_stdlib {|
(require [ocaml.Callback_vector_fixture :as host])
(set! (.-read-only (host/make-cursor)) 3)
|} |> expect_error_contains "not mutable";
      compile_string_with_stdlib {|
(require [ocaml.Callback_vector_fixture :as host])
(set! (.-queue (host/make-cursor)) (list "invalid"))
|} |> expect_error_contains "string";
      let incompatible = {|
(require [ocaml.Callback_vector_fixture :as host])
(let [staged (atom [])]
  (host/create :stage (fn [operation] (swap! staged conj operation)))
  (swap! staged conj (host/make-row "row" "Different record"))
  (println (count @staged)))
|} in
      let incompatible_updater = {|
(require [ocaml.Callback_vector_fixture :as host])
(let [staged (atom [])]
  (host/create :stage (fn [operation] (swap! staged conj operation)))
  (swap! staged (fn [pending] (conj pending (host/make-row "row" "Different record"))))
  (println (count @staged)))
|} in
      List.iter
        (fun source ->
          match compile_string_with_stdlib source with
          | Error _ -> ()
          | Ok _ -> failwith "atom updates must not merge distinct host records")
        [incompatible; incompatible_updater])

