(assert (= (Some 42) (increment-answer [(tuple "answer" 41)])))
(assert (= nil (increment-answer [(tuple "other" 41)])))
(assert (= (Some 2) (increment-answer [(tuple "answer" 1) (tuple "answer" 99)])))
