let test_host_variant_tuple_sequence_adapts_payload_capabilities () =
  let dir = Filename.concat (test_dir ()) "variant_sequence_fixture" in
  if not (Sys.file_exists dir) then Unix.mkdir dir 0o755;
  Fun.protect ~finally:(fun () ->
    Array.iter (fun name -> Sys.remove (Filename.concat dir name)) (Sys.readdir dir);
    Unix.rmdir dir) (fun () ->
    let fixture = Filename.concat dir "variant_sequence_fixture.ml" in
    write_file fixture {|
type t = [ `String of string | `Null | `Assoc of (string * t) list ]
let entries () : (string * t) list =
  ["text", `String "hello"; "empty", `String ""; "null", `Null;
   "nested", `Assoc ["child", `String "kept"]]
|};
    if Sys.command (compile_only_command dir fixture) <> 0 then
      failwith "variant sequence fixture did not compile";
    Lg.Ocaml_signature.set_melange_target false;
    Lg.Ocaml_signature.add_include_dirs [dir];
    let source = {|
(ns variant-sequence-client (:require [ocaml.Variant_sequence_fixture :as host]))
(defn lookup-field [fields name]
  (some (fn [[key value]] (when (= key name) value)) fields))
(defn populated? [fields name]
  (match (lookup-field fields name)
    (Some (tag String value)) (not (empty? value))
    _ false))
(let [fields (host/entries)]
  (assert (populated? fields "text"))
  (assert (not (populated? fields "empty")))
  (assert (not (populated? fields "null")))
  (assert (not (populated? fields "nested")))
  (assert (not (populated? fields "missing"))))
|} in
    let compiled = compile_string_with_stdlib source |> expect_ok in
    let generated = Filename.concat dir "variant_sequence_generated.ml" in
    write_file generated compiled;
    if Sys.command (compile_only_command dir generated) <> 0 then
      failwith "variant sequence generated code did not compile";
    let output = Filename.concat dir "result.out" in
    if Sys.command (run_compiled_module_command dir
      [Filename.concat dir "variant_sequence_fixture.cmo";
       Filename.concat dir "variant_sequence_generated.cmo"] output) <> 0 then
      failwith "variant sequence generated code did not run";
    if read_file output <> "" then failwith "unexpected variant sequence output")

let test_some_preserves_host_tuple_elements () =
  let dir = Filename.concat (test_dir ()) "host_tuple_fixture" in
  if not (Sys.file_exists dir) then Unix.mkdir dir 0o755;
  Fun.protect ~finally:(fun () ->
    Array.iter (fun name -> Sys.remove (Filename.concat dir name)) (Sys.readdir dir);
    Unix.rmdir dir) (fun () ->
    let ml = Filename.concat dir "host_tuple_fixture.ml" in
    write_file ml {|
type value = Text of string
type tx_value = One_value of value | One_entity of tx_entity
and tx_entity = { db_id : int option; attrs : (string * tx_value) list }
type tx_op = Entity of tx_entity | Delete of int
let make () = Entity { db_id = None; attrs = ["index", One_value (Text "yes")] }
type datom = { added : bool; value : string }
let rows () = [{ added = true; value = "old" }; { added = false; value = "kept" }]
let entries () = List.map (fun row -> row.value, row) (rows ())
type api = { all : unit -> datom list }
let api = { all = rows }
type pair = string * int
type paired = Pair of pair
let paired = Pair ("items", 2)
module Internal = struct
  module Config = struct type t = { enabled : bool } end
  module Token : sig type t val make : unit -> t end = struct
    type t = int
    let make () = 7
  end
  let read (config : Config.t) = config.enabled
  let tokens () = ["token", Some (Token.make ())]
end
module Config = Internal.Config
module Token = Internal.Token
let read = Internal.read
let tokens = Internal.tokens
let configs () = ["enabled", Some Internal.Config.{ enabled = true }]
module Other = struct type t = { enabled : bool } end
module Codec = struct
  type t = Int
  let int = Int
  let read = function Int -> 7
end
module Json = struct
  type t = [ `Assoc of (string * t) list | `List of t list | `String of string | `Int of int ]
  let sample = `List [`Assoc ["title", `String "hello"]]
  let accept (value : t) = value
end
module Typed_codec : sig
  type 'a t
  val string : string t
  val int : int t
  val decode : 'a t -> 'a
end = struct
  type 'a t = { value : 'a }
  let string = { value = "hello" }
  let int = { value = 7 }
  let decode codec = codec.value
end
module Attribute : sig
  type 'a t
  val make : string -> 'a Typed_codec.t -> bool -> 'a t
  val string : string t
  val int : int t
  val read_one : 'a t -> string -> ('a option, string) result
end = struct
  type 'a t = { value : 'a }
  let make _name codec _indexed = { value = Typed_codec.decode codec }
  let string = make "title" Typed_codec.string false
  let int = make "count" Typed_codec.int false
  let read_one attr _entity = Ok (Some attr.value)
end
let or_raise = function Ok value -> value | Error message -> failwith message
|};
    if Sys.command (compile_only_command dir ml) <> 0 then failwith "host tuple fixture did not compile";
    Lg.Ocaml_signature.set_melange_target false;
    Lg.Ocaml_signature.add_include_dirs [dir];
    let source = {|
(ns host-tuple-client
  (:require [ocaml.Host_tuple_fixture :as host] [ocaml.Rrbvec :as rrbvec]
            [ocaml.Host_tuple_fixture.Attribute :as attribute]
            [ocaml.Host_tuple_fixture.Codec :as codec]))
(assert (= (codec/read codec/int) 7))
(defn read-attribute [attr entity]
  (when-some [entity entity] (host/or-raise (attribute/read-one attr entity))))
(defn text-attribute [name] (attribute/make name host/Typed_codec.string false))
(def string-attribute (text-attribute "hello"))
(type-record decoded-status (title :string))
(type-record decoded-entry (status :option<decoded-status>) (count :int))
(defn decode-status [source]
  (when (not= source "") (record decoded-status (title (clojure.string/trim source)))))
(defn read-entry [entity]
  (when-some [uuid (read-attribute string-attribute entity)]
    (record decoded-entry
      (status (when-some [value (read-attribute string-attribute entity)] (decode-status value)))
      (count (or (read-attribute host/Attribute.int entity) 0)))))
(assert (match (read-entry (Some "entity"))
          (Some entry) (and (= (:count entry) 7)
                            (= (when-some [status (:status entry)] (:title status)) (Some "hello")))
          _ false))
(defn json-title [^:map<string;Host_tuple_fixture.Json.t> fields]
  (match (get fields "title") (Some (tag String title)) (Some title) _ nil))
(defn json-titles [^:Host_tuple_fixture.Json.t source]
  (match source
    (tag List values) (vec (keep (fn [value]
                                  (match value (tag Assoc entries) (json-title (into {} entries)) _ nil)) values))
    _ []))
(assert (= (json-titles host/Json.sample) ["hello"]))
(defn schema-attr? [attr] (contains? #{"index" "unique"} attr))
(defn select [tx]
  (match tx
    (host/Entity entity)
    (let [attrs (filterv (fn [[attr _]] (schema-attr? attr)) (:attrs entity))]
      (when (some (fn [[attr _]] (schema-attr? attr)) attrs)
        (host/Entity (assoc entity :db-id nil :attrs (rrbvec/to-list attrs)))))
    _ nil))
(println (some? (select (host/make))))
(assert (= (count ((:all host/api))) 2))
(let [all (:all host/api)] (assert (= (count (all)) 2)))
(assert (= (match host/paired (host/Pair [label size]) (str label ":" size)) "items:2"))
(assert (host/read (record Host_tuple_fixture.Config.t (enabled true))))
(defn read-configs [^:vector<tuple<string;option<Host_tuple_fixture.Config.t>>> configs]
  (mapv (fn [[label config]] (if-some [config config] (host/read config) false)) configs))
(assert (= (read-configs (vec (host/configs))) [true]))
(defn count-tokens [^:vector<tuple<string;option<Host_tuple_fixture.Token.t>>> tokens]
  (count tokens))
(assert (= (count-tokens (vec (host/tokens))) 1))
(defn rewrite []
  (let [rows (vec (host/rows))]
    (loop [index 0 result []]
      (if (= index (count rows))
        result
        (let [row (nth rows index)]
          (if (:added row)
            (recur (inc index) (conj result (assoc row :value "changed")))
            (recur (inc index) (conj result row))))))))
(println (clojure.string/join ":" (mapv :value (rewrite))))
(defn check-value [^:bool valid]
  (when (not valid) (throw (Failure "inactive"))))
(defn validate [^:bool whole]
  (if whole (run! check-value [true]) (check-value true)))
(assert (nil? (validate true)))
(assert (nil? (validate false)))
(defn run-validations [] (run! check-value [true]))
(assert (nil? (run-validations)))
(defn has-value? [entries key]
  (if-some [row (get entries key)] (some? (:value row)) false))
(let [entries (into {} (host/entries))]
  (assert (has-value? entries "old"))
  (assert (not (has-value? entries "missing"))))
|} in
    let state, previous = Lg.Compiler.compile_chunk ~target:Lg.Target.Native
      (stdlib_state Lg.Target.Native) {|
(ns earlier-codec (:require [clojure.core :as codec]))
(defn cast-int [value] (codec/int value))
|} |> expect_ok in
    let _, compiled = Lg.Compiler.compile_chunk ~target:Lg.Target.Native state source |> expect_ok in
    let compiled = previous ^ "\n" ^ compiled in
    (match compile_string_with_stdlib {|
(ns wrong-host-record (:require [ocaml.Host_tuple_fixture :as host]))
(host/read (record Host_tuple_fixture.Other.t (enabled true)))
|} with
     | Error _ -> ()
     | Ok _ -> failwith "unrelated host records must not be identity compatible");
    (match compile_string_with_stdlib {|
(ns wrong-json-payload (:require [ocaml.Host_tuple_fixture.Json :as json]))
(json/accept (tag List (list (tag String 42))))
|} with
     | Error _ -> ()
     | Ok _ -> failwith "recursive host aliases must retain their payload types");
    let generated = Filename.concat dir "host_tuple_generated.ml" in
    write_file generated (native_stdlib_prelude () ^ "\n" ^ strip_native_stdlib_prelude compiled);
    if Sys.command (compile_only_command dir generated) <> 0 then failwith "host tuple generated code did not compile";
    let output = Filename.concat dir "result.out" in
    if Sys.command (run_compiled_module_command dir
      [Filename.concat dir "host_tuple_fixture.cmo"; Filename.concat dir "host_tuple_generated.cmo"] output) <> 0
    then failwith "host tuple generated code did not run";
    if read_file output <> "true\nchanged:kept\n" then failwith "host tuple selection changed")

let test_contains_propagates_protocol_set_element_to_parameter () =
