(extend-type leaf Traversable (walk-leaf [value] (:text value)))
(defn walk [^walk-node value]
  (match value
    (WalkLeaf leaf) (Traversable/walk-leaf leaf)
    (WalkChildren values) (apply str (map walk values))
    WalkOther "_"))
(def value (record leaf (text "leaf")))
