let test_if_heterogeneous_nominal_branches_require_sum_type () =
  let source =
    {|
(declare ->Entity)
(defn choose-entity [many?]
  (if many?
    (hash-set (->Entity 7 (volatile! {})))
    (->Entity 7 (volatile! {}))))
(deftype Entity [^int eid cache]
  IEquiv
  (-equiv [this other]
    (and
      (instance? Entity other)
      (= eid (.-eid ^Entity other)))))
(def entity (Entity. 7 (volatile! {})))
(def one (choose-entity false))
(def many (choose-entity true))
(println (= one entity))
(println (= many (hash-set entity)))
|}
  in
  compile_with_stdlib_result Lg.Target.Native
    "test/if_heterogeneous_nominal_branches.cljc" source
  |> expect_error_contains "define a closed sum type";
  compile_with_stdlib_result Lg.Target.Melange
    "test/if_heterogeneous_nominal_branches.cljc" source
  |> expect_error_contains "define a closed sum type"

