let test_cross_namespace_deftype_uses_custom_printer () =
  let model_source =
    {|
(ns app.model)
(defprotocol IDatom
  (datom-tx [this])
  (datom-added [this]))
(deftype Datom [^number e ^:keyword a ^:string v ^number tx
                ^:mutable ^number idx ^:mutable ^number cached-hash]
  IDatom
  (datom-tx [_] tx)
  (datom-added [_] true)
  IPrintWithWriter
  (-pr-writer [d writer opts]
    (-write writer "#app/Datom [")
    (pr-writer (.-e d) writer opts)
    (-write writer " ")
    (pr-writer (.-a d) writer opts)
    (-write writer " ")
    (-write writer (str "\"" (.-v d) "\""))
    (-write writer " ")
    (pr-writer (datom-tx d) writer opts)
    (-write writer " ")
    (pr-writer (datom-added d) writer opts)
    (-write writer "]")))
|}
  in
  let consumer_source =
    {|
(ns app.serialize
  (:require [app.model :as model]))
(def datom (model/Datom. 1 :name "Ada" 2 0 0))
(println (pr-str datom))
|}
  in
  let compile target =
    let stdlib = compiled_stdlib target in
    let state, model_ocaml =
      Lg.Compiler.compile_chunk ~target stdlib.state model_source
      |> expect_ok
    in
    let _, consumer_ocaml =
      Lg.Compiler.compile_chunk ~target state consumer_source |> expect_ok
    in
    model_ocaml ^ "\n" ^ consumer_ocaml
  in
  let native_source = compile Lg.Target.Native in
  assert_ocaml_runs "cross_namespace_deftype_uses_custom_printer"
    "#app/Datom [1 :name \"Ada\" 2 true]\n" native_source;
  ignore (compile Lg.Target.Melange)

