let test_nominal_sequence_branches_lift_into_nullable_results () =
  let source =
    {|
(deftype Datom [^int value])
(defrecord Holder [^:option<seq<Datom>> datoms])
(defn ^:option<seq<Datom>> choose-datoms [mode]
  (cond
    (= mode 0)
    (filter (fn [^Datom _] true) [(Datom. 1)])

    (= mode 1)
    (Some (filter (fn [^Datom _] true) [(Datom. 2)]))

    (= mode 2)
    nil

    :else
    (take-while (fn [^Datom _] true)
      (filter (fn [^Datom _] true) [(Datom. 3)]))))
(defn chosen-count [mode]
  (let [holder (Holder. (choose-datoms mode))]
    (if-some [datoms (:datoms holder)]
      (count datoms)
      0)))
(defn first-is-datom? [mode]
  (if-some [datom (first (choose-datoms mode))]
    (instance? Datom datom)
    false))
(println
  (str (chosen-count 0) ":"
       (chosen-count 1) ":"
       (chosen-count 2) ":"
       (chosen-count 3) ":"
       (first-is-datom? 0) ":"
       (first-is-datom? 3)))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "nominal_sequence_branches_lift_into_nullable_results"
    "1:1:0:1:true:true\n" ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_cross_module_dynamic_protocol_results_require_static_sum () =
  let set_source =
    {|
(ns test.set)
(defn slice [values present?]
  (if present?
    (Some (filter (fn [_] true) values))
    nil))
(defn first-item [values]
  (first values))
|}
  in
  let db_source =
    {|
(ns test.db)
(defprotocol IDatom
  (datom-value [datom]))
(deftype Datom [^int value ^:mutable ^int idx]
  IDatom
  (datom-value [_] value)
  IEquiv
  (-equiv [_ other]
    (instance? Datom other)))
(defn ^Datom datom [value]
  (Datom. value 0))
|}
  in
  let app_source =
    {|
(ns test.app
  (:require [test.set :as set]
            [test.db :as db]))
(defprotocol Search
  (-search [db]))
(deftype DynamicDB [marker]
  Search
  (-search [_]
    (filter (fn [^test.db/Datom _] true) [(db/datom 2)])))
(defrecord Context [db])
(defrecord Holder [datoms])
(defn choose-datoms [^Context context mode]
  (let [db (:db context)]
    (cond
      (= mode 0)
      (set/slice [(db/datom 1)] true)

      (= mode 1)
      (-search db)

      (= mode 2)
      nil

      :else
      (take-while (fn [^test.db/Datom _] true) (-search db)))))
(def context (Context. (DynamicDB. true)))
(defn chosen-count [mode]
  (let [holder (Holder. (choose-datoms context mode))]
    (if-some [datoms (:datoms holder)]
      (count datoms)
      0)))
(defn first-is-datom? [mode]
  (instance? test.db/Datom (first (choose-datoms context mode))))
(defn first-value [mode]
  (let [holder (Holder. (choose-datoms context mode))
        ^test.db/Datom datom (set/first-item (.-datoms holder))]
    (.-value datom)))
(defn first-static-value []
  (let [^test.db/Datom datom
        (set/first-item
          (filter (fn [^test.db/Datom _] true) [(db/datom 3)]))]
    (.-value datom)))
(println
  (str (chosen-count 0) ":"
       (chosen-count 1) ":"
       (chosen-count 2) ":"
       (chosen-count 3) ":"
       (first-is-datom? 0) ":"
       (first-is-datom? 1) ":"
       (first-value 0) ":"
       (first-value 1) ":"
       (first-static-value)))
|}
  in
  let reject target =
    let stdlib = compiled_stdlib target in
    let state, _set_ocaml =
      Lg.Compiler.compile_chunk ~target stdlib.state set_source
      |> expect_ok
    in
    let state, _db_ocaml =
      Lg.Compiler.compile_chunk ~target state db_source |> expect_ok
    in
    Lg.Compiler.compile_chunk ~target state app_source
    |> expect_error_contains "match a closed sum type"
  in
  reject Lg.Target.Native;
  reject Lg.Target.Melange

let test_extend_protocol_keeps_parameter_positions_independent () =
  let source =
    {|
(defrecord FindRel [])
(defrecord FindColl [])
(defrecord FindScalar [])
(defrecord FindTuple [])
(defprotocol PostProcess
  (-post-process
    [find
     ^:option<bool> return-map
     ^:vector<vector<int>> tuples]))
(extend-protocol PostProcess
  FindRel
  (-post-process [_ return-map tuples]
    (if (nil? return-map)
      tuples
      (vec tuples)))

  FindColl
  (-post-process [_ return-map tuples]
    (into [] (map (fn [tuple] (nth tuple 0))) tuples))

  FindScalar
  (-post-process [_ return-map tuples]
    (ffirst tuples)))
(println (= [1 2] (-post-process (FindColl.) nil [[1] [2]])))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native
      "test/extend_protocol_parameter_positions.cljc" source
  in
  assert_ocaml_runs "extend_protocol_keeps_parameter_positions_independent"
    "true\n" native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange
       "test/extend_protocol_parameter_positions.cljc" source)

