let test_cond_contextualizes_anonymous_function_branches () =
  let source =
    {|
(type-variant predicate-value
  (StringValue :string)
  (NilValue)
  (IntValue :int))
(defn predicate-for [value]
  (match value
    (StringValue _)
    (fn [candidate]
      (match candidate
        (StringValue _) true
        _ false))
    (NilValue)
    (fn [candidate]
      (match candidate
        (NilValue) true
        _ false))
    (IntValue expected)
    (fn [candidate]
      (match candidate
        (IntValue actual) (= expected actual)
        _ false))))
(println (str ((predicate-for (StringValue "a")) (StringValue "b")) ":"
              ((predicate-for (NilValue)) (NilValue)) ":"
              ((predicate-for (IntValue 1)) (IntValue 1))))
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "cond_contextualizes_anonymous_function_branches"
    "true:true:true\n" ocaml_source

