let test_assoc_callback_preserves_nominal_record_collection_fields () =
  let source =
    {|
(type-variant semantic-value (String-value :string))
(type-record property-change
  (attr :string)
  (expected :option<semantic-value>)
  (value :option<semantic-value>))
(type-record pending-properties
  (uuid :string)
  (changes :vector<property-change>))
(defn normalize-optional-value [value]
  (match value
    (Some present) (Some present)
    None None))
(defn normalize-property-change [change]
  (assoc change
         :expected (normalize-optional-value (:expected change))
         :value (normalize-optional-value (:value change))))
(defn normalize-properties [value]
  (assoc value :changes (mapv normalize-property-change (:changes value))))
(def sample
  (record pending-properties
    (uuid "u")
    (changes [(record property-change
                (attr "a")
                (expected (Some (String-value "old")))
                (value (Some (String-value "new"))))])))
(println (:uuid (normalize-properties sample)))

(type-record encryption-options (encrypt-title :fn<string;result<string;string>>))
(def defaults (record encryption-options (encrypt-title (fn [value] (Ok value)))))
(defn encrypted-options []
  (let [encrypt-text (fn [value] (Ok (str "enc:" value)))]
    (assoc defaults :encrypt-title encrypt-text)))
(match ((:encrypt-title (encrypted-options)) "title")
  (Ok title) (println title)
  (Error message) (throw (Failure message)))

(type-record optional-title-normalizer
  (normalize :option<fn<string;list<string>;tuple<list<string>;list<tuple<string;string>>>>>))
(def normalizer-defaults (record optional-title-normalizer (normalize None)))
(defn normalizer-options []
  (assoc normalizer-defaults
         :normalize (Some (fn [uuid titles]
                            (tuple titles (list (tuple uuid "Title")))))))
(match (:normalize (normalizer-options))
  (Some normalize)
  (let [[titles tags] (normalize "u" (list "Title"))]
    (println (str (count titles) ":" (count tags))))
  None (println "missing"))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs
    "assoc_callback_preserves_nominal_record_collection_fields"
    "u\nenc:title\n1:1\n"
    ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Js_of_ocaml source |> expect_ok);
  let provider =
    {|
(ns app.runtime)

(type-record runtime-options
  (encrypt-title :fn<string;result<string;string>>))

(def default-options
  (record runtime-options (encrypt-title (fn [value] (Ok value)))))
|}
  in
  let consumer =
    {|
(ns app.live
  (:require [app.runtime :as runtime]))

(defn options [enabled]
  (let [encrypt-text (fn [value] (Ok (if enabled (str "enc:" value) value)))]
    (assoc runtime/default-options :encrypt-title encrypt-text)))

(defn with-callback [callback]
  (callback "dir"))

(defn nested-options [enabled]
  (let [encrypt-text (fn [value] (Ok (if enabled (str "nested:" value) value)))]
    (with-callback
      (fn [dir]
        (let [options (assoc runtime/default-options :encrypt-title encrypt-text)]
          options)))))

(match ((:encrypt-title (options true)) "title")
  (Ok title) (println title)
  (Error message) (throw (Failure message)))

(match ((:encrypt-title (nested-options true)) "title")
  (Ok title) (println title)
  (Error message) (throw (Failure message)))
|}
  in
  let stdlib = compiled_stdlib Lg.Target.Native in
  let state, provider_ocaml =
    Lg.Compiler.compile_chunk ~target:Lg.Target.Native stdlib.state provider
    |> expect_ok
  in
  let _, consumer_ocaml =
    Lg.Compiler.compile_chunk ~target:Lg.Target.Native state consumer
    |> expect_ok
  in
  assert_ocaml_runs
    "assoc_imported_callback_uses_record_field_context"
    "enc:title\nnested:title\n"
    (String.concat "\n"
       [ stdlib.ocaml_source; provider_ocaml; consumer_ocaml ]);
  let stdlib = compiled_stdlib Lg.Target.Melange in
  let state, _ =
    Lg.Compiler.compile_chunk ~target:Lg.Target.Melange stdlib.state provider
    |> expect_ok
  in
  ignore
    (Lg.Compiler.compile_chunk ~target:Lg.Target.Melange state consumer
    |> expect_ok)

let test_assoc_computed_record_field_uses_field_context () =
  let source = {|
(type-record operation (operation-id :string))
(type-record pending (operation :operation))
(type-record session-state (semantic-queue :vector<pending>))
(type-record session (state :ref<session-state>))
(defn state [session] @(:state session))
(defn prioritize [session operation]
  (let [queue (:semantic-queue (state session))
        selected? (fn [pending] (= (:operation-id (:operation pending)) (:operation-id operation)))]
    (swap! (:state session) assoc :semantic-queue
           (into (filterv selected? queue) (remove selected? queue)))))
(let [a (record operation (operation-id "a"))
      b (record operation (operation-id "b"))
      current (record session (state (atom (record session-state
                                (semantic-queue [(record pending (operation a)) (record pending (operation b))])))))]
  (prioritize current b)
  (let [ids (mapv #(-> % :operation :operation-id) (:semantic-queue (state current)))]
    (println (str (nth ids 0) ":" (nth ids 1)))))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs
    "assoc_computed_record_field_uses_field_context" "b:a\n"
    ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Js_of_ocaml source |> expect_ok)

let test_update_callback_does_not_inherit_enclosing_record_result () =
  let source = {|
(type-record pending (id :string))
(type-record active (pending :pending))
(type-record session-state (queue :vector<pending>) (active :option<active>))
(type-record session (state :ref<session-state>))
(defn state [session] @(:state session))
(defn prepend! [session]
  (when-some [active (:active (state session))]
    (swap! (:state session) update :queue #(into [(:pending active)] %))))
(let [first (record pending (id "first"))
      last (record pending (id "last"))
      current (record session (state (atom (record session-state (queue [last])
                                           (active (Some (record active (pending first))))))))]
  (prepend! current)
  (assert (= ["first" "last"] (mapv :id (:queue @(:state current))))))
|} in
  let compiled = compile_string_with_stdlib source |> expect_ok in
  if string_contains_substring compiled "Runtime_dynamic" then
    failwith "record field update must remain static";
  assert_ocaml_runs "update_callback_does_not_inherit_enclosing_record_result"
    "" compiled;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

