let test_swap_update_conj_preserves_record_element_context () =
  let source = {|
(type-record route (uuid :string) (zoom :bool) (state :int))

(type-record navigation (routes :vector<route>))

(type-record session (state :ref<navigation>))

(defn state [session] @(:state session))

(defn initial-state [route]
  (if (:zoom route) (if (= (:uuid route) "") 0 3) 0))

(defn push-route! [session route]
  (count (:routes (state session)))
  (let [current (initial-state route)]
    (swap! (:state session) update :routes conj (assoc route :state current))))

(def session (record session (state (atom (record navigation (routes []))))))

(push-route! session (record route (uuid "abc") (zoom true) (state 99)))
(push-route! session (record route (uuid "def") (zoom false) (state 99)))
(println (count (:routes @(:state session))))
(run! (fn [route] (println (str (:uuid route) ":" (:state route)))) (:routes @(:state session)))
|} in
  let output = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "swap_update_conj_preserves_record_element_context"
    "2\nabc:3\ndef:0\n" output;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_expression_callback_constrains_record_arguments () =
  let source = {|
(type-record request (url :string))

(type-record response (body :string))

(type-record transport (send :fn<request;response>))

(type-record session (host :transport))

(defn host [session] (:host session))

(defn deliver [session request]
  (:body ((:send (host session)) request)))

(def client
  (record session
    (host (record transport
      (send (fn [request] (record response (body (:url request)))))))))

(println (deliver client (record request (url "preserved"))))

(let [calls (atom 0)]
  (println (:body ((do (swap! calls inc) (:send (host client)))
                  (record request (url "once")))))
  (println @calls))
|} in
  let output = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "expression_callback_constrains_record_arguments" "preserved\nonce\n1\n" output;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  List.iter (fun target ->
    match compile_string_with_stdlib ~target (source ^ "\n(deliver client 42)") with
    | Error _ -> ()
    | Ok _ -> failwith "expression callback erased its request argument type")
    [Lg.Target.Native; Lg.Target.Melange]

let test_assoc_nested_record_flows_into_callback () =
  let source = {|
(type-variant phase (Waiting) (Accepted :int))

(type-record operation (id :string) (phase :phase))

(type-record pending (operation :operation))

(type-record active (pending :pending))

(type-record host (stage :option<fn<operation;string>>))

(defn finish [host active]
  (if-some [stage (:stage host)]
    (stage (assoc (:operation (:pending active)) :phase (Accepted 7)))
    "absent"))

(def original (record operation (id "kept") (phase Waiting)))

(def entry (record active (pending (record pending (operation original)))))

(def enabled (record host (stage (Some (fn [operation]
  (str (:id operation) ":" (match (:phase operation) (Accepted n) n Waiting 0)))))))

(println (finish enabled entry))
(println (finish (record host (stage nil)) entry))
(println (match (:phase original) Waiting "unchanged" (Accepted _) "changed"))

(defn rename-entry [active]
  (assoc (:operation (:pending active)) :phase (Accepted 9) :id "renamed"))

(println (:id (rename-entry entry)))

(type-record counters (counts :map<keyword;int>))

(defn update-counts [^:counters entry]
  (assoc (:counts entry) :a 2 :b 3))

(println (get (update-counts (record counters (counts {:a 1}))) :b 0))
|} in
  let output = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "assoc_nested_record_flows_into_callback"
    "kept:7\nabsent\nunchanged\nrenamed\n3\n" output;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  List.iter (fun target ->
    match compile_string_with_stdlib ~target (source ^ {|
(defn invalid [host active]
  (when-some [stage (:stage host)]
    (stage (assoc (:operation (:pending active)) :phase "bad"))))
(invalid enabled entry)
|}) with
    | Error _ -> ()
    | Ok _ -> failwith "nested assoc accepted an incompatible record field")
    [Lg.Target.Native; Lg.Target.Melange]

let test_assoc_accepts_protocol_constrained_named_records () =
  let source =
    {|(refer-clojure-exclude replace-value)
(defprotocol HasValue
  (read-value [value] :int))
(defrecord state [^int value ^:vector<int> items]
  HasValue
  (read-value [state] (+ (.-value state) 0)))
(defrecord other-state [^int value]
  HasValue
  (read-value [state] (+ (.-value state) 0)))
(defn add-item [^:vector<int> items ^int item]
  (conj items item))
(defn replace-value [state]
  (if (read-value state)
    (-> state
      (update :items add-item 2)
      (assoc :value 42))
    state))
(def initial (state. 1 [1]))
(let [updated (replace-value initial)]
  (println [(:value updated) (count (:items updated))]))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "assoc_accepts_protocol_constrained_named_records" "[42 2]\n"
    ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Js_of_ocaml source |> expect_ok)

