let test_inline_transient_uses_static_protocol_implementations () =
  let source =
    {|
(ns model.database)
(type-record tree [value owner write]
  (item :value))
(extend-type tree
  IEditableCollection
  (-as-transient [value] value)
  ITransientCollection
  (-conj! [value _item] value)
  (-persistent! [value] value))
