let test_nested_update_infers_optional_map_value_collections () =
  let util_source =
    {|
(ns test.util)
(def conjs (fnil conj #{}))
(defn find-value [pred xs]
  (reduce
    (fn [_ value]
      (if (pred value) (reduced value) nil))
    nil xs))
|}
  in
  let app_source =
    {|
(ns test.app
  (:require [test.util :as util]))
(type-record allocation-report
  (reverse-tempids :map<int;set<string>>))
(defn allocate [report ^string tempid eid]
  (let [reverse-tempids (:reverse-tempids report)
        tempids (get reverse-tempids eid (hash-set))]
    (assoc report :reverse-tempids
      (assoc reverse-tempids eid (conj tempids tempid)))))
(defn has-tempid? [report eid]
  (let [tempids (get (:reverse-tempids report) eid)]
    (some? (util/find-value (fn [_] true) tempids))))
(defn uncalled-has-tempid? [report eid]
  (let [tempids (get (:reverse-tempids report) eid)
        tempid  (util/find-value (fn [_] true) tempids)]
    (some? tempid)))
(def report
  (allocate
    (record allocation-report (reverse-tempids {}))
    "temp" 1))
(println (has-tempid? report 1))
|}
  in
  let compile target =
    compile_chunks_with_stdlib target
      [ ("test/util.cljc", util_source); ("test/app.cljc", app_source) ]
  in
  let ocaml_source = compile Lg.Target.Native in
  assert_ocaml_runs "nested_update_infers_optional_map_value_collections"
    "true\n" ocaml_source;
  ignore (compile Lg.Target.Melange);
  ignore (compile Lg.Target.Js_of_ocaml)

let test_if_some_get_keeps_map_storage_non_nullable () =
  let open Lg.Types in
  let key_ty = dynamic_constraint TKeyword in
  let field =
    make_field ":values" (dynamic_map key_ty (TVar "map_value"))
  in
  let target =
    typed_ir (TRecord [ field ]) (Lg.Semantic_ir.Ident "target")
  in
  let replacement =
    typed_ir
      (dynamic_map key_ty (dynamic_constraint TUnknown))
      (Lg.Semantic_ir.Ident "replacement")
  in
  (match Lg.Structural_map.assoc target [ field ] ":values" replacement with
  | Ok _ -> ()
  | Error error ->
      failwith
        ("nested unresolved map values must refine at assoc: "
       ^ error.Lg.Error.message));
  let source =
    {|
(type-record remember-row (values :map<keyword;int>))
(defn remember [^remember-row report ^:keyword key ^int value]
  (if-some [existing (get (:values report) key)]
    (do (+ existing 0) report)
    (assoc report :values (assoc (:values report) key value))))
(def result
  (remember (record remember-row (values (zipmap [:seed] [0]))) :answer 42))
(println (count (:values result)))
|}
  in
  let ocaml_source =
    compile_with_stdlib Lg.Target.Native "test/non_nullable_map_storage.cljc"
      source
  in
  assert_ocaml_runs "if_some_get_keeps_map_storage_non_nullable" "2\n"
    ocaml_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange
       "test/non_nullable_map_storage.cljc" source);
  ignore
    (compile_with_stdlib Lg.Target.Js_of_ocaml
       "test/non_nullable_map_storage.cljc" source)

let test_nullable_record_constraints_merge_across_branches () =
  let source =
