  (accessed :fn<int;bool>)
  (restore :fn<int;int>))
(defn use-storage [storage]
  (if-some [value storage]
    (let [accessed (:accessed value)]
      (accessed 1))
    false)
  (match storage
    (Some value)
    (let [restore (:restore value)]
      (restore 41))
    None 0))
