let test_source_some_and_boolean_predicates_preserve_static_contracts () =
  let source =
    {|
(ns source-predicate-app
  (:require [cljs.core :as core :refer [some? boolean?]]))

(def evaluations (atom 0))
(defn int-present? [^:int value] (some? value))
(defn string-present? [^:string value] (core/some? value))
(defn optional-present? [^:option<int> value]
  (clojure.core/some? value))
(defn optional-inc [^:option<int> value]
  (if (some? value) (inc value) 0))

(println (int-present? 1))
(println (string-present? "value"))
(println (optional-present? (Some 2)))
(println (optional-present? nil))
(println (= 3 (optional-inc (Some 2))))
(println (= 0 (optional-inc nil)))
(println (some? (do (swap! evaluations inc) nil)))
(println (core/boolean? (do (swap! evaluations inc) true)))
(println (boolean? false))
(println (clojure.core/boolean? 1))
(println (boolean? "false"))
(println (boolean? nil))
(println (= 2 @evaluations))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_predicates.cljc" source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source predicates must preserve static values";
  assert_ocaml_runs "source_some_and_boolean_predicates"
    "true\ntrue\ntrue\nfalse\ntrue\ntrue\nfalse\ntrue\ntrue\nfalse\nfalse\nfalse\ntrue\n"
    native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange "test/source_predicates.cljc" source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith "Melange source predicates must preserve static values";
  compile_with_stdlib_result Lg.Target.Native "test/some_zero_arity.cljc"
    {|(def result (some?))|}
  |> expect_error_contains "unsupported macro arity 0";
  compile_with_stdlib_result Lg.Target.Native "test/some_two_arity.cljc"
    {|(def result (some? 1 2))|}
  |> expect_error_contains "unsupported macro arity 2";
  compile_with_stdlib_result Lg.Target.Native "test/boolean_zero_arity.cljc"
    {|(def result (boolean?))|}
  |> expect_error_contains "unsupported macro arity 0";
  compile_with_stdlib_result Lg.Target.Native "test/boolean_two_arity.cljc"
    {|(def result (boolean? true false))|}
  |> expect_error_contains "unsupported macro arity 2"

let test_source_collection_and_scalar_predicates_match_clojurescript () =
  let source =
    {|
(ns source-protocol-predicate-app
  (:require [cljs.core :as core
             :refer [empty? integer? ident? counted? seqable?]]))

(def evaluations (atom 0))
(println (empty? nil))
(println (empty? []))
(println (empty? (list)))
(println (empty? ""))
(println (empty? {}))
(println (empty? #{}))
(println (core/empty? [1]))
(println (clojure.core/empty? "x"))
(println (integer? 1))
(println (integer? 1.0))
(println (core/integer? "1"))
(println (ident? :name))
(println (ident? 'name))
(println (clojure.core/ident? "name"))
(println (counted? [1]))
(println (counted? (list 1)))
(println (core/counted? (array-values 1)))
(println (counted? {}))
(println (counted? (seq [1])))
(println (seqable? nil))
(println (seqable? (array-values 1)))
(println (seqable? {}))
(println (seqable? (seq [1])))
(println (seqable? 1))
(println (empty? (do (swap! evaluations inc) [])))
(println (= 1 @evaluations))
(println (integer? (do (swap! evaluations inc) 1)))
(println (= 2 @evaluations))
(println (ident? (do (swap! evaluations inc) :name)))
(println (= 3 @evaluations))
(println (counted? (do (swap! evaluations inc) [1])))
(println (= 4 @evaluations))
(println (seqable? (do (swap! evaluations inc) [1])))
(println (= 5 @evaluations))
(println (= 5 @evaluations))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_protocol_predicates.cljc"
      source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source protocol predicates must preserve static values";
  assert_ocaml_runs "source_collection_and_scalar_predicates"
    "true\ntrue\ntrue\ntrue\ntrue\ntrue\nfalse\nfalse\ntrue\nfalse\nfalse\ntrue\ntrue\nfalse\ntrue\ntrue\nfalse\ntrue\nfalse\ntrue\ntrue\ntrue\ntrue\nfalse\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\ntrue\n"
    native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange
      "test/source_protocol_predicates.cljc" source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith "Melange source protocol predicates must preserve static values";
  List.iter
    (fun name ->
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_zero_arity.cljc")
        ("(def result (" ^ name ^ "))")
      |> expect_error_contains "unsupported macro arity 0";
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_two_arity.cljc")
        ("(def result (" ^ name ^ " 1 2))")
      |> expect_error_contains "unsupported macro arity 2")
    [ "empty?"; "integer?"; "ident?"; "counted?"; "seqable?" ];
