let test_source_numeric_coercions_match_clojurescript () =
  let source =
    {|
(ns source-numeric-coercion-app
  (:require
    [cljs.core :as core
     :refer [int long double byte float short unchecked-byte unchecked-char
             unchecked-short unchecked-float unchecked-double
             unchecked-int unchecked-long]]))

(def int-coercion int)
(def long-coercion core/long)
(def double-coercion clojure.core/double)
(def byte-coercion byte)
(def float-coercion core/float)
(def short-coercion short)
(def unchecked-byte-coercion core/unchecked-byte)
(def unchecked-char-coercion clojure.core/unchecked-char)
(def unchecked-short-coercion unchecked-short)
(def unchecked-float-coercion core/unchecked-float)
(def unchecked-double-coercion clojure.core/unchecked-double)
(def unchecked-int-coercion unchecked-int)
(def unchecked-long-coercion core/unchecked-long)
(def float-factors (array 2.0))
(defn multiply-double [value]
  (Float.mul (double value) (aget float-factors 0)))

(println (= 2 (int 2.9)))
(println (= -2 (long -2.9)))
(println (= 2.0 (double 2)))
(println (= 7 (byte 7)))
(println (= 1.5 (float 1.5)))
(println (= 3 (core/int 3.9)))
(println (= -3 (clojure.core/long -3.9)))
(println (= 4.0 (core/double 4)))
(println (= 5 (int-coercion 5)))
(println (= 6 (long-coercion 6)))
(println (= 7.0 (double-coercion 7)))
(println (= 8 (byte-coercion 8)))
(println (= 9.5 (float-coercion 9.5)))
(println (= 6.0 (multiply-double 3)))
(println (= 10 (short-coercion 10)))
(println (= 11 (unchecked-byte-coercion 11)))
(println (= \a (unchecked-char-coercion \a)))
(println (= 12 (unchecked-short-coercion 12)))
(println (= 13.5 (unchecked-float-coercion 13.5)))
(println (= 14.5 (unchecked-double-coercion 14.5)))
(println (= 15 (short 15)))
(println (= 16 (core/unchecked-byte 16)))
(println (= \b (clojure.core/unchecked-char \b)))
(println (= 17 (unchecked-short 17)))
(println (= 18.5 (core/unchecked-float 18.5)))
(println (= 19.5 (clojure.core/unchecked-double 19.5)))
(println (= 20 (unchecked-int 20.9)))
(println (= -21 (core/unchecked-long -21.9)))
(println (= 22 (clojure.core/unchecked-int 22.9)))
(println (= -23 (unchecked-long -23.9)))
(println (= 24 (unchecked-int-coercion 24)))
(println (= 25 (unchecked-long-coercion 25)))
|}
  in
  let expected = String.concat "" (List.init 32 (fun _ -> "true\n")) in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_numeric_coercions.cljc"
      source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source numeric coercions must not introduce dynamic dispatch";
  assert_ocaml_runs "source_numeric_coercions" expected native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange "test/source_numeric_coercions.cljc"
      source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith "Melange source numeric coercions must remain static";
  List.iter
    (fun name ->
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_source_zero_arity.cljc")
        ("(def result (" ^ name ^ "))")
      |> expect_error_contains "unsupported macro arity 0";
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_source_two_arity.cljc")
        ("(def result (" ^ name ^ " 1 2))")
      |> expect_error_contains "unsupported macro arity 2")
    [
      "int";
      "long";
      "double";
      "byte";
      "float";
      "short";
      "unchecked-byte";
      "unchecked-char";
      "unchecked-short";
      "unchecked-float";
      "unchecked-double";
      "unchecked-int";
      "unchecked-long";
    ];
  List.iter
    (fun name ->
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_source_wrong_type.cljc")
        ("(def result (" ^ name ^ " \"1\"))")
      |> expect_error_contains (name ^ " expects a numeric value"))
    [ "int"; "long"; "double" ];
  List.iter
    (fun name ->
      compile_with_stdlib_result Lg.Target.Native
        ("test/" ^ name ^ "_source_wrong_type.cljc")
        ("(def result (" ^ name ^ " \"1\"))")
      |> expect_error_contains "expects a numeric value")
    [ "unchecked-int"; "unchecked-long" ]

let test_melange_nil_numeric_coercion_matches_clojurescript () =
  let source =
    {|
(ns test.melange-nil-numeric
  (:require [clojure.core :refer [= * + - / dec inc neg? pos? println zero?]]))

(println
  (and (= 1 (+ nil 1))
       (= 1 (+ 1 nil))
       (= 1.5 (+ nil 1.5))
       (= -1 (- nil 1))
       (= 1 (- 1 nil))
       (= -1.5 (- nil 1.5))
       (= 0 (* nil 7))
       (= 0.0 (* 7.0 nil))
       (= 0 (/ nil 2))
       (= ##Inf (/ 1 nil))
       (= 1 (inc nil))
       (= -1 (dec nil))
       (not (zero? nil))
       (not (pos? nil))
       (not (neg? nil))))
|}
  in
  let generated =
    compile_with_stdlib_result Lg.Target.Melange
      "test/melange_nil_numeric.cljc" source
    |> expect_ok
  in
  if string_contains_substring generated "Runtime_dynamic" then
    failwith "Melange nil numeric coercion must remain statically typed";
  List.iter
    (fun expression ->
      match
        compile_with_stdlib_result Lg.Target.Native
          "test/native_nil_numeric_rejected.cljc" expression
      with
      | Error _ -> ()
      | Ok generated ->
          failwith
            ("Native must reject nil numeric coercion, got:\n" ^ generated))
    [
      "(+ nil 1)";
      "(- nil 1)";
      "(* nil 1)";
      "(/ nil 1)";
      "(inc nil)";
      "(dec nil)";
      "(zero? nil)";
      "(pos? nil)";
      "(neg? nil)";
    ]

