let test_doseq_uses_upstream_seqable_iteration () =
  let source =
    {|
(type-record direct-values (items :array<int>))
(def seq-calls (atom 0))
(extend-type direct-values Seqable
  (-seq [values]
    (do
      (swap! seq-calls inc)
      (array-to-seq (:items values)))))
(extend-type direct-values Reducible
  (-reduce [_ f initial]
    (f (f (f initial 1) 2) 3)))
(def values (record direct-values (items (array 1 2 3))))
(def total (atom 0))
(doseq [value values]
  (swap! total + value))
(println (str (deref total) ":" (deref seq-calls)))
|}
  in
  let ocaml_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "doseq_uses_upstream_seqable_iteration" "6:1\n"
    ocaml_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Js_of_ocaml source
    |> expect_ok)

