let test_group_by_map_entry_destructuring_preserves_named_record_keys () =
  let source =
    {|
(signature GroupKey {:symbol :symbol})
(defrecord GroupKey [symbol])
(type-record ParsedRow
  (name :GroupKey)
  (value :int))
(signature key-symbol :fn<GroupKey;symbol>)
(defn key-symbol [key] (:symbol key))
(def rows [(record ParsedRow (name (GroupKey. 'alpha)) (value 1))
           (record ParsedRow (name (GroupKey. 'alpha)) (value 2))])
(defn find-group [key] (get (group-by :name rows) key []))
(assert (= (count (find-group (GroupKey. 'alpha))) 2))
(assert (= (count (find-group (GroupKey. 'missing))) 0))
(type-record OutlineSummary (uuid :string) (title :string))
(type-record OtherOutlineSummary (uuid :string) (title :string) (extra :int))
(def ranked-summaries
  (sort (fn [[left-used left] [right-used right]]
          (let [used (compare right-used left-used)
                title (compare (:title left) (:title right))]
            (cond (not= used 0) used (not= title 0) title
                  :else (compare (:uuid left) (:uuid right)))))
        [(tuple 10 (record OutlineSummary (uuid "a") (title "A")))
         (tuple 20 (record OutlineSummary (uuid "b") (title "B")))
         (tuple 20 (record OutlineSummary (uuid "d") (title "A")))
         (tuple 20 (record OutlineSummary (uuid "c") (title "A")))]))
(assert (= (mapv (fn [[_ item]] (:uuid item)) ranked-summaries) ["c" "d" "b" "a"]))
(type-record OutlineBlock (uuid :string) (parent-id :option<string>) (order :option<string>) (created-at :int))
(defn compare-outline [left right]
  (match (tuple (:order left) (:order right))
    [(Some left-order) (Some right-order)]
    (let [order (compare left-order right-order)] (if (zero? order) (compare (:uuid left) (:uuid right)) order))
    [(Some _) None] -1 [None (Some _)] 1
    [None None] (let [order (compare (:created-at left) (:created-at right))]
                  (if (zero? order) (compare (:uuid left) (:uuid right)) order))))
(defn preorder [page-id blocks]
  (let [blocks (vec blocks)
        by-uuid (into {} (map (fn [block] (tuple (:uuid block) block)) blocks))
        children (group-by (fn [block]
                             (if-some [parent (:parent-id block)]
                               (if (or (contains? by-uuid parent) (= parent page-id)) parent page-id)
                               page-id)) blocks)]
    (loop [pending (vec (reverse (sort compare-outline (get children page-id [])))) seen #{} ordered []]
      (if (empty? pending)
        (into ordered (sort compare-outline (remove (fn [block] (contains? seen (:uuid block))) blocks)))
        (let [block (nth pending (dec (count pending))) pending (pop pending)]
          (if (contains? seen (:uuid block))
            (recur pending seen ordered)
            (recur (into pending (reverse (sort compare-outline (get children (:uuid block) []))))
                   (conj seen (:uuid block)) (conj ordered block))))))))
(defn render-outline-ids [rows]
  (mapv (fn [row] (str "block/" (:uuid row))) rows))
(assert (= (render-outline-ids [(record OutlineBlock (uuid "root") (parent-id nil) (order nil) (created-at 0))]) ["block/root"]))
(assert (= (mapv :uuid (preorder "page" [(record OutlineBlock (uuid "root") (parent-id (Some "page")) (order nil) (created-at 0))])) ["root"]))
(assert (= (count (preorder "page" [])) 0))
(assert (= (mapv :uuid (preorder "page" [(record OutlineBlock (uuid "page") (parent-id (Some "page")) (order nil) (created-at 0))])) ["page"]))
(defn block-day [block] (:created-at block))
(defn sorted-groups [blocks]
  (let [groups (group-by :parent-id blocks)
        day (fn [[page-id blocks]]
              (if-some [block (first blocks)] (block-day block) 0))
        groups (sort (fn [[left-page left-blocks] [right-page right-blocks]]
                       (compare (day (tuple left-page left-blocks))
                                (day (tuple right-page right-blocks)))) groups)]
    (vec (mapcat (fn [[page-id blocks]] blocks) groups))))
(assert (= (mapv :uuid (sorted-groups [(record OutlineBlock (uuid "root") (parent-id nil) (order nil) (created-at 0))])) ["root"]))
(assert (= (count (sorted-groups [])) 0))
(assert (= (mapv :uuid
                (sorted-groups
                 [(record OutlineBlock (uuid "late") (parent-id (Some "later")) (order nil) (created-at 20))
                  (record OutlineBlock (uuid "early") (parent-id (Some "earlier")) (order nil) (created-at 10))]))
           ["early" "late"]))
(def labels
  (for [[name branches] (group-by :name rows)]
    (str (= (key-symbol name) 'alpha) ":" (count branches))))
(println (first labels))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native
      "test/group_by_named_record_key.cljc" source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "group-by map entries must preserve named record key types";
  assert_ocaml_runs
    "group_by_map_entry_destructuring_preserves_named_record_keys"
    "true:2\n" native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange
       "test/group_by_named_record_key.cljc" source)

