let test_group_by_preserves_full_concat_elements_with_shorthand_key () =
  let source =
    {|
(ns group-by-concat-shorthand-test
  (:require [ocaml.String :as bytes]))

(type-record candidate (label :string) (value :string))
(type-record summary (uuid :string) (title :string))
(type-record block (title :string) (references :list<summary>) (tags :list<summary>))
(type-record context (pages :list<candidate>) (tags :list<candidate>))
(def empty-labels #{})

(defn duplicated-labels [candidates]
  (let [by-label (group-by #(bytes/lowercase-ascii (:label %)) candidates)]
    (into empty-labels
          (keep (fn [[label values]]
                  (when (> (count (set (map :value values))) 1)
                    label))
                by-label))))
(defn summary-candidates [summaries]
  (mapv #(record candidate (label (:title %)) (value (:uuid %))) summaries))
(defn display-duplicated [context block]
  (duplicated-labels
    (concat (:pages context) (:tags context)
            (summary-candidates (concat (:references block) (:tags block))))))

(println
  (contains?
    (display-duplicated
      (record context (pages (list)) (tags (list)))
      (record block
        (title "See [[page-uuid-1]] or [[page-uuid-2]]")
        (references (list (record summary (uuid "page-uuid-1") (title "Roadmap"))
                          (record summary (uuid "page-uuid-2") (title "roadmap"))))
        (tags (list))))
    "roadmap"))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native
      "test/group_by_concat_shorthand.cljc" source
  in
  if
    string_contains_substring native_source
      "(__lg_keyword_function_item : candidate) -> None"
    || string_contains_substring native_source
         "(__lg_keyword_function_item : t"
  then failwith "group-by bucket values lost fields through concat";
  assert_ocaml_runs
    "group_by_preserves_full_concat_elements_with_shorthand_key"
    "true\n" native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange
       "test/group_by_concat_shorthand.cljc" source)

let test_local_name_binding_does_not_inherit_core_function_type () =
  let source = {|
(ns local-name-inference-test)
(type-record field (label :string))
(defn duplicates? [values name-of]
  (loop [index 0 seen (hash-map)]
    (if (= index (count values))
      false
      (let [name (name-of (nth values index))]
        (if (contains? seen name)
          true
          (recur (inc index) (assoc seen name true)))))))
(println (duplicates? [(record field (label "a")) (record field (label "a"))] :label))
(println (duplicates? [(record field (label "a")) (record field (label "b"))] :label))
|} in
  let native_source = compile_with_stdlib Lg.Target.Native
    "test/local_name_inference.cljc" source in
  assert_ocaml_runs "local_name_binding_does_not_inherit_core_function_type"
    "true\nfalse\n" native_source;
  ignore (compile_with_stdlib Lg.Target.Melange
    "test/local_name_inference.cljc" source)

let test_incremental_record_identities_survive_include_directory_changes () =
  let sources = [
    ("record_api.cljc", {|
(ns record-api)
(type-record config (base-url :string) (graph-id :string)
  (graph-name :option<string>) (token :string))
|});
    ("record_host.cljc", {|
(ns record-host)
(type-record session (graph-id :string) (revision :int))
(type-record projection (graph-name :option<string>) (revision :int))
(type-record request (method :string) (url :string) (body :string) (token :string))
(type-record settings (appearance :string) (language :string) (spell-check :bool)
  (auto-correction :bool) (tabs :vector<string>) (base-url :string))
|});
    ("record_consumer.cljc", {|
(ns record-consumer (:require [record-api :as api] [ocaml.Stdlib :as host]))
(def config (record api/config (base-url "https://example.test") (graph-id "graph")
  (graph-name nil) (token "access")))
(host/print-endline (:base-url config))
(host/print-endline (:graph-id config))
|})
  ] in
  let compile target =
    let _, outputs =
      List.fold_left
        (fun (state, outputs) (filename, source) ->
          if filename = "record_host.cljc" then
            Lg.Ocaml_signature.add_include_dirs
              [Filename.temp_dir "lg-record-env-" ""];
          let state, output =
            Lg.Compiler.compile_chunk_with_filename ~target ~filename state source
            |> expect_ok
          in
          state, output :: outputs)
        (Lg.Compiler.empty_state, []) sources
    in
    String.concat "\n" (List.rev outputs)
  in
  let native = compile Lg.Target.Native in
  assert_ocaml_runs "incremental_record_identities_survive_include_directory_changes"
    "https://example.test\ngraph\n" native;
  ignore (compile Lg.Target.Melange)

