let test_reify_preserves_static_protocol_payload () =
  let source =
    {|
(defprotocol Value
  (-value [this]))
(defn make-value []
  (reify Value
    (-value [_] 42)))
(def value (make-value))
(println (-value value))
(println (satisfies? Value value))
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
