  assert_ocaml_runs "sorted_set_order"
    "(-1 1 2 3):(-1 0 1 2 3):(-1 0 1 3):(2 3):(2 1 -1):true:false:2:-1:4:4:true:true:(3 2 1):true:true:true:true\n"
    native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange "app/sorted_set_order.cljc" source);
