  (and (= 1 (protocol-first builtin-sequence))
       (= [2 3] (vec (protocol-rest builtin-sequence)))
       (= [2 3] (vec (protocol-next builtin-sequence)))
       (empty? (protocol-next (seq [1])))))

(deftype SourceSequence [^:seq<int> values]
  ISeq
