let test_reference_metadata_reset_and_alter_are_source_owned () =
  let source =
    {|
(ns metadata.reference-cells
  (:require [cljs.core :as core
             :refer [alter-meta! atom meta reset! reset-meta!]]))

(def cell (atom 1))
(defn metadata-entry
  [^:keyword source ^:Lg_edn_backend.t previous ^:int extra]
  (meta
   (with-meta
    {:placeholder 0}
    {:source source :previous previous :extra extra})))
(def reset-result (reset-meta! cell {:source :reset :value 1}))
(def alter-result
  (alter-meta!
   cell
   (fn [current source extra]
     (metadata-entry source (:source current) extra))
   :alter
   2))
(def qualified-result (core/reset-meta! cell {:source :qualified :value 3}))

(println
  (str (:source reset-result) ":"
       (:value reset-result) ":"
       (:source alter-result) ":"
       (:previous alter-result) ":"
       (:extra alter-result) ":"
       (:source qualified-result) ":"
       (:value (meta cell)) ":"
       (reset! cell 9) ":"
       (:source (meta cell))))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "metadata/reference_cells.cljc" source
  in
  let consumer_source = compile_string_from_stdlib source |> expect_ok in
  if string_contains_substring consumer_source "Runtime_dynamic" then
    failwith "reference metadata must not cross Runtime_dynamic";
  assert_ocaml_runs "reference_metadata_reset_and_alter_are_source_owned"
    ":reset:1::alter::reset:2::qualified:3:9::qualified\n" native_source;
  ignore
    (compile_with_stdlib Lg.Target.Melange "metadata/reference_cells.cljc"
       source)

let test_source_memoize_caches_fixed_arity_calls () =
  let source =
    {|
(ns test.source-memoize
  (:require [cljs.core :as core :refer [memoize]]))

(def zero-calls (atom 0))
(def one-calls (atom 0))
(def two-calls (atom 0))
(def three-calls (atom 0))

(def memo-zero
  (memoize
   (fn []
     (swap! zero-calls inc)
     42)))

(def memo-one
  (memoize
   (fn [^:int value]
     (swap! one-calls inc)
     (+ value 10))))

(def memo-two
  (core/memoize
   (fn [^:int value ^:string suffix]
     (swap! two-calls inc)
     (str value suffix))))

(def memo-three
  (memoize
   (fn [^:int value ^:string suffix ^:bool flag]
     (swap! three-calls inc)
     (str value suffix flag))))

(println
  (str
   (memo-zero) ":" (memo-zero) ":" (deref zero-calls) ":"
   (memo-one 5) ":" (memo-one 5) ":" (memo-one 6) ":" (deref one-calls) ":"
   (memo-two 7 "a") ":" (memo-two 7 "a") ":" (memo-two 8 "a") ":" (deref two-calls) ":"
   (memo-three 9 "b" true) ":" (memo-three 9 "b" true) ":"
   (memo-three 9 "b" false) ":" (deref three-calls)))
|}
  in
  let native_source =
    compile_with_stdlib Lg.Target.Native "test/source_memoize.cljc" source
  in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "source memoize must not use Runtime_dynamic";
  assert_ocaml_runs "source_memoize_caches_fixed_arity_calls"
    "42:42:1:15:15:16:2:7a:7a:8a:2:9btrue:9btrue:9bfalse:2\n"
    native_source;
  let melange_source =
    compile_with_stdlib Lg.Target.Melange "test/source_memoize.cljc" source
  in
  if string_contains_substring melange_source "Runtime_dynamic" then
    failwith "Melange source memoize must not use Runtime_dynamic"

