let test_reduced_predicate_preserves_generic_callback_results () =
  let source =
    {|
(defn reduce-indexed [f init xs]
  (loop [remaining (seq xs)
         acc init
         idx 0]
    (if-some [x (first remaining)]
      (let [result (f acc x idx)]
        (if (reduced? result)
          result
          (recur (next remaining) (unreduced result) (inc idx))))
      acc)))
(def total
  (reduce-indexed
    (fn [acc value index] (+ acc (* value index)))
    0
    [2 3 4]))
(def stopped
  (reduce-indexed
    (fn [acc value index]
      (if (= index 1) (reduced acc) (+ acc value)))
    0
    [2 3 4]))
(println (= 11 (unreduced total)))
(println (reduced? stopped))
(println (= 2 (unreduced stopped)))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "reduced_predicate_preserves_generic_callback_results"
    "true\ntrue\ntrue\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_generic_reduce_indexed_signature_keeps_rigid_accumulator () =
  let source =
    {|
(ns app.reduce-indexed)
(signature app.reduce-indexed/reduce-indexed [value accumulator storage]
  :fn<fn<accumulator;value;int;reducing-callback-result<accumulator>>;accumulator;seqable<value;storage>;accumulator>)
(defn reduce-indexed [f init xs]
  (let [[result _]
    (reduce
      (fn [[acc idx] x]
        (let [res (f acc x idx)]
          (if (reduced? res)
            (reduced [(unreduced res) idx])
            [(unreduced res) (inc idx)])))
      [init 0]
      xs)]
    result))
(println
  (= 11 (reduce-indexed
          (fn [acc value index] (+ acc (* value index)))
          0
          [2 3 4])))
(println
  (str
    (= 2
      (reduce-indexed
        (fn [acc value index]
          (if (= index 1) (reduced acc) (+ acc value)))
        0
        [2 3 4]))))
|}
  in
  let native_source = compile_string_with_stdlib source |> expect_ok in
  if string_contains_substring native_source "Runtime_dynamic" then
    failwith "generic reduce-indexed must not materialize dynamic storage";
  assert_ocaml_runs "generic_reduce_indexed_signature_keeps_rigid_accumulator"
    "true\ntrue\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

