  (:require [cljs.test :refer [set-env!]]))
(set-env! [1 2 3])
|}
  |> expect_error_contains "set-env!";
  compile_with_stdlib_result Lg.Target.Native
    "test/source_cljs_test_environment_bad_counter.cljc"
