  (-seq [bag] (seq-bag bag)))
(defn sum-values [items]
  (reduce + 0 items))
(type-record database
  (values :bag))
(extend-type database
  DiffLike
  (diff-like [left right]
    (+ (sum-values (:values left))
       (sum-values (:values right)))))
