let test_dependency_graph_treats_declare_macro_as_declaration () =
  let open Lg.Ast in
  let declaration =
    FList
      [
        FSymbol "declare+";
        FSymbol "pr-db";
        FVector [ FSymbol "db"; FSymbol "writer"; FSymbol "opts" ];
      ]
  in
  if Lg.Dependency_graph.provided_names declaration <> [ "pr-db" ] then
    failwith "declare+ must provide its declared name";
  if not (Lg.Dependency_graph.has_declarations [ declaration ]) then
    failwith "declare+ must participate in declaration stabilization";
  let forms =
    [
      FList
        [
          FSymbol "defmacro";
          FSymbol "declare+";
          FVector [ FSymbol "name"; FSymbol "&"; FSymbol "arglists" ];
          FList [ FSymbol "list"; FString "declare"; FSymbol "name" ];
        ];
      declaration;
      FList
        [
          FSymbol "defrecord";
          FSymbol "DB";
          FVector [];
          FSymbol "IPrintWithWriter";
          FList
            [
              FSymbol "-pr-writer";
              FVector [ FSymbol "db"; FSymbol "writer"; FSymbol "opts" ];
              FList
                [
                  FSymbol "pr-db";
                  FSymbol "db";
                  FSymbol "writer";
                  FSymbol "opts";
                ];
            ];
        ];
      FList
        [
          FSymbol "defn";
          FSymbol "pr-db";
          FVector [ FSymbol "db"; FSymbol "writer"; FSymbol "opts" ];
          FSymbol "db";
        ];
    ]
  in
  let order = Lg.Dependency_graph.stable_order forms in
  let position index =
    List.find_index (( = ) index) order |> Option.value ~default:max_int
  in
  if not (position 0 < position 1 && position 1 < position 2) then
    failwith "declare+ must follow its macro and precede declared consumers"

let test_dependency_graph_treats_typed_declare_macro_as_declaration () =
  let open Lg.Ast in
  let declaration =
    FList
      [
        FSymbol "declare+";
        FList
          [
            FSymbol "__type-hint";
            FSymbol "boolean";
            FSymbol "indexing?";
          ];
        FVector [ FSymbol "database"; FSymbol "attr" ];
      ]
  in
  if Lg.Dependency_graph.provided_names declaration <> [ "indexing?" ] then
    failwith "typed declare+ must provide its declared name";
  if not (Lg.Dependency_graph.has_declarations [ declaration ]) then
    failwith "typed declare+ must participate in declaration stabilization";
  let forms =
    [
      FList
        [
          FSymbol "defmacro";
          FSymbol "declare+";
          FVector [ FSymbol "name"; FSymbol "&"; FSymbol "arglists" ];
          FList [ FSymbol "list"; FString "declare"; FSymbol "name" ];
        ];
      declaration;
      FList
        [
          FSymbol "defn";
          FSymbol "validate-indexed";
          FVector [ FSymbol "database"; FSymbol "attr" ];
          FList
            [ FSymbol "indexing?"; FSymbol "database"; FSymbol "attr" ];
        ];
      FList
        [
          FSymbol "defn+";
          FList
            [
              FSymbol "__type-hint";
              FSymbol "boolean";
              FSymbol "indexing?";
            ];
          FVector [ FSymbol "database"; FSymbol "attr" ];
          FBool true;
        ];
    ]
  in
  let order = Lg.Dependency_graph.stable_order forms in
  let position index =
    List.find_index (( = ) index) order |> Option.value ~default:max_int
  in
  if not (position 0 < position 1 && position 1 < position 2) then
    failwith
      "typed declare+ must follow its macro and precede declared consumers"

