let test_dependency_graph_scales_linearly_for_independent_forms () =
  let open Lg.Ast in
  let form_count = 3_000 in
  let forms =
    List.init form_count (fun index ->
        FList
          [
            FSymbol "def";
            FSymbol ("value-" ^ string_of_int index);
            FInt index;
          ])
  in
  let started_at = Sys.time () in
  let order = Lg.Dependency_graph.stable_order forms in
  let elapsed = Sys.time () -. started_at in
  if order <> List.init form_count Fun.id then
    failwith "independent forms must retain source order";
  if elapsed >= 1.0 then
    failwith
      (Printf.sprintf
         "dependency ordering must scale to large source files (%.3fs)" elapsed)

let test_stabilization_ast_skips_mutual_function_bodies () =
  let open Lg.Ast in
  let forms =
    [
      FList [ FSymbol "declare"; FSymbol "left"; FSymbol "right" ];
      FList
        [
          FSymbol "defn";
          FSymbol "left";
          FVector [];
          FList [ FSymbol "right" ];
        ];
      FList
        [
          FSymbol "defn";
          FSymbol "right";
          FVector [];
          FList [ FSymbol "left" ];
        ];
      FList [ FSymbol "defn"; FSymbol "independent"; FVector []; FInt 42 ];
    ]
  in
  let evidence = Lg.Toolchain.stabilization_ast forms in
  match evidence with
  | [ _; FList (FSymbol "declare" :: names); FList [ FSymbol "declare" ]; last ] ->
      if names <> [ FSymbol "left"; FSymbol "right" ] then
        failwith "the evidence pass must retain both recursive declarations";
      if last <> FList [ FSymbol "declare" ] then
        failwith "the evidence pass must omit unrelated function bodies"
  | _ -> failwith "mutual function bodies must be omitted from evidence passes"

let test_stabilization_ast_retains_forward_definition_dependencies () =
  let open Lg.Ast in
  let helper =
    FList
      [ FSymbol "defn"; FSymbol "helper"; FVector []; FInt 42 ]
  in
  let target =
    FList
      [
        FSymbol "defn";
        FSymbol "target";
        FVector [];
        FList [ FSymbol "helper" ];
      ]
  in
  let unrelated =
    FList
      [ FSymbol "defn"; FSymbol "unrelated"; FVector []; FInt 7 ]
  in
  match
    Lg.Toolchain.stabilization_ast
      [
        FList [ FSymbol "declare"; FSymbol "target" ];
        helper;
        target;
        unrelated;
      ]
  with
  | [ _; evidence_helper; evidence_target; FList [ FSymbol "declare" ] ] ->
      if evidence_helper != helper || evidence_target != target then
        failwith
          "the evidence pass must retain forward definitions and their dependencies"
  | _ ->
      failwith
        "the evidence pass must omit definitions unrelated to forward declarations"

let test_stabilization_ast_without_forward_declarations_is_unchanged () =
  let open Lg.Ast in
  let forms =
    [
      FList
        [ FSymbol "defn"; FSymbol "first"; FVector []; FInt 1 ];
      FList
        [ FSymbol "defn"; FSymbol "second"; FVector []; FInt 2 ];
    ]
  in
  let evidence = Lg.Toolchain.stabilization_ast forms in
  if not (List.for_all2 ( == ) evidence forms) then
    failwith "files without forward declarations must keep a single full pass"

let test_stabilization_ast_skips_explicitly_signed_function_bodies () =
  let open Lg.Ast in
  let signed =
    FList
      [
        FSymbol "defn";
        FSymbol "signed";
        FVector [ FSymbol "value" ];
        FSymbol "value";
      ]
  in
  let unsigned =
    FList
      [
        FSymbol "defn";
        FSymbol "unsigned";
        FVector [ FSymbol "value" ];
        FSymbol "value";
      ]
  in
  match
    Lg.Toolchain.stabilization_ast ~signed_names:[ "user/signed" ]
      [
        FList [ FSymbol "namespace-scope"; FSymbol "user" ];
        FList [ FSymbol "declare"; FSymbol "signed" ];
        signed;
        unsigned;
      ]
  with
  | [
   _;
   _;
   FList [ FSymbol "declare"; FSymbol "signed" ];
   FList [ FSymbol "declare" ];
  ] ->
      ()
  | _ ->
      failwith
        "the evidence pass must omit a function body whose ABI has an explicit signature"

let test_stabilization_ast_keeps_other_namespace_namesakes () =
  let open Lg.Ast in
  let namesake =
    FList
      [
        FSymbol "defn";
        FSymbol "pattern";
        FVector [ FSymbol "value" ];
        FSymbol "value";
      ]
  in
  match
    Lg.Toolchain.stabilization_ast
      ~signed_names:[ "other.namespace/pattern" ]
      [
        FList
          [ FSymbol "namespace-scope"; FSymbol "current.namespace" ];
        namesake;
      ]
  with
  | [ _; evidence_namesake ] when evidence_namesake == namesake -> ()
  | _ ->
      failwith
        "a sidecar signature must not hide a namesake in another namespace"

let test_stabilization_ast_preserves_inline_signed_function_bodies () =
  let open Lg.Ast in
  let signature =
    FList
      [
        FSymbol "signature";
        FSymbol "user/signed";
        FKeyword ":fn<int;int>";
      ]
  in
  let signed =
    FList
      [
        FSymbol "defn";
        FSymbol "signed";
        FVector [ FSymbol "value" ];
        FSymbol "value";
      ]
  in
  match Lg.Toolchain.stabilization_ast [ signature; signed ] with
  | [ evidence_signature; evidence_signed ] ->
      if evidence_signature != signature || evidence_signed != signed then
        failwith
          "inline signatures must retain body evidence for inferred capabilities"
  | _ -> failwith "inline signatures and definitions must be preserved"

let test_declarations_do_not_merge_independent_functions () =
  let source =
    {|
(declare later)
(defprotocol Value
  (-value [item]))
(deftype Box [value]
  Value
  (-value [item] (.-value item)))
(defn independent [value]
  value)
(defn later [value]
  value)
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
  if string_contains_substring ocaml_source "and ((independent)[" then
    failwith
      "declare must not merge independent functions into one recursive group"

let test_typecheck_stabilizes_forward_declaration_abi () =
  let passes = ref 0 in
  let compile (state : Lg.Compiler_state.t) =
    incr passes;
    let row_arity = if !passes = 1 then 29 else 41 in
    let row_parameters =
      List.init row_arity (fun index -> Some ("'a" ^ string_of_int index))
    in
    let binding =
      Lg.Types.binding ~row_param_types:row_parameters "restore"
        (Lg.Types.TFn ([ Lg.Types.TInt ], Lg.Types.TInt))
    in
    let env = Lg.Compiler_environment.add "restore" binding state.env in
    Ok ({ state with env }, [])
  in
  let ast =
    [
      Lg.Ast.FList
        [
          Lg.Ast.FSymbol "declare";
          Lg.Ast.FSymbol "restore";
          Lg.Ast.FSymbol "helper";
        ];
      Lg.Ast.FList
        [
          Lg.Ast.FSymbol "def";
          Lg.Ast.FSymbol "restore";
          Lg.Ast.FList [ Lg.Ast.FSymbol "helper" ];
        ];
      Lg.Ast.FList
        [
          Lg.Ast.FSymbol "def";
          Lg.Ast.FSymbol "helper";
          Lg.Ast.FList [ Lg.Ast.FSymbol "restore" ];
        ];
    ]
  in
  let state, _ =
    Lg.Toolchain.stabilize_typecheck ~compile
      ~initial_state:Lg.Compiler_state.empty ast
    |> expect_ok
  in
  if !passes <> 3 then
    failwith
      ("forward declaration ABI should stabilize in three passes, got "
      ^ string_of_int !passes);
  let binding =
    Lg.Compiler_environment.find_opt "restore" state.env
    |> Option.get
  in
  if List.length binding.row_param_types <> 41 then
    failwith "the stabilized declaration ABI must be retained"

let test_typecheck_validates_full_compile_after_evidence_stabilizes () =
  let full_passes = ref 0 in
  let evidence_passes = ref 0 in
  let compile_with_row_arity passes row_arity (state : Lg.Compiler_state.t) =
    incr passes;
    let row_parameters =
      List.init row_arity (fun index -> Some ("'a" ^ string_of_int index))
    in
    let binding =
      Lg.Types.binding ~row_param_types:row_parameters "restore"
        (Lg.Types.TFn ([ Lg.Types.TInt ], Lg.Types.TInt))
    in
    let env = Lg.Compiler_environment.add "restore" binding state.env in
    Ok ({ state with env }, [])
  in
  let compile state =
    compile_with_row_arity full_passes 53 state
  in
  let compile_evidence state =
    compile_with_row_arity evidence_passes 41 state
  in
  let ast =
    [
      Lg.Ast.FList
        [ Lg.Ast.FSymbol "declare"; Lg.Ast.FSymbol "restore" ];
    ]
  in
  let state, _ =
    Lg.Toolchain.stabilize_typecheck ~compile_evidence ~compile
      ~initial_state:Lg.Compiler_state.empty ast
    |> expect_ok
  in
  if !full_passes <> 2 then
    failwith
      ("the final full compile should stabilize its own ABI, got "
      ^ string_of_int !full_passes
      ^ " full passes");
  let binding =
    Lg.Compiler_environment.find_opt "restore" state.env
    |> Option.get
  in
  if List.length binding.row_param_types <> 53 then
    failwith "the final full compile ABI must be retained"

let test_nested_simple_let_inference_visits_body_linearly () =
  let known_lookups = ref 0 in
  let lookup_function_ty name =
    if String.equal name "known" then (
      incr known_lookups;
      Ok (Lg.Types.TFn ([ Lg.Types.TInt ], Lg.Types.TInt))
    ) else Lg.Error.error ("unknown function " ^ name)
  in
  let rec nested_let depth value =
    if depth = 0 then
      Lg.Ast.FList [ Lg.Ast.FSymbol "known"; value ]
    else
      let local = "value" ^ string_of_int depth in
      Lg.Ast.FList
        [
          Lg.Ast.FSymbol "let";
          Lg.Ast.FVector [ Lg.Ast.FSymbol local; value ];
          nested_let (depth - 1) (Lg.Ast.FSymbol local);
        ]
  in
  ignore
    (Lg.Type_inference.infer_params ~lookup_function_ty
       ~lookup_protocol_constraint:(fun _ -> None)
       ~lookup_dynamic_key_record_type:(fun _ -> None)
       ~resolve_named_record:Fun.id
       [ ("input", Lg.Types.TInt) ]
       [ nested_let 6 (Lg.Ast.FSymbol "input") ]
    |> expect_ok);
  if !known_lookups > 16 then
    failwith
      ("nested simple lets should visit the body linearly, got "
      ^ string_of_int !known_lookups
      ^ " known-function lookups")

let test_local_callback_resolves_deferred_record_arguments () =
  let open Lg.Types in
  let generic =
    named_record ~type_parameters:[ "left"; "right" ] ~type_name:"datom"
      ~set_module_name:"datom_set" []
  in
  let expected, resolved =
    match generic with
    | TNamed_record record ->
        ( TNamed_record
            {
              record with
              type_arguments =
                [ Lg.Type_solver.fresh (); Lg.Type_solver.fresh () ];
            },
          TNamed_record
            {
              record with
              type_parameters = [];
              type_arguments = [];
            } )
    | _ -> failwith "expected a named record"
  in
  let params =
    [
      ("cmp", TFn ([ expected; expected ], TInt));
      ("left", TOcaml "__lg_record:Datom");
      ("right", TOcaml "__lg_record:Datom");
    ]
  in
  let resolved_arguments = ref 0 in
  ignore
    (Lg.Type_inference.infer_params
       ~expected_return_ty:(dynamic_constraint TUnknown)
       ~lookup_function_ty:(fun name ->
         Lg.Error.error ("unknown function " ^ name))
       ~lookup_protocol_constraint:(fun _ -> None)
       ~lookup_dynamic_key_record_type:(fun _ -> None)
       ~resolve_named_record:(function
         | TOcaml "__lg_record:Datom" ->
             incr resolved_arguments;
             resolved
         | ty -> ty)
       params
       [
         Lg.Ast.FList
           [
             Lg.Ast.FSymbol "cmp";
             Lg.Ast.FSymbol "left";
             Lg.Ast.FSymbol "right";
           ];
       ]
    |> expect_ok);
  if !resolved_arguments < 2 then
    failwith "local callback arguments must resolve deferred record types"

let test_unobserved_calls_do_not_precompute_argument_types () =
  let open Lg.Ast in
  let lookup_function_ty name =
    if String.equal name "consume" then
      Ok (Lg.Types.TFn ([ Lg.Types.TVector Lg.Types.TInt ], Lg.Types.TInt))
    else Lg.Error.error ("unknown function " ^ name)
  in
  let argument = FVector (List.init 64 (fun index -> FInt index)) in
  let body =
    List.init 4_000 (fun _ -> FList [ FSymbol "consume"; argument ])
  in
  let infer ?observe_call () =
    Gc.full_major ();
    let before = Gc.allocated_bytes () in
    ignore
      (Lg.Type_inference.infer_params ?observe_call ~lookup_function_ty
         ~lookup_protocol_constraint:(fun _ -> None)
         ~lookup_dynamic_key_record_type:(fun _ -> None)
         ~resolve_named_record:Fun.id [] body
      |> expect_ok);
    Gc.allocated_bytes () -. before
  in
  let unobserved = infer () in
  let observed = infer ~observe_call:(fun _ _ _ -> ()) () in
  if observed -. unobserved < 200_000. then
    failwith
      (Printf.sprintf
         "unobserved calls retained eager argument-type traversal: %.0f vs %.0f bytes"
         unobserved observed)

let test_call_observer_receives_static_argument_types () =
  let open Lg.Ast in
  let observed = ref [] in
  let lookup_function_ty name =
    if String.equal name "consume" then
      Ok
        (Lg.Types.TFn
           ([ Lg.Types.TInt; Lg.Types.TString ], Lg.Types.TInt))
    else Lg.Error.error ("unknown function " ^ name)
  in
  ignore
    (Lg.Type_inference.infer_params ~lookup_function_ty
       ~lookup_protocol_constraint:(fun _ -> None)
       ~lookup_dynamic_key_record_type:(fun _ -> None)
       ~resolve_named_record:Fun.id
       ~observe_call:(fun name _forms types -> observed := (name, types) :: !observed)
       []
       [ FList [ FSymbol "consume"; FInt 42; FString "answer" ] ]
    |> expect_ok);
  if
    not
      (List.exists
         (fun (name, types) ->
           String.equal name "consume"
           && types = [ Lg.Types.TInt; Lg.Types.TString ])
         !observed)
  then failwith "call observer did not receive the static argument types"

let test_inference_propagates_long_recursive_declarations () =
  let count = 24 in
  let declarations = List.init count (fun index ->
    Printf.sprintf "(defn chain%d [x] (chain%d x))" index (index + 1)) in
  let source = String.concat "\n" (declarations @
    [Printf.sprintf "(defn chain%d [x] (if (zero? x) 42 (chain0 (dec x))))" count;
     "(println (chain0 1))"]) in
  let allocated_before = Gc.allocated_bytes () in
  let compiled = Lg.Compiler.compile_string source |> expect_ok in
  let allocated = Gc.allocated_bytes () -. allocated_before in
  (* Includes compiler setup; repeated rebuilding of unrelated bindings used
     over 11 GB for this small recursive group. *)
  if allocated > 4_000_000_000. then
    failwith
      (Printf.sprintf "recursive declaration inference allocated %.0f bytes"
         allocated);
  assert_ocaml_runs "long_recursive_declarations" "42\n" compiled

let test_inference_propagates_long_constraint_chains () =
  let open Lg.Ast in
  let open Lg.Types in
  let name index = "v" ^ string_of_int index in
  let count = 12 in
  let body = List.init count (fun index ->
      FList [FSymbol "if"; FSymbol "flag";
        FSymbol (name index); FSymbol (name (index + 1))])
    @ [FList [FSymbol "consume"; FSymbol (name count)]] in
  let inferred = Lg.Type_inference.infer_params
      ~lookup_function_ty:(fun name -> if name = "consume"
        then Ok (TFn ([TVector TInt], TUnit)) else Lg.Error.error "unknown")
      ~lookup_protocol_constraint:(fun _ -> None)
      ~lookup_dynamic_key_record_type:(fun _ -> None)
      ~resolve_named_record:Fun.id
      (("flag", TBool) :: List.init (count + 1)
        (fun index -> (name index, TVector TUnknown))) body |> expect_ok in
  List.iter (fun (name, ty) -> if name <> "flag" && not (equal ty (TVector TInt))
    then failwith (name ^ " remained " ^ source_name ty)) inferred

let test_global_function_alias_keeps_contextual_inference () =
  let lookup_function_ty name =
    if String.equal name "known" then
      Ok (Lg.Types.TFn ([ Lg.Types.TInt ], Lg.Types.TInt))
    else Lg.Error.error ("unknown function " ^ name)
  in
  let body =
    Lg.Ast.FList
      [
        Lg.Ast.FSymbol "let";
        Lg.Ast.FVector
          [ Lg.Ast.FSymbol "f"; Lg.Ast.FSymbol "known" ];
        Lg.Ast.FList
          [ Lg.Ast.FSymbol "f"; Lg.Ast.FSymbol "input" ];
      ]
  in
  let inferred =
    Lg.Type_inference.infer_params ~lookup_function_ty
      ~lookup_protocol_constraint:(fun _ -> None)
      ~lookup_dynamic_key_record_type:(fun _ -> None)
      ~resolve_named_record:Fun.id
      [ ("input", Lg.Types.TUnknown) ] [ body ]
    |> expect_ok
  in
  match List.assoc_opt "input" inferred with
  | Some Lg.Types.TInt -> ()
  | Some ty ->
      failwith
        ("global function alias should infer int, got "
        ^ Lg.Types.source_name ty)
  | None -> failwith "global function alias lost the input parameter"

