let test_recursive_collection_result_specializes_self_calls () =
  let source =
    {|
(type-variant nested-value
  (ScalarValue :int)
  (NestedValues :vector<nested-value>))

(defn ^:vector<nested-value> expand-values [values]
  (vec
    (map
      (fn [value]
        (match value
          (ScalarValue _) value
          (NestedValues nested)
            (if-some [expanded (first (expand-values nested))]
              expanded
              value)))
      values)))

(print "ok")
|}
  in
  let ocaml_source =
    compile_with_stdlib Lg.Target.Native
      "test/recursive_collection_result.cljc" source
  in
  if string_contains_substring ocaml_source "Runtime_dynamic" then
    failwith "recursive closed collections must remain statically typed";
  assert_ocaml_runs "recursive_collection_result_specializes_self_calls" "ok"
    ocaml_source

let test_grouped_records_preserve_constructor_type () =
  let source =
    {|
(defrecord Branch [^:vector<int> vars ^:vector<int> clauses])
(defrecord Rule [^:keyword rule-name ^:vector<Branch> branches])
(defrecord Parsed
  [^:keyword source-name ^:vector<int> vars ^:vector<int> clauses])

(defn ^Parsed parse-branch [^:vector<keyword> form]
  (Parsed. (nth form 0) [] []))

(defn validate-branches
  [^:keyword name ^:vector<Branch> branches]
  (:vars (nth branches 0)))

(defn ^Branch parsed-branch [^Parsed parsed]
  (Branch. (:vars parsed) (:clauses parsed)))

(defn ^:vector<Rule> parse-rules [^:vector<vector<keyword>> forms]
  (vec
    (for [[name branches] (group-by :source-name (map parse-branch forms))
          :let [branches (mapv parsed-branch branches)]]
      (do
        (validate-branches name branches)
        (Rule. name branches)))))

(print "ok")
|}
  in
  let ocaml_source =
    compile_with_stdlib Lg.Target.Native "test/grouped_records.cljc" source
  in
  assert_ocaml_runs "grouped_records_preserve_constructor_type" "ok"
    ocaml_source

let test_typecheck_skips_replay_without_new_stabilization_evidence () =
  let passes = ref 0 in
  let protocol_id =
    Lg.Protocol_id.create ~owner:[] ~name:"CompileOnce"
  in
  let compile (state : Lg.Compiler_state.t) =
    incr passes;
    let protocols =
      Lg.Protocol_registry.declare protocol_id []
        (Lg.Compiler_environment.protocols state.env)
      |> expect_ok
    in
    let env =
      Lg.Compiler_environment.with_protocols protocols state.env
    in
    Ok ({ state with env }, [])
  in
  let ast =
    [
      Lg.Ast.FList
        [ Lg.Ast.FSymbol "def"; Lg.Ast.FSymbol "answer"; Lg.Ast.FInt 42 ];
    ]
  in
  ignore
    (Lg.Toolchain.stabilize_typecheck ~compile
       ~initial_state:Lg.Compiler_state.empty ast
    |> expect_ok);
  if !passes <> 1 then
    failwith
      ("a form without forward declarations must compile once, got "
      ^ string_of_int !passes)

let test_recursive_declared_nullable_sequence_supports_not_empty () =
  let source =
    {|
(type-variant parser-node
  MissingNode
  (ValueNode :int)
  (GroupNode :vector<parser-node>))

(declare parse-node parse-nodes)

(defn parse-seq [parse-element forms]
  (when (sequential? forms)
    (reduce
      (fn [parsed form]
        (if-let [parsed-form (parse-element form)]
          (conj parsed parsed-form)
          (reduced nil)))
      [] forms)))

(defn parse-group [forms]
  (let [parsed (parse-nodes forms)]
    (if (not-empty parsed)
      (count parsed)
      0)))

(defn parse-node [form]
  (match form
    MissingNode nil
    (ValueNode value) value
    (GroupNode forms) (parse-group forms)))

(defn parse-nodes [forms]
  (parse-seq parse-node forms))

|}
  in
  let consumer =
    {|
(println
  (str (parse-group [(ValueNode 1) (ValueNode 2)]) ":"
       (parse-group []) ":"
       (parse-group [MissingNode]) ":"
       (parse-group [(GroupNode [(ValueNode 1) (ValueNode 2)])])))
|}
  in
  let compile target =
    compile_chunks_with_stdlib target
      [ ("test/parser.cljc", source); ("test/consumer.cljc", consumer) ]
  in
  let native_source =
    compile Lg.Target.Native
  in
  let parser_source =
    substring_from native_source "type parser_node"
    |> Option.value ~default:native_source
  in
  if string_contains_substring parser_source "Runtime_dynamic" then
    failwith "recursive parser sequences must remain statically typed";
  assert_ocaml_runs "recursive_declared_nullable_sequence_supports_not_empty"
    "2:0:0:1\n" native_source;
  ignore (compile Lg.Target.Melange)

let test_nested_keyword_lookup_preserves_nullable_map_evidence () =
