  (when-some [return-map (:qreturn-map query)]
    (:type return-map))
  (when-some [return-symbols (:symbols (:qreturn-map query))]
    (Rrbvec.length return-symbols))
  true)

(defn validate-return-map-reversed [query]
  (when-some [return-symbols (:symbols (:qreturn-map query))]
    (Rrbvec.length return-symbols))
  (when-some [return-map (:qreturn-map query)]
