let test_higher_order_protocol_traversal_requires_closed_sum () =
  let source =
    {|
(defprotocol ITraversable
  (-postwalk [_ f]))

(defn postwalk [form f]
  (if (satisfies? ITraversable form)
    (f (-postwalk form f))
    (f form)))

(defrecord Placeholder []
  ITraversable
  (-postwalk [_ _f]
    (Placeholder.)))

(defrecord Variable [symbol]
  ITraversable
  (-postwalk [_ f]
    (Variable. (postwalk symbol f))))

(defn parse-placeholder [form]
  (when (= '_ form)
    (Placeholder.)))

(defn parse-variable [form]
  (when (symbol? form)
    (Variable. form)))

|}
  in
  Lg.Compiler.compile_string ~target:Lg.Target.Native source
  |> expect_error_contains
       "higher-order protocol traversal requires a closed sum type"

let test_parser_alternatives_use_closed_input_and_result_types () =
  let source =
    {|
(type-variant parse-input
  (InputSymbol :symbol)
  (InputInt :int))

(type-variant pattern-element
  PlaceholderElement
  (VariableElement :symbol)
  (ConstantSymbolElement :symbol)
  (ConstantIntElement :int))

(defn parse-placeholder [form]
  (match form
    (InputSymbol symbol)
      (when (= '_ symbol)
        PlaceholderElement)
    (InputInt _) nil))

(defn parse-variable [form]
  (match form
    (InputSymbol symbol)
      (when (= (first (name symbol)) \?)
        (VariableElement symbol))
    (InputInt _) nil))

(defn parse-constant [form]
  (match form
    (InputSymbol symbol)
      (when-not (= (first (name symbol)) \?)
        (ConstantSymbolElement symbol))
    (InputInt value)
      (ConstantIntElement value)))

(defn parse-pattern-element [form]
  (or (parse-placeholder form)
      (parse-variable form)
      (parse-constant form)))

(println
  (str (some? (parse-pattern-element (InputSymbol '_))) ":"
       (some? (parse-pattern-element (InputSymbol '?name))) ":"
       (some? (parse-pattern-element (InputInt 42)))))
|}
  in
  let native_source =
    compile_string_with_stdlib ~target:Lg.Target.Native source |> expect_ok
  in
  assert_ocaml_runs "parser_alternatives_use_closed_input_and_result_types"
    "true:true:true\n" native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

let test_parser_rule_map_allocates_anonymous_return_record () =
  let source =
    {|
(defrecord PlainSymbol [symbol])
(defrecord RuleVars [required free])
(defrecord RuleForm [^:symbol name vars clauses])

(defn parse-plain-symbol [form]
  (when (symbol? form)
    (PlainSymbol. form)))

(defn parse-rule-vars [forms]
  (RuleVars. [1] [2]))

(defn parse-clauses [_forms]
  [1])

(defn parse-seq [parse-element forms]
  (reduce
    (fn [parsed form]
      (if-let [value (parse-element form)]
        (conj parsed value)
        (reduced nil)))
    []
    forms))

(defn parse-rule [form]
  (let [name (:name form)
        vars (:vars form)
        clauses (:clauses form)
        name* (or (parse-plain-symbol name)
                  (throw (ex-info "missing name" {})))
        vars* (parse-rule-vars vars)
        clauses* (parse-clauses clauses)]
    {:name name*
     :vars vars*
     :clauses clauses*}))

(println
  (:symbol
    (:name
      (parse-rule (RuleForm. 'query ['?x] [1])))))
|}
  in
  let native_source =
    compile_string_with_stdlib ~target:Lg.Target.Native source |> expect_ok
  in
  let anonymous_types = count_generated_anonymous_record_types native_source in
  if anonymous_types <> 1 then
    failwith
      (Printf.sprintf
         "function return maps must allocate one anonymous record type, got %d"
         anonymous_types);
  assert_ocaml_runs
    "parser_rule_map_allocates_anonymous_return_record" "query\n"
    native_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok)

