  [(count (:required rule-vars)) (count (:free rule-vars))])

(defn validate-arity
  [^PlainSymbol name ^:vector<RuleBranch> branches]
  (let [vars0 (:vars (first branches))
        arity0 (rule-vars-arity vars0)]
    (doseq [branch (next branches)
            :let [vars (:vars branch)]]
