  (loop [only-left []
         only-right []
         both []
         left (seq [1])
         right (seq [2])]
    (cond
      (empty? left)
      [(not-empty only-left)
       (not-empty (into only-right right))
       (not-empty both)]

      (empty? right)
      [(not-empty (into only-left left))
       (not-empty only-right)
       (not-empty both)]

      :else
      (cond
        (= (first left) 1)
        (recur (conj only-left (first left))
               only-right
