let test_namespaced_array_macros_preserve_closed_sources () =
  let arrays_source =
    {|
(ns arrays (:refer-clojure :exclude [array? into-array asort]))
(defmacro array? [value]
  `(array-value? ~value))
(defmacro into-array [values]
  `(array-from ~values))
(defmacro asort [values cmp]
  `(let [values# ~values]
     (do
       (asort! ~cmp values#)
       values#)))
|}
  in
  let app_source =
    {|
(ns app
  (:require [arrays :as arrays]))
(deftype Entry [^int value])
(type-variant entry-source
  (EntryVector :vector<entry>)
  (EntryArray :array<entry>))
(defn compare-entries [^Entry left ^Entry right]
  (compare (.-value left) (.-value right)))
(defn normalize [source]
  (let [result
        (match source
          (EntryVector values) (arrays/into-array values)
          (EntryArray values) values)]
    (arrays/asort result compare-entries)
    result))
(def vector-source (EntryVector [(Entry. 2) (Entry. 1)]))
(def array-source (EntryArray (array (Entry. 4) (Entry. 3))))
(normalize vector-source)
(normalize array-source)
(println "ok")
|}
  in
  let ocaml_source =
    compile_chunks_with_stdlib Lg.Target.Native
      [ ("test/arrays.cljc", arrays_source); ("test/app.cljc", app_source) ]
  in
  assert_ocaml_runs
    "namespaced_array_macros_preserve_closed_sources" "ok\n" ocaml_source

