let test_protocol_witnesses_are_shared_across_call_sites () =
  let source call_count =
    let calls =
      List.init call_count (fun index ->
          Printf.sprintf "(read-box (Box. %d))" (index + 1))
      |> String.concat " "
    in
    {|
(defprotocol IReadBox
  (-read [value fallback])
  (-values [value first-value second-value]))
(defrecord Box [^int value]
  IReadBox
  (-read [box _fallback] (.-value box))
  (-values [box first-value second-value]
    (+ (.-value box) first-value second-value)))
(type-variant read-result
  (ReadValue :int)
  (ReadValues :int))
(defn read-box [box]
  [(ReadValue (-read box 0))
   (ReadValues (-values box 1 2))])
(println (count [|}
    ^ calls
    ^ {|]))
|}
  in
  let single_source = compile_string_with_stdlib (source 1) |> expect_ok in
  let repeated_source = compile_string_with_stdlib (source 8) |> expect_ok in
  let added_size = String.length repeated_source - String.length single_source in
  if added_size > 4_000 then
    failwith
      (Printf.sprintf
         "repeated protocol witnesses expanded generated code by %d bytes"
         added_size);
  assert_ocaml_runs "protocol_witnesses_are_shared_across_call_sites" "8\n"
    repeated_source;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange (source 8)
    |> expect_ok)

let test_exact_protocol_witnesses_reuse_implementation_functions () =
  let source =
    {|
(defprotocol Append
  (-append [buffer value offset length] :unit))
(extend-type :Buffer.t
  Append
  (-append [buffer value offset length]
    (Buffer.add_substring buffer value offset length)))
(defn append-ready [buffer]
  (-append buffer "ready" 0 5))
(append-ready (Buffer.create 8))
|}
  in
  let ocaml_source =
    compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok
  in
  if
    string_contains_substring ocaml_source
      "fun __lg_protocol_witness_argument_0"
  then
    failwith
      "an exact protocol witness must reuse its implementation function without eta expansion"

