let test_cross_module_seqable_callback_preserves_vector_element_type () =
  let util_source =
    {|
(ns test.util)
(type-record distinct-state
  (seen :set<int>)
  (result :vector<int>))
(defn ^:vector<int> distinct-by
  [^:fn<int;int> f ^:vector<int> coll]
  (let [state
        (reduce
      (fn [^distinct-state state ^int el]
        (let [seen (:seen state)
              result (:result state)
              key (f el)]
          (if (contains? seen key)
            state
            (record distinct-state
              (seen (conj seen key))
              (result (conj result el))))))
      (record distinct-state
        (seen (disj #{0} 0))
        (result []))
      coll)]
    (:result state)))
|}
  in
  let app_source =
    {|
(ns test.app
  (:require [test.util :as util]))
(println (= [1 2 3] (util/distinct-by #(mod % 3) [1 4 2 5 3 6])))
|}
  in
  let compile target =
    compile_chunks_with_stdlib target
      [ ("test/util.cljc", util_source); ("test/app.cljc", app_source) ]
  in
  let native_source = compile Lg.Target.Native in
  assert_ocaml_runs
    "cross_module_seqable_callback_preserves_vector_element_type" "true\n"
    native_source;
  ignore (compile Lg.Target.Melange)

let test_variadic_nested_seqable_preserves_static_witness () =
  let util_source =
    {|
(ns test.util)
(defn concatv [& collections]
  (loop [remaining collections
         result []]
    (if-some [values (first remaining)]
      (let [appended
            (loop [values-remaining (seq values)
                   appended result]
              (if-some [value (first values-remaining)]
                (recur (next values-remaining) (conj appended value))
                appended))]
        (recur (next remaining) appended))
      result)))
|}
  in
  let app_source =
    {|
(ns test.app
  (:require [test.util :as util]))
(println (= [1 2 3] (util/concatv [1] [] [2 3])))
|}
  in
  let compile target =
    compile_chunks_with_stdlib target
