    (catch (Failure message) (str "caught:" message))
    (catch _ "other")))
(println result)
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "try_catches_ocaml_exceptions" "caught:boom\n" ocaml_source

let test_try_supports_normal_results_multiple_body_forms_and_handlers () =
  let source =
    {|
(def normal
  (try
    (println "body")
    "ok"
    (catch (Invalid_argument message) (str "invalid:" message))
    (catch _ "other")))
(def invalid
  (try
    (raise (Invalid_argument "bad"))
    (catch (Failure message) (str "failure:" message))
    (catch (Invalid_argument message)
      (println "handled")
      (str "invalid:" message))))
(println (str normal ":" invalid))
(defn rethrow [value]
  (try value (catch error (throw error))))
(assert (= (rethrow 42) 42))
(assert (= (try (try (raise (Failure "original"))
                    (catch error (throw (Failure "wrapped"))))
               (catch (Failure message) message)) "wrapped"))
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs
    "try_supports_normal_results_multiple_body_forms_and_handlers"
    "body\nhandled\nok:invalid:bad\n" ocaml_source

let test_try_supports_finally_with_and_without_catch () =
  let source =
    {|
(def normal
  (try
    (println "body")
    42
    (finally (println "normal-finally"))))
(def recovered
  (try
    (raise (Failure "boom"))
    (catch (Failure message) message)
    (finally (println "caught-finally"))))
(def propagated
  (try
    (try
      (raise (Failure "again"))
      (finally (println "propagated-finally")))
    (catch (Failure message) message)))
(println (str normal ":" recovered ":" propagated))
|}
  in
  let ocaml_source = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "try_supports_finally_with_and_without_catch"
    "body\nnormal-finally\ncaught-finally\npropagated-finally\n42:boom:again\n"
    ocaml_source

let test_try_and_raise_reject_malformed_forms () =
  Lg.Compiler.compile_string {|(def value (try 42))|}
  |> expect_error "try requires at least one catch or finally clause";
  Lg.Compiler.compile_string {|(def value (try 42 (finally)))|}
  |> expect_error "finally requires a body";
  Lg.Compiler.compile_string {|(def value (try 42 (catch)))|}
  |> expect_error "catch requires a pattern and body";
  Lg.Compiler.compile_string {|(def value (try (catch _ 42)))|}
  |> expect_error "try requires a body";
  Lg.Compiler.compile_string {|(def value (raise))|}
  |> expect_error "raise expects 1 arguments";
  Lg.Compiler.compile_string {|(def value (raise 1 2))|}
  |> expect_error "raise expects 1 arguments"

let test_match_collection_rest_patterns () =
  let source = {|
(type-variant envelope (Payload :list<int>))
(defn multiple? [input]
  (match input (Payload [_ _ & _]) true _ false))
(defn tail-size [input]
  (match input (Payload [head & tail]) (+ head (count tail)) _ 0))
(println (str (multiple? (Payload (list))) ":"
              (multiple? (Payload (list 1))) ":"
              (multiple? (Payload (list 1 2))) ":"
              (multiple? (Payload (list 1 2 3))) ":"
              (tail-size (Payload (list 10 20 30)))))
(println (match [1 2 3] [head & tail] (+ head (count tail)) _ 0))
|} in
  let compiled = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "match_collection_rest_patterns" "false:false:true:true:12\n3\n" compiled;
  ignore (Lg.Compiler.compile_string ~target:Lg.Target.Melange source |> expect_ok);
  List.iter (fun pattern ->
    Lg.Compiler.compile_string ("(match (list 1) " ^ pattern ^ " 1 _ 0)")
    |> expect_error_contains "rest pattern")
    ["[head &]"; "[head & tail extra]"; "[head & &]"]

let test_catch_binding_accepts_symbol_bodies () =
  let source = {|
(def fallback "saved")
(def answer (try (raise (Failure "boom")) (catch error fallback)))
(def missing (try (Some 1) (raise (Failure "boom")) (catch error nil)))
(def multiple (try (raise (Failure "boom")) (catch error fallback "last")))
(def typed (try (raise (Failure "boom")) (catch js/Error error fallback)))
(println (str answer ":" (nil? missing) ":" multiple ":" typed))
|} in
  let compiled = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "catch_binding_symbol_bodies" "saved:true:last:saved\n" compiled;
  ignore (Lg.Compiler.compile_string ~target:Lg.Target.Melange source |> expect_ok);
  Lg.Compiler.compile_string {|(try 42 (catch js/Error error))|}
  |> expect_error "catch requires a type, binding, and body"

