let test_variant_callback_payload_unpacks_collection_evidence () =
  let source = {|
(defn inspect [value handle]
  (match value
    (tag Items items) (handle value (count (reverse items)))
    (tag Empty) 0))

(defn first-item [^:variant<Items:list<int>;Empty> value]
  (match value (tag Items items) (or (first items) 0) (tag Empty) 0))

(println (inspect (tag Items (list 7 8)) (fn [value size] (+ (first-item value) size))))
(println (inspect (tag Empty) (fn [value size] (+ (first-item value) size))))
(println (inspect (tag Items (list)) (fn [value size] (+ (first-item value) size))))
(let [calls (atom 0)]
  (println (inspect (do (swap! calls inc) (tag Items (list 3)))
                    (fn [value size] (+ (first-item value) size))))
  (println @calls))
|} in
  let output = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "variant_callback_payload_unpacks_collection_evidence" "9\n0\n0\n4\n1\n" output;
  ignore (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  List.iter (fun target ->
    match compile_string_with_stdlib ~target (source ^ {|
(inspect (tag Items (list "bad")) (fn [value size] (+ (first-item value) size)))
|}) with
    | Error _ -> ()
    | Ok _ -> failwith "variant adaptation erased the collection element type")
    [Lg.Target.Native; Lg.Target.Melange]

let test_polymorphic_variant_collection_payloads_infer_capabilities () =
  let source = {|
(defn find-field [key node]
  (match node
    (tag Assoc fields)
    (some (fn [entry]
            (match entry (tuple name value) (when (= name key) value))) fields)
    _ nil))
(println (pr-str (find-field "title" (tag Assoc (list (tuple "title" 42))))))
(println (pr-str (find-field "title" (tag Assoc [(tuple "title" "answer")]))))
(println (pr-str (find-field "missing" (tag Assoc [(tuple "title" 42)]))))
(defn choose [present]
  (if present (tag Assoc (list (tuple "title" 7))) (tag Empty)))
(println (pr-str (find-field "title" (choose true))))
(println (pr-str (find-field "title" (choose false))))
(defn nested-count [node]
  (match node (tag Box inner) (match inner (tag Items items) (count items))))
(println (nested-count (tag Box (tag Items (list 1 2 3)))))
(defn optional-value [f value]
  (match value (tag Null) nil _ (Some (f value))))
(defn lookup-entry [fields key]
  (some (fn [entry]
          (match entry (tuple name value) (when (= name key) value))) fields))
(defn required-entry [fields key]
  (match (lookup-entry fields key) (Some value) value _ (Stdlib.failwith "missing")))
(defn text-value [value] (match value (tag String text) text _ "other"))
(defn optional-field [fields key]
  (optional-value text-value (required-entry fields key)))
(println (pr-str (optional-field (list (tuple "title" (tag String "kept"))) "title")))
|} in
  let native = compile_string_with_stdlib source |> expect_ok in
  assert_ocaml_runs "variant_collection_payload_capabilities"
    "42\n\"answer\"\nnil\n7\nnil\n3\n\"kept\"\n" native;
  ignore
    (compile_string_with_stdlib ~target:Lg.Target.Melange source |> expect_ok);
  List.iter (fun target ->
    compile_string_with_stdlib ~target
      (source ^ "(find-field \"title\" (tag Assoc 42))")
    |> expect_error_contains "incompatible") [Lg.Target.Native; Lg.Target.Melange]

let test_vectors_merge_tuple_variant_rows () =
  let source = {|
(defn entries [title ready]
  [(tuple "title" (tag String title))
   (tuple "ready" (tag Bool ready))
   (tuple "pending" (tag Bool false))])
(defn describe [^:vector<tuple<string;variant<String:string;Bool:bool>>> fields]
  (reduce (fn [text [key value]]
            (str text key "=" (match value
                                 (tag String value) value
                                 (tag Bool value) (if value "yes" "no")) ";"))
          "" fields))
(println (describe (entries "note" true)))
(println (describe [(tuple "title" (tag String "direct")) (tuple "ready" (tag Bool false))]))
(defn send-fields [title ready]
  (describe [(tuple "title" (tag String title)) (tuple "ready" (tag Bool ready))]))
(println (send-fields "forward" true))
(defn describe-list [^:list<tuple<string;variant<String:string;Bool:bool>>> fields]
  (describe (vec fields)))
(defn send-list [title ready]
  (describe-list (list (tuple "title" (tag String title)) (tuple "ready" (tag Bool ready)))))
(println (send-list "list" false))
(defn send-more [title ready]
  (describe (into [(tuple "title" (tag String title))] [(tuple "ready" (tag Bool ready))])))
(println (send-more "into" true))
|} in
  let compiled = Lg.Compiler.compile_string source |> expect_ok in
  assert_ocaml_runs "vectors_merge_tuple_variant_rows"
    "title=note;ready=yes;pending=no;\ntitle=direct;ready=no;\ntitle=forward;ready=yes;\ntitle=list;ready=no;\ntitle=into;ready=yes;\n" compiled;
  ignore (Lg.Compiler.compile_string ~target:Lg.Target.Melange source |> expect_ok);
  List.iter (fun target ->
    Lg.Compiler.compile_string ~target
      (source ^ "(describe [(tuple \"bad\" (tag Bool 42))])")
    |> expect_error_contains "cannot adapt") [Lg.Target.Native; Lg.Target.Melange]

