let test_incremental_compilation_preserves_modules () =
  let stdlib = compiled_stdlib Lg.Target.Native in
  let state = stdlib.state in
  let state, module_ocaml =
    Lg.Compiler.compile_chunk state
      {|
(module Math
  (defn add2 [x] (+ x 2)))
|}
    |> expect_ok
  in
  let _state, app_ocaml =
    Lg.Compiler.compile_chunk state {|
(println (Math/add2 40))
|} |> expect_ok
  in
  assert_ocaml_runs "incremental_compilation_preserves_modules" "42\n"
    (String.concat "\n" [ stdlib.ocaml_source; module_ocaml; app_ocaml ])

let test_incremental_compilation_preserves_modules_with_ocaml_packages () =
  let compile target =
    let stdlib = compiled_stdlib target in
    let provider =
      match target with
      | Lg.Target.Native | Lg.Target.Js_of_ocaml ->
          {|
(require [ocaml.package/core]
         [ocaml.Core.Int :as int])
(module Math
  (defn magnitude-plus-two [x] (+ (int/abs x) 2)))
|}
      | Lg.Target.Melange ->
          (* Core is Native-only; use a package with actual Melange interfaces. *)
          {|
(require [ocaml.package/lg.runtime]
         [ocaml.Lg_runtime.Runtime_int :as int])
(module Math
  (defn magnitude-plus-two [^:int x] (+ (int/int-max x (- x)) 2)))
|}
    in
    let state, _provider =
      Lg.Compiler.compile_chunk_with_filename_and_diagnostics ~target
        ~filename:"math.cljc" stdlib.state provider
      |> expect_ok
    in
    ignore
      (Lg.Compiler.compile_chunk_with_filename_and_diagnostics ~target
         ~filename:"main.cljc" state
         {|(println (Math/magnitude-plus-two -40))|}
      |> expect_ok)
  in
  compile Lg.Target.Native;
  compile Lg.Target.Melange

